INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-01', 0, 'Welcome and Table of Contents: summary', 'Welcome to SS2 Biology First Term: digestion, transport, breathing, respiration, excretion and nutrient cycles, with a map of every unit. Key words: SS2 Biology - First Term, Syllabus, Table of contents.', 'welcome and table of contents: summary welcome to ss2 biology first term: digestion, transport, breathing, respiration, excretion and nutrient cycles, with a map of every unit. key words: ss2 biology - first term, syllabus, table of contents. welcome and table of contents ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-01', 1, 'Welcome to SS2 Biology - First Term', 'Welcome to SS2 Biology, First Term. This term follows the journey of food and air through the body: how food is digested and absorbed, how materials are carried by the blood, how we breathe and release energy in cells, how wastes are removed, and how nature recycles water, carbon and nitrogen. Read each unit slowly, study the pictures, and answer the short check questions at the end. Where the original lesson note had a mistake or an out-of-date number, a correction is explained in the unit.', 'welcome to ss2 biology - first term welcome to ss2 biology, first term. this term follows the journey of food and air through the body: how food is digested and absorbed, how materials are carried by the blood, how we breathe and release energy in cells, how wastes are removed, and how nature recycles water, carbon and nitrogen. read each unit slowly, study the pictures, and answer the short check questions at the end. where the original lesson note had a mistake or an out-of-date number, a correction is explained in the unit. welcome and table of contents ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-01', 2, 'Table of contents for SS2 Biology - First Term', 'Here is the plan for the term. Tick each unit when you finish it. 1; -; Welcome and table of contents. 2; 1; Nutrition and the Alimentary Canal: From Mouth to Stomach. 3; 1; The Small and Large Intestine and the Liver and Pancreas. 4; 2; Digestive Enzymes and Enzyme Specificity. 5; 2; Absorption in the Ileum and Assimilation. 6; 3; Why Organisms Need Transport Systems: Surface Area to Volume Ratio and Diffusion. 7; 3; Osmosis and Active Transport. 8; 4; The Mammalian Circulatory System and the Heart. 9; 4; Blood Vessels and the Components of Blood. 10; 6; The Respiratory System: Structure and Gas Exchange. 11; 6; The Mechanism of Breathing. 12; 8; Cellular Respiration: ATP and Aerobic Respiration. 13; 8; Anaerobic Respiration, Oxygen Debt and Fermentation. 14; 9; Excretion and the Organs That Excrete. 15; 9; The Urinary System and the Nephron. 16; 9; Water Balance, ADH and Kidney Disorders. 17; 10; Nutrient Cycling and the Water Cycle. 18; 10; The Carbon Cycle and Global Warming. 19; 10; The Nitrogen Cycle. 20; 11; First Term Revision: Connecting the Systems.', 'table of contents for ss2 biology - first term here is the plan for the term. tick each unit when you finish it. 1; -; welcome and table of contents. 2; 1; nutrition and the alimentary canal: from mouth to stomach. 3; 1; the small and large intestine and the liver and pancreas. 4; 2; digestive enzymes and enzyme specificity. 5; 2; absorption in the ileum and assimilation. 6; 3; why organisms need transport systems: surface area to volume ratio and diffusion. 7; 3; osmosis and active transport. 8; 4; the mammalian circulatory system and the heart. 9; 4; blood vessels and the components of blood. 10; 6; the respiratory system: structure and gas exchange. 11; 6; the mechanism of breathing. 12; 8; cellular respiration: atp and aerobic respiration. 13; 8; anaerobic respiration, oxygen debt and fermentation. 14; 9; excretion and the organs that excrete. 15; 9; the urinary system and the nephron. 16; 9; water balance, adh and kidney disorders. 17; 10; nutrient cycling and the water cycle. 18; 10; the carbon cycle and global warming. 19; 10; the nitrogen cycle. 20; 11; first term revision: connecting the systems. welcome and table of contents ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-02', 'Nutrition and the Alimentary Canal: From Mouth to Stomach') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-02', 0, 'Nutrition and the Alimentary Canal: From Mouth to Stomach: summary', 'The five stages of nutrition, the parts of the alimentary canal, and how the mouth, oesophagus and stomach digest food. Key words: Ingestion, Digestion, Absorption, Assimilation, Egestion, Peristalsis, Chyme.', 'nutrition and the alimentary canal: from mouth to stomach: summary the five stages of nutrition, the parts of the alimentary canal, and how the mouth, oesophagus and stomach digest food. key words: ingestion, digestion, absorption, assimilation, egestion, peristalsis, chyme. nutrition and the alimentary canal: from mouth to stomach ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-02', 1, 'The stages of nutrition', 'Nutrition is the process by which an organism takes in and uses food to support life. It has five stages. Ingestion: taking food into the body. Digestion: breaking large, insoluble food molecules into small, soluble ones that can be absorbed. Absorption: the passage of digested food from the gut into the blood and lymph. Assimilation: the use of the absorbed nutrients by the body''s cells for energy, growth and repair. Egestion: the removal of undigested food (such as cellulose fibre) as faeces. Egestion is not excretion, because the material was never part of the body''s cells.', 'the stages of nutrition nutrition is the process by which an organism takes in and uses food to support life. it has five stages. ingestion: taking food into the body. digestion: breaking large, insoluble food molecules into small, soluble ones that can be absorbed. absorption: the passage of digested food from the gut into the blood and lymph. assimilation: the use of the absorbed nutrients by the body''s cells for energy, growth and repair. egestion: the removal of undigested food (such as cellulose fibre) as faeces. egestion is not excretion, because the material was never part of the body''s cells. nutrition and the alimentary canal: from mouth to stomach ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-02', 2, 'The alimentary canal', 'The alimentary canal is a continuous muscular tube about 9 m long, from the mouth to the anus. The associated organs (salivary glands, liver, gall bladder and pancreas) add secretions.', 'the alimentary canal the alimentary canal is a continuous muscular tube about 9 m long, from the mouth to the anus. the associated organs (salivary glands, liver, gall bladder and pancreas) add secretions. nutrition and the alimentary canal: from mouth to stomach ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-02', 3, 'The mouth', 'Teeth chew food (mechanical digestion) into a soft bolus and increase its surface area for enzymes. The tongue moves food, mixes it with saliva and starts swallowing. There are three pairs of salivary glands (parotid, sublingual, submandibular). Saliva contains water (to moisten), mucin (to lubricate) and salivary amylase (ptyalin), which begins the digestion of starch into maltose.', 'the mouth teeth chew food (mechanical digestion) into a soft bolus and increase its surface area for enzymes. the tongue moves food, mixes it with saliva and starts swallowing. there are three pairs of salivary glands (parotid, sublingual, submandibular). saliva contains water (to moisten), mucin (to lubricate) and salivary amylase (ptyalin), which begins the digestion of starch into maltose. nutrition and the alimentary canal: from mouth to stomach ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-02', 4, 'The oesophagus', 'A muscular tube from the pharynx to the stomach. Peristalsis, a wave of contraction of the smooth muscle that pushes the bolus along, works even if you swallow while upside down.', 'the oesophagus a muscular tube from the pharynx to the stomach. peristalsis, a wave of contraction of the smooth muscle that pushes the bolus along, works even if you swallow while upside down. nutrition and the alimentary canal: from mouth to stomach ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-02', 5, 'The stomach', 'A J-shaped, stretchy muscular bag that stores food and mixes it. Gastric glands in its wall secrete gastric juice, which has: hydrochloric acid (pH about 1.5 to 2.0: it denatures proteins, kills most germs and activates pepsinogen to pepsin); pepsin, an enzyme that breaks proteins into shorter polypeptides; and rennin (in infants) that clots milk protein so that it stays longer. Three layers of muscle churn the food into a semi-liquid called chyme. The pyloric sphincter lets small amounts into the small intestine at a time. The stomach shows both kinds of digestion: mechanical (churning) and chemical (pepsin and acid).', 'the stomach a j-shaped, stretchy muscular bag that stores food and mixes it. gastric glands in its wall secrete gastric juice, which has: hydrochloric acid (ph about 1.5 to 2.0: it denatures proteins, kills most germs and activates pepsinogen to pepsin); pepsin, an enzyme that breaks proteins into shorter polypeptides; and rennin (in infants) that clots milk protein so that it stays longer. three layers of muscle churn the food into a semi-liquid called chyme. the pyloric sphincter lets small amounts into the small intestine at a time. the stomach shows both kinds of digestion: mechanical (churning) and chemical (pepsin and acid). nutrition and the alimentary canal: from mouth to stomach ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-02', 6, 'What happens to a piece of bread', 'In the mouth the teeth crush it and saliva wets it; amylase starts changing starch to maltose. Peristalsis carries the bolus down the oesophagus. In the stomach, the acid stops the action of salivary amylase (which needs a neutral pH). The bread is churned into chyme; the small amount of protein in bread (gluten) starts to be digested by pepsin, but starch digestion has paused.', 'what happens to a piece of bread in the mouth the teeth crush it and saliva wets it; amylase starts changing starch to maltose. peristalsis carries the bolus down the oesophagus. in the stomach, the acid stops the action of salivary amylase (which needs a neutral ph). the bread is churned into chyme; the small amount of protein in bread (gluten) starts to be digested by pepsin, but starch digestion has paused. nutrition and the alimentary canal: from mouth to stomach ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-03', 'The Small and Large Intestine and the Liver and Pancreas') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-03', 0, 'The Small and Large Intestine and the Liver and Pancreas: summary', 'The three parts of the small intestine, the large intestine, and the roles of the liver (bile) and pancreas (pancreatic juice) in digestion. Key words: Duodenum, Jejunum, Ileum, Colon, Bile, Pancreatic juice, Emulsification.', 'the small and large intestine and the liver and pancreas: summary the three parts of the small intestine, the large intestine, and the roles of the liver (bile) and pancreas (pancreatic juice) in digestion. key words: duodenum, jejunum, ileum, colon, bile, pancreatic juice, emulsification. the small and large intestine and the liver and pancreas ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-03', 1, 'The small intestine', 'The main place for digestion and absorption. It has three parts. The duodenum (about 25 cm) is C-shaped: chyme mixes with bile and pancreatic juice here and most chemical digestion is completed. The jejunum (about 2.5 m) is the middle part, where some absorption begins. The ileum (about 3.5 m) is the longest part and is specialised for absorption of digested food.', 'the small intestine the main place for digestion and absorption. it has three parts. the duodenum (about 25 cm) is c-shaped: chyme mixes with bile and pancreatic juice here and most chemical digestion is completed. the jejunum (about 2.5 m) is the middle part, where some absorption begins. the ileum (about 3.5 m) is the longest part and is specialised for absorption of digested food. the small and large intestine and the liver and pancreas ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-03', 2, 'The large intestine (colon)', 'Wider but shorter than the small intestine. It absorbs water and minerals from the undigested residue, making it solid as faeces. It contains friendly (symbiotic) bacteria that make vitamin K and some B vitamins. The rectum stores faeces until they leave through the anus.', 'the large intestine (colon) wider but shorter than the small intestine. it absorbs water and minerals from the undigested residue, making it solid as faeces. it contains friendly (symbiotic) bacteria that make vitamin k and some b vitamins. the rectum stores faeces until they leave through the anus. the small and large intestine and the liver and pancreas ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-03', 3, 'The liver and bile', 'The liver makes bile, a greenish-yellow alkaline fluid. Bile is not an enzyme. It has two jobs: (1) emulsification: bile salts break large fat droplets into tiny droplets, which increases the surface area many times so that the enzyme lipase can act quickly; (2) neutralisation: it neutralises the acid chyme from the stomach and gives the right pH (alkaline) for the pancreatic and intestinal enzymes. The gall bladder stores and concentrates bile and releases it through the bile duct into the duodenum when fat arrives.', 'the liver and bile the liver makes bile, a greenish-yellow alkaline fluid. bile is not an enzyme. it has two jobs: (1) emulsification: bile salts break large fat droplets into tiny droplets, which increases the surface area many times so that the enzyme lipase can act quickly; (2) neutralisation: it neutralises the acid chyme from the stomach and gives the right ph (alkaline) for the pancreatic and intestinal enzymes. the gall bladder stores and concentrates bile and releases it through the bile duct into the duodenum when fat arrives. the small and large intestine and the liver and pancreas ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-03', 4, 'The pancreas', 'The pancreas is both an exocrine and an endocrine gland. Its exocrine part makes pancreatic juice, which has sodium hydrogencarbonate (to neutralise acid), pancreatic amylase (digests starch), trypsin (digests proteins) and pancreatic lipase (digests fats). These enter the duodenum by the pancreatic duct. (Its endocrine part makes insulin and glucagon.)', 'the pancreas the pancreas is both an exocrine and an endocrine gland. its exocrine part makes pancreatic juice, which has sodium hydrogencarbonate (to neutralise acid), pancreatic amylase (digests starch), trypsin (digests proteins) and pancreatic lipase (digests fats). these enter the duodenum by the pancreatic duct. (its endocrine part makes insulin and glucagon.) the small and large intestine and the liver and pancreas ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-03', 5, 'Why bile matters even though it has no enzyme', 'Fat does not mix with water, so lipase can only reach the surface of large fat globules. Bile breaks the globules into a fine emulsion, so the total surface area for lipase is much larger and digestion is fast.', 'why bile matters even though it has no enzyme fat does not mix with water, so lipase can only reach the surface of large fat globules. bile breaks the globules into a fine emulsion, so the total surface area for lipase is much larger and digestion is fast. the small and large intestine and the liver and pancreas ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-04', 'Digestive Enzymes and Enzyme Specificity') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-04', 0, 'Digestive Enzymes and Enzyme Specificity: summary', 'How digestive enzymes work (hydrolysis, lock and key), a table of the main enzymes, their pH and products, and an experiment on amylase. Key words: Enzyme, Hydrolysis, Specificity, Amylase, Pepsin, Trypsin, Lipase.', 'digestive enzymes and enzyme specificity: summary how digestive enzymes work (hydrolysis, lock and key), a table of the main enzymes, their ph and products, and an experiment on amylase. key words: enzyme, hydrolysis, specificity, amylase, pepsin, trypsin, lipase. digestive enzymes and enzyme specificity ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-04', 1, 'Enzymes: the molecular scissors', 'Enzymes are biological catalysts, almost always proteins, that speed up reactions and are not used up. Digestive enzymes are hydrolases: they split large molecules by adding water (hydrolysis). Each enzyme is specific: its active site has a shape that fits only one kind of substrate, like a key in a lock. That is why starch, proteins and fats each need a different enzyme.', 'enzymes: the molecular scissors enzymes are biological catalysts, almost always proteins, that speed up reactions and are not used up. digestive enzymes are hydrolases: they split large molecules by adding water (hydrolysis). each enzyme is specific: its active site has a shape that fits only one kind of substrate, like a key in a lock. that is why starch, proteins and fats each need a different enzyme. digestive enzymes and enzyme specificity ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-04', 2, 'The main digestive enzymes', 'Study the table. Mouth; Salivary amylase (salivary glands); Starch; Maltose; About 6.7 to 7.0; stopped by stomach acid. Stomach; Pepsin (gastric glands); Proteins; Shorter peptides; About 1.5 to 2.5; made as inactive pepsinogen. Stomach (infants); Rennin; Milk protein (caseinogen); Curd (casein); Acidic; makes milk stay longer. Duodenum; Pancreatic amylase; Starch; Maltose; About 8; alkaline. Duodenum; Trypsin (pancreas); Proteins and peptides; Shorter polypeptides; Alkaline; made as inactive trypsinogen. Duodenum; Pancreatic lipase; Emulsified fats; Fatty acids and glycerol; Alkaline; needs bile. Ileum; Maltase (intestinal glands); Maltose; Glucose; Alkaline. Ileum; Sucrase; Sucrose; Glucose and fructose; Alkaline. Ileum; Lactase; Lactose; Glucose and galactose; Lack of it causes lactose intolerance. Ileum; Peptidases (erepsin); Peptides; Amino acids; Final step of protein digestion.', 'the main digestive enzymes study the table. mouth; salivary amylase (salivary glands); starch; maltose; about 6.7 to 7.0; stopped by stomach acid. stomach; pepsin (gastric glands); proteins; shorter peptides; about 1.5 to 2.5; made as inactive pepsinogen. stomach (infants); rennin; milk protein (caseinogen); curd (casein); acidic; makes milk stay longer. duodenum; pancreatic amylase; starch; maltose; about 8; alkaline. duodenum; trypsin (pancreas); proteins and peptides; shorter polypeptides; alkaline; made as inactive trypsinogen. duodenum; pancreatic lipase; emulsified fats; fatty acids and glycerol; alkaline; needs bile. ileum; maltase (intestinal glands); maltose; glucose; alkaline. ileum; sucrase; sucrose; glucose and fructose; alkaline. ileum; lactase; lactose; glucose and galactose; lack of it causes lactose intolerance. ileum; peptidases (erepsin); peptides; amino acids; final step of protein digestion. digestive enzymes and enzyme specificity ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-04', 3, 'Why are some enzymes made inactive?', 'Pepsinogen and trypsinogen are made as inactive forms so that they do not digest the cells that make them. They are activated (by acid, or by an intestinal enzyme) only inside the gut.', 'why are some enzymes made inactive? pepsinogen and trypsinogen are made as inactive forms so that they do not digest the cells that make them. they are activated (by acid, or by an intestinal enzyme) only inside the gut. digestive enzymes and enzyme specificity ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-04', 4, 'Experiment: amylase and starch', 'Aim: to show that amylase digests starch. Hypothesis: starch will disappear and sugar will appear when amylase is added. Method: mix starch solution with saliva (or amylase solution) at 37 °C. At intervals, take drops and test with iodine solution: blue-black means starch is present; brown means starch is gone. Test the mixture with Benedict''s solution and heat: an orange-brown colour shows reducing sugar (maltose). Control: starch with boiled saliva or with water gives no change. Result: the iodine test becomes negative and the Benedict''s test positive over time.', 'experiment: amylase and starch aim: to show that amylase digests starch. hypothesis: starch will disappear and sugar will appear when amylase is added. method: mix starch solution with saliva (or amylase solution) at 37 °c. at intervals, take drops and test with iodine solution: blue-black means starch is present; brown means starch is gone. test the mixture with benedict''s solution and heat: an orange-brown colour shows reducing sugar (maltose). control: starch with boiled saliva or with water gives no change. result: the iodine test becomes negative and the benedict''s test positive over time. digestive enzymes and enzyme specificity ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-05', 'Absorption in the Ileum and Assimilation') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-05', 0, 'Absorption in the Ileum and Assimilation: summary', 'The adaptations of the ileum and the villus for absorption, how nutrients are absorbed, where they go, and the role of the liver in assimilation. Key words: Villus, Lacteal, Microvilli, Hepatic portal vein, Deamination, Glycogen.', 'absorption in the ileum and assimilation: summary the adaptations of the ileum and the villus for absorption, how nutrients are absorbed, where they go, and the role of the liver in assimilation. key words: villus, lacteal, microvilli, hepatic portal vein, deamination, glycogen. absorption in the ileum and assimilation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-05', 1, 'Adaptations of the ileum', '1. Great length (over 3 m in the ileum alone). 2. Folds of Kerckring: circular folds of the wall. 3. Villi: millions of finger-like projections about 1 mm long. 4. Microvilli: the cells on each villus have a brush border of tiny projections, giving a huge extra surface. 5. A very good blood supply: every villus has a network of capillaries and a central lacteal (a lymph vessel). The epithelium is only one cell thick, so the diffusion distance is short.', 'adaptations of the ileum 1. great length (over 3 m in the ileum alone). 2. folds of kerckring: circular folds of the wall. 3. villi: millions of finger-like projections about 1 mm long. 4. microvilli: the cells on each villus have a brush border of tiny projections, giving a huge extra surface. 5. a very good blood supply: every villus has a network of capillaries and a central lacteal (a lymph vessel). the epithelium is only one cell thick, so the diffusion distance is short. absorption in the ileum and assimilation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-05', 2, 'How nutrients are absorbed', 'Simple diffusion: fatty acids, glycerol and some vitamins move down their concentration gradient. Facilitated diffusion: carrier proteins without energy (fructose). Active transport: uses ATP to move nutrients against a gradient (glucose, galactose, amino acids), so absorption is complete even when the gut has little of them.', 'how nutrients are absorbed simple diffusion: fatty acids, glycerol and some vitamins move down their concentration gradient. facilitated diffusion: carrier proteins without energy (fructose). active transport: uses atp to move nutrients against a gradient (glucose, galactose, amino acids), so absorption is complete even when the gut has little of them. absorption in the ileum and assimilation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-05', 3, 'Where absorbed products go', 'Glucose, fructose, galactose and amino acids enter the blood capillaries of the villi. These join to form the hepatic portal vein, which takes them straight to the liver. Fatty acids and glycerol diffuse into the epithelial cells, are rebuilt into triglycerides, and are packed with protein into tiny droplets called chylomicrons. These are too big for the capillaries and enter the lacteals instead. The lymph later empties into the bloodstream near the heart. If a lacteal is blocked, fat absorption is poor and fats (and fat-soluble vitamins) are lost in the faeces.', 'where absorbed products go glucose, fructose, galactose and amino acids enter the blood capillaries of the villi. these join to form the hepatic portal vein, which takes them straight to the liver. fatty acids and glycerol diffuse into the epithelial cells, are rebuilt into triglycerides, and are packed with protein into tiny droplets called chylomicrons. these are too big for the capillaries and enter the lacteals instead. the lymph later empties into the bloodstream near the heart. if a lacteal is blocked, fat absorption is poor and fats (and fat-soluble vitamins) are lost in the faeces. absorption in the ileum and assimilation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-05', 4, 'Assimilation: the role of the liver', 'Glucose control: the liver turns excess glucose into glycogen (glycogenesis) for storage, and turns glycogen back to glucose (glycogenolysis) when blood sugar is low. Amino acids: used to build body proteins. Excess amino acids cannot be stored, so the liver removes the amino group (–NH₂) (deamination) and turns it into urea, which the kidneys excrete. The rest (the carbon part) is used for energy or made into fat. Fats: the liver changes and repackages fats, makes cholesterol and breaks down old red blood cells. The liver is vital because everything absorbed from the gut (except most fat) passes through it first, so it can store, change or remove substances to keep the blood composition steady.', 'assimilation: the role of the liver glucose control: the liver turns excess glucose into glycogen (glycogenesis) for storage, and turns glycogen back to glucose (glycogenolysis) when blood sugar is low. amino acids: used to build body proteins. excess amino acids cannot be stored, so the liver removes the amino group (–nh₂) (deamination) and turns it into urea, which the kidneys excrete. the rest (the carbon part) is used for energy or made into fat. fats: the liver changes and repackages fats, makes cholesterol and breaks down old red blood cells. the liver is vital because everything absorbed from the gut (except most fat) passes through it first, so it can store, change or remove substances to keep the blood composition steady. absorption in the ileum and assimilation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-05', 5, 'Tracing a protein', 'Meat protein → pepsin (stomach) → shorter peptides → trypsin (duodenum) → peptidases (ileum) → amino acids → absorbed by active transport into the capillaries → hepatic portal vein → liver → blood → muscle cell, where the amino acids are joined to make muscle protein.', 'tracing a protein meat protein → pepsin (stomach) → shorter peptides → trypsin (duodenum) → peptidases (ileum) → amino acids → absorbed by active transport into the capillaries → hepatic portal vein → liver → blood → muscle cell, where the amino acids are joined to make muscle protein. absorption in the ileum and assimilation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-06', 'Why Organisms Need Transport Systems: Surface Area to Volume Ratio and Diffusion') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-06', 0, 'Why Organisms Need Transport Systems: Surface Area to Volume Ratio and Diffusion: summary', 'The SA:V ratio and why large organisms need transport systems, and diffusion with the factors that affect its rate. Key words: Surface area to volume ratio, Diffusion, Concentration gradient, Unicellular, Multicellular.', 'why organisms need transport systems: surface area to volume ratio and diffusion: summary the sa:v ratio and why large organisms need transport systems, and diffusion with the factors that affect its rate. key words: surface area to volume ratio, diffusion, concentration gradient, unicellular, multicellular. why organisms need transport systems: surface area to volume ratio and diffusion ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-06', 1, 'The surface area to volume ratio', 'As an object gets bigger, its volume grows faster than its surface area, so the ratio of surface area to volume (SA:V) falls. Example: a cube with 1 mm sides has a surface area of 6 mm² and a volume of 1 mm³, so SA:V = 6 : 1. If the same volume is cut into 1 000 cubes of 0.1 mm, the total surface area is 60 mm² and SA:V = 60 : 1. A cube with 10 cm sides has SA:V = 600/1 000 = 0.6 : 1.', 'the surface area to volume ratio as an object gets bigger, its volume grows faster than its surface area, so the ratio of surface area to volume (sa:v) falls. example: a cube with 1 mm sides has a surface area of 6 mm² and a volume of 1 mm³, so sa:v = 6 : 1. if the same volume is cut into 1 000 cubes of 0.1 mm, the total surface area is 60 mm² and sa:v = 60 : 1. a cube with 10 cm sides has sa:v = 600/1 000 = 0.6 : 1. why organisms need transport systems: surface area to volume ratio and diffusion ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-06', 2, 'Single-celled and many-celled organisms', 'Unicellular organisms such as Amoeba are small and have a high SA:V. Oxygen, food and wastes cross the cell membrane quickly by diffusion, and streaming of the cytoplasm (cyclosis) spreads materials inside. They need no transport system. Large multicellular organisms (humans, elephants, trees) have a low SA:V. Cells deep inside are too far from the outside for diffusion to supply them fast enough. So they have transport systems: the circulatory system in animals and xylem and phloem in plants. Flatworms are flat so that every cell is near the surface and they do not need a heart; an elephant is very big with a small SA:V and needs one.', 'single-celled and many-celled organisms unicellular organisms such as amoeba are small and have a high sa:v. oxygen, food and wastes cross the cell membrane quickly by diffusion, and streaming of the cytoplasm (cyclosis) spreads materials inside. they need no transport system. large multicellular organisms (humans, elephants, trees) have a low sa:v. cells deep inside are too far from the outside for diffusion to supply them fast enough. so they have transport systems: the circulatory system in animals and xylem and phloem in plants. flatworms are flat so that every cell is near the surface and they do not need a heart; an elephant is very big with a small sa:v and needs one. why organisms need transport systems: surface area to volume ratio and diffusion ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-06', 3, 'Diffusion', 'Diffusion is the net movement of molecules from a region of higher concentration to a region of lower concentration (down a concentration gradient). It is a passive process (no ATP) driven by the kinetic energy of the particles. Factors affecting its rate: (1) concentration gradient (the steeper, the faster); (2) temperature (higher means faster); (3) surface area (larger means more particles cross); (4) distance (shorter means faster); (5) size of molecules (smaller diffuse faster). Examples: gas exchange in alveoli; movement of neurotransmitters across a synapse; absorption of some digested food in the ileum; oxygen entering a leaf.', 'diffusion diffusion is the net movement of molecules from a region of higher concentration to a region of lower concentration (down a concentration gradient). it is a passive process (no atp) driven by the kinetic energy of the particles. factors affecting its rate: (1) concentration gradient (the steeper, the faster); (2) temperature (higher means faster); (3) surface area (larger means more particles cross); (4) distance (shorter means faster); (5) size of molecules (smaller diffuse faster). examples: gas exchange in alveoli; movement of neurotransmitters across a synapse; absorption of some digested food in the ileum; oxygen entering a leaf. why organisms need transport systems: surface area to volume ratio and diffusion ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-07', 'Osmosis and Active Transport') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-07', 0, 'Osmosis and Active Transport: summary', 'Osmosis and water potential, the effects of osmosis on animal and plant cells, active transport, and a comparison of the three transport processes. Key words: Osmosis, Water potential, Turgid, Plasmolysis, Active transport, ATP.', 'osmosis and active transport: summary osmosis and water potential, the effects of osmosis on animal and plant cells, active transport, and a comparison of the three transport processes. key words: osmosis, water potential, turgid, plasmolysis, active transport, atp. osmosis and active transport ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-07', 1, 'Osmosis', 'Osmosis is the net movement of water molecules from a region of higher water potential (a dilute solution) to a region of lower water potential (a concentrated solution) through a selectively permeable membrane. Pure water has the highest water potential (Ψ = 0); adding solute lowers it (makes it more negative). Osmosis is passive.', 'osmosis osmosis is the net movement of water molecules from a region of higher water potential (a dilute solution) to a region of lower water potential (a concentrated solution) through a selectively permeable membrane. pure water has the highest water potential (ψ = 0); adding solute lowers it (makes it more negative). osmosis is passive. osmosis and active transport ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-07', 2, 'Osmosis in animal cells (red blood cells)', 'Isotonic solution (same water potential as the cell): the cell stays normal. Hypotonic solution (outside more dilute): water enters, the cell swells and may burst (lysis). Hypertonic solution (outside more concentrated): water leaves and the cell shrinks and becomes spiky (crenation).', 'osmosis in animal cells (red blood cells) isotonic solution (same water potential as the cell): the cell stays normal. hypotonic solution (outside more dilute): water enters, the cell swells and may burst (lysis). hypertonic solution (outside more concentrated): water leaves and the cell shrinks and becomes spiky (crenation). osmosis and active transport ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-07', 3, 'Osmosis in plant cells', 'In a hypotonic solution (such as pure water), water enters, the cytoplasm pushes on the strong cell wall and the cell becomes turgid. This supports non-woody plants. In a hypertonic solution, water leaves the vacuole, the cytoplasm shrinks away from the wall (plasmolysis) and the plant wilts. Examples: a dried apricot swells in pure water because its cells take up water by osmosis. A fresh cucumber in concentrated salt water becomes limp because water leaves its cells by osmosis.', 'osmosis in plant cells in a hypotonic solution (such as pure water), water enters, the cytoplasm pushes on the strong cell wall and the cell becomes turgid. this supports non-woody plants. in a hypertonic solution, water leaves the vacuole, the cytoplasm shrinks away from the wall (plasmolysis) and the plant wilts. examples: a dried apricot swells in pure water because its cells take up water by osmosis. a fresh cucumber in concentrated salt water becomes limp because water leaves its cells by osmosis. osmosis and active transport ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-07', 4, 'Active transport', 'Active transport is the movement of substances from a region of lower concentration to a region of higher concentration, against the gradient. It needs energy (ATP from respiration) and specific carrier proteins in the membrane, which act as pumps and change shape to carry the substance across. Examples: the sodium-potassium pump (needed for nerve impulses); uptake of mineral ions by root hair cells (soil water is very dilute, so ions must be pumped in); reabsorption of glucose and amino acids in the kidney tubules; absorption of glucose in the ileum.', 'active transport active transport is the movement of substances from a region of lower concentration to a region of higher concentration, against the gradient. it needs energy (atp from respiration) and specific carrier proteins in the membrane, which act as pumps and change shape to carry the substance across. examples: the sodium-potassium pump (needed for nerve impulses); uptake of mineral ions by root hair cells (soil water is very dilute, so ions must be pumped in); reabsorption of glucose and amino acids in the kidney tubules; absorption of glucose in the ileum. osmosis and active transport ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-07', 5, 'Comparison', 'Study the table. What moves; Any particle (gases, solutes); Water only; Specific ions or molecules. Direction; Down the concentration gradient; Down the water potential gradient; Against the gradient. Membrane; Not essential; Selectively permeable; With carrier proteins. Energy (ATP); No; No; Yes. Saturation; No (rate rises with the gradient); No; Yes (limited by the number of carriers).', 'comparison study the table. what moves; any particle (gases, solutes); water only; specific ions or molecules. direction; down the concentration gradient; down the water potential gradient; against the gradient. membrane; not essential; selectively permeable; with carrier proteins. energy (atp); no; no; yes. saturation; no (rate rises with the gradient); no; yes (limited by the number of carriers). osmosis and active transport ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-08', 'The Mammalian Circulatory System and the Heart') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-08', 0, 'The Mammalian Circulatory System and the Heart: summary', 'Closed double circulation, the structure of the heart, valves and the cardiac cycle. Key words: Double circulation, Atrium, Ventricle, Valves, Cardiac cycle, Coronary artery.', 'the mammalian circulatory system and the heart: summary closed double circulation, the structure of the heart, valves and the cardiac cycle. key words: double circulation, atrium, ventricle, valves, cardiac cycle, coronary artery. the mammalian circulatory system and the heart ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-08', 1, 'Closed, double circulation', 'Mammals have a closed circulatory system: blood stays inside vessels (arteries, veins and capillaries), so blood pressure is high and flow can be controlled. It is a double circulation: the blood passes through the heart twice in each circuit of the body. Pulmonary circulation: right side of the heart → lungs → left side of the heart (for gas exchange). Systemic circulation: left side of the heart → body tissues → right side of the heart (delivers oxygen and nutrients and removes wastes).', 'closed, double circulation mammals have a closed circulatory system: blood stays inside vessels (arteries, veins and capillaries), so blood pressure is high and flow can be controlled. it is a double circulation: the blood passes through the heart twice in each circuit of the body. pulmonary circulation: right side of the heart → lungs → left side of the heart (for gas exchange). systemic circulation: left side of the heart → body tissues → right side of the heart (delivers oxygen and nutrients and removes wastes). the mammalian circulatory system and the heart ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-08', 2, 'The heart', 'A four-chambered muscular organ in the chest, slightly to the left, protected by the ribs. Atria (upper chambers, thin walls) receive blood. The right atrium receives deoxygenated blood from the body through the vena cava. The left atrium receives oxygenated blood from the lungs through the pulmonary veins. Ventricles (lower chambers, thick walls) pump blood out. The right ventricle pumps blood to the lungs through the pulmonary artery. The left ventricle pumps blood to the whole body through the aorta, and has the thickest wall because it must push blood through the long systemic circuit at high pressure. Valves: atrioventricular valves (tricuspid on the right with 3 flaps, bicuspid or mitral on the left with 2 flaps) stop blood flowing back into the atria. Semilunar valves at the base of the pulmonary artery and aorta stop blood flowing back into the ventricles.', 'the heart a four-chambered muscular organ in the chest, slightly to the left, protected by the ribs. atria (upper chambers, thin walls) receive blood. the right atrium receives deoxygenated blood from the body through the vena cava. the left atrium receives oxygenated blood from the lungs through the pulmonary veins. ventricles (lower chambers, thick walls) pump blood out. the right ventricle pumps blood to the lungs through the pulmonary artery. the left ventricle pumps blood to the whole body through the aorta, and has the thickest wall because it must push blood through the long systemic circuit at high pressure. valves: atrioventricular valves (tricuspid on the right with 3 flaps, bicuspid or mitral on the left with 2 flaps) stop blood flowing back into the atria. semilunar valves at the base of the pulmonary artery and aorta stop blood flowing back into the ventricles. the mammalian circulatory system and the heart ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-08', 3, 'The cardiac cycle', 'One heartbeat takes about 0.8 s. (a) Atrial systole: the atria contract and push blood into the ventricles. (b) Ventricular systole: the ventricles contract; the AV valves shut (''lub''); the semilunar valves open and blood is pushed into the arteries. (c) Diastole: all chambers relax; the semilunar valves shut (''dub''); the heart refills from the veins. The coronary arteries, the first branches of the aorta, supply the heart muscle itself with blood. A blockage causes a heart attack (myocardial infarction).', 'the cardiac cycle one heartbeat takes about 0.8 s. (a) atrial systole: the atria contract and push blood into the ventricles. (b) ventricular systole: the ventricles contract; the av valves shut (''lub''); the semilunar valves open and blood is pushed into the arteries. (c) diastole: all chambers relax; the semilunar valves shut (''dub''); the heart refills from the veins. the coronary arteries, the first branches of the aorta, supply the heart muscle itself with blood. a blockage causes a heart attack (myocardial infarction). the mammalian circulatory system and the heart ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-08', 4, 'Tracing the blood', 'Right ventricle → pulmonary artery → lungs → pulmonary vein → left atrium → bicuspid valve → left ventricle → aorta → body → vena cava → right atrium → tricuspid valve → right ventricle.', 'tracing the blood right ventricle → pulmonary artery → lungs → pulmonary vein → left atrium → bicuspid valve → left ventricle → aorta → body → vena cava → right atrium → tricuspid valve → right ventricle. the mammalian circulatory system and the heart ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-09', 'Blood Vessels and the Components of Blood') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-09', 0, 'Blood Vessels and the Components of Blood: summary', 'Arteries, veins and capillaries compared, and plasma, red cells, white cells and platelets with blood clotting. Key words: Artery, Vein, Capillary, Plasma, Haemoglobin, Phagocyte, Platelet.', 'blood vessels and the components of blood: summary arteries, veins and capillaries compared, and plasma, red cells, white cells and platelets with blood clotting. key words: artery, vein, capillary, plasma, haemoglobin, phagocyte, platelet. blood vessels and the components of blood ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-09', 1, 'Blood vessels', 'The structure of each vessel suits its job. Function; Carries blood away from the heart; Exchange with tissues; Carries blood to the heart. Wall; Thick, muscular and elastic; One cell thick; Thin, less muscle. Lumen; Narrow; Just wide enough for one red cell; Wide. Blood pressure; High; Falls sharply; Low. Valves; No (except at the heart); No; Yes, to stop backflow. Blood carried; Oxygenated (except pulmonary); Mixed; Deoxygenated (except pulmonary).', 'blood vessels the structure of each vessel suits its job. function; carries blood away from the heart; exchange with tissues; carries blood to the heart. wall; thick, muscular and elastic; one cell thick; thin, less muscle. lumen; narrow; just wide enough for one red cell; wide. blood pressure; high; falls sharply; low. valves; no (except at the heart); no; yes, to stop backflow. blood carried; oxygenated (except pulmonary); mixed; deoxygenated (except pulmonary). blood vessels and the components of blood ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-09', 2, 'Blood', 'Blood is a connective tissue of cells in a liquid called plasma. Plasma (about 55%) is a straw-coloured liquid, 92% water. It carries blood cells, nutrients, hormones, urea, CO₂ and heat. Red blood cells (erythrocytes) have no nucleus in mammals and are packed with haemoglobin. Their biconcave shape gives a large surface area for gas exchange and makes them flexible. Haemoglobin joins reversibly with oxygen in the lungs to form oxyhaemoglobin and releases it in the tissues. White blood cells (leucocytes) are larger and have a nucleus. Phagocytes (neutrophils and macrophages) engulf and digest germs (phagocytosis): a non-specific defence. Lymphocytes give specific immunity: B cells make antibodies and T cells destroy infected body cells.', 'blood blood is a connective tissue of cells in a liquid called plasma. plasma (about 55%) is a straw-coloured liquid, 92% water. it carries blood cells, nutrients, hormones, urea, co₂ and heat. red blood cells (erythrocytes) have no nucleus in mammals and are packed with haemoglobin. their biconcave shape gives a large surface area for gas exchange and makes them flexible. haemoglobin joins reversibly with oxygen in the lungs to form oxyhaemoglobin and releases it in the tissues. white blood cells (leucocytes) are larger and have a nucleus. phagocytes (neutrophils and macrophages) engulf and digest germs (phagocytosis): a non-specific defence. lymphocytes give specific immunity: b cells make antibodies and t cells destroy infected body cells. blood vessels and the components of blood ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-09', 3, 'Platelets and clotting', 'Platelets are small cell fragments that help blood to clot. When a vessel is cut: (1) the vessel narrows (vasoconstriction); (2) platelets stick to the damaged place and form a temporary plug; (3) coagulation: chemicals released by platelets and damaged tissue change the soluble protein fibrinogen into insoluble fibrin threads, which trap red cells and form a clot. The clot stops blood loss and keeps germs out until the wound heals.', 'platelets and clotting platelets are small cell fragments that help blood to clot. when a vessel is cut: (1) the vessel narrows (vasoconstriction); (2) platelets stick to the damaged place and form a temporary plug; (3) coagulation: chemicals released by platelets and damaged tissue change the soluble protein fibrinogen into insoluble fibrin threads, which trap red cells and form a clot. the clot stops blood loss and keeps germs out until the wound heals. blood vessels and the components of blood ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-10', 'The Respiratory System: Structure and Gas Exchange') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-10', 0, 'The Respiratory System: Structure and Gas Exchange: summary', 'Breathing versus cellular respiration, the parts of the respiratory tract and how each is adapted, and the structure of the alveoli. Key words: Trachea, Bronchi, Alveoli, Epiglottis, Mucociliary escalator, Respiratory membrane.', 'the respiratory system: structure and gas exchange: summary breathing versus cellular respiration, the parts of the respiratory tract and how each is adapted, and the structure of the alveoli. key words: trachea, bronchi, alveoli, epiglottis, mucociliary escalator, respiratory membrane. the respiratory system: structure and gas exchange ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-10', 1, 'Breathing and respiration', 'Breathing (ventilation) is the movement of air into and out of the lungs; it is a physical process. Cellular respiration is the chemical release of energy from glucose in cells. They are linked: breathing brings in the oxygen that cells need for respiration and removes the carbon dioxide that respiration produces.', 'breathing and respiration breathing (ventilation) is the movement of air into and out of the lungs; it is a physical process. cellular respiration is the chemical release of energy from glucose in cells. they are linked: breathing brings in the oxygen that cells need for respiration and removes the carbon dioxide that respiration produces. the respiratory system: structure and gas exchange ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-10', 2, 'The respiratory tract', '1. Nostrils and nasal cavity: lined with hairs and ciliated mucous membrane. They filter (hairs and mucus trap dust and germs), warm (blood capillaries), moisten the air and contain the smell receptors. 2. Pharynx: a shared passage for air and food. The epiglottis, a flap of cartilage, closes over the glottis when we swallow so that food goes into the oesophagus and we do not choke. 3. Larynx (voice box): cartilage plates (the Adam''s apple is the thyroid cartilage) and the vocal cords, which vibrate to make sound; pitch depends on their tension. 4. Trachea (windpipe): 10 to 12 cm long, held open by C-shaped rings of cartilage that stop it collapsing when pressure drops during breathing in. It is lined with ciliated cells and goblet cells. Goblet cells make mucus that traps dirt; the cilia beat upwards (the mucociliary escalator) to sweep it to the throat, where it is swallowed or coughed out. 5. Bronchi and bronchioles: the trachea divides into two bronchi (one to each lung) and then into smaller bronchioles. As they get smaller, there is less cartilage and more smooth muscle, which controls the flow of air. 6. Alveoli: the bronchioles end in clusters of tiny air sacs. There are about 300 to 500 million alveoli, giving a surface area of about 70 to 100 m².', 'the respiratory tract 1. nostrils and nasal cavity: lined with hairs and ciliated mucous membrane. they filter (hairs and mucus trap dust and germs), warm (blood capillaries), moisten the air and contain the smell receptors. 2. pharynx: a shared passage for air and food. the epiglottis, a flap of cartilage, closes over the glottis when we swallow so that food goes into the oesophagus and we do not choke. 3. larynx (voice box): cartilage plates (the adam''s apple is the thyroid cartilage) and the vocal cords, which vibrate to make sound; pitch depends on their tension. 4. trachea (windpipe): 10 to 12 cm long, held open by c-shaped rings of cartilage that stop it collapsing when pressure drops during breathing in. it is lined with ciliated cells and goblet cells. goblet cells make mucus that traps dirt; the cilia beat upwards (the mucociliary escalator) to sweep it to the throat, where it is swallowed or coughed out. 5. bronchi and bronchioles: the trachea divides into two bronchi (one to each lung) and then into smaller bronchioles. as they get smaller, there is less cartilage and more smooth muscle, which controls the flow of air. 6. alveoli: the bronchioles end in clusters of tiny air sacs. there are about 300 to 500 million alveoli, giving a surface area of about 70 to 100 m². the respiratory system: structure and gas exchange ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-10', 3, 'Adaptations of the alveoli', '1. A large surface area (millions of alveoli). 2. A thin diffusion path: the alveolus wall and the capillary wall are each one cell thick, and the respiratory membrane is only about 0.5 to 1 µm thick. 3. A moist surface so that gases can dissolve. 4. A rich blood supply of capillaries, which keeps a steep concentration gradient by bringing deoxygenated blood and carrying oxygenated blood away. 5. Surfactant, a detergent-like secretion that lowers the surface tension of the fluid so that the alveoli do not collapse when we breathe out. (That is about a quarter of the area of a tennis court, packed inside your chest.)', 'adaptations of the alveoli 1. a large surface area (millions of alveoli). 2. a thin diffusion path: the alveolus wall and the capillary wall are each one cell thick, and the respiratory membrane is only about 0.5 to 1 µm thick. 3. a moist surface so that gases can dissolve. 4. a rich blood supply of capillaries, which keeps a steep concentration gradient by bringing deoxygenated blood and carrying oxygenated blood away. 5. surfactant, a detergent-like secretion that lowers the surface tension of the fluid so that the alveoli do not collapse when we breathe out. (that is about a quarter of the area of a tennis court, packed inside your chest.) the respiratory system: structure and gas exchange ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-10', 4, 'Gas exchange', 'Oxygen is at a high concentration in the alveolus and low in the blood arriving from the body, so it diffuses into the blood and joins haemoglobin. Carbon dioxide is at a higher concentration in the blood than in the alveolus, so it diffuses into the air to be breathed out.', 'gas exchange oxygen is at a high concentration in the alveolus and low in the blood arriving from the body, so it diffuses into the blood and joins haemoglobin. carbon dioxide is at a higher concentration in the blood than in the alveolus, so it diffuses into the air to be breathed out. the respiratory system: structure and gas exchange ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-11', 'The Mechanism of Breathing') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-11', 0, 'The Mechanism of Breathing: summary', 'How the diaphragm, ribs and intercostal muscles change the pressure in the chest to move air in and out, and a simple lung model. Key words: Diaphragm, Intercostal muscles, Inhalation, Exhalation, Boyle''s law, Thoracic cavity.', 'the mechanism of breathing: summary how the diaphragm, ribs and intercostal muscles change the pressure in the chest to move air in and out, and a simple lung model. key words: diaphragm, intercostal muscles, inhalation, exhalation, boyle''s law, thoracic cavity. the mechanism of breathing ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-11', 1, 'Breathing is a pressure pump', 'Air moves from a place of higher pressure to a place of lower pressure. Breathing works by changing the volume, and therefore the pressure, of the chest (thoracic) cavity. The lungs have no muscles of their own. They are pulled open and pushed shut by the diaphragm (a dome-shaped sheet of muscle under the lungs) and the intercostal muscles (between the ribs). Boyle''s law says: when the volume of a gas increases, its pressure decreases (and the other way round).', 'breathing is a pressure pump air moves from a place of higher pressure to a place of lower pressure. breathing works by changing the volume, and therefore the pressure, of the chest (thoracic) cavity. the lungs have no muscles of their own. they are pulled open and pushed shut by the diaphragm (a dome-shaped sheet of muscle under the lungs) and the intercostal muscles (between the ribs). boyle''s law says: when the volume of a gas increases, its pressure decreases (and the other way round). the mechanism of breathing ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-11', 2, 'Inhalation (breathing in): an active process', '1. The external intercostal muscles contract and pull the rib cage up and out. 2. The diaphragm contracts and flattens, moving down. 3. The volume of the thoracic cavity increases. 4. The pressure inside the lungs falls below the pressure of the air outside. 5. Air rushes in until the two pressures are equal.', 'inhalation (breathing in): an active process 1. the external intercostal muscles contract and pull the rib cage up and out. 2. the diaphragm contracts and flattens, moving down. 3. the volume of the thoracic cavity increases. 4. the pressure inside the lungs falls below the pressure of the air outside. 5. air rushes in until the two pressures are equal. the mechanism of breathing ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-11', 3, 'Exhalation (breathing out): usually passive', '1. The external intercostal muscles relax and the rib cage moves down and in (its weight and the elastic pull of the lungs help). 2. The diaphragm relaxes and returns to its dome shape. 3. The volume of the thoracic cavity decreases. 4. The pressure in the lungs rises above the outside pressure. 5. Air is pushed out. Forced exhalation, as in coughing, blowing out candles or hard exercise, is active: the internal intercostal muscles and the muscles of the abdomen contract and squeeze the air out.', 'exhalation (breathing out): usually passive 1. the external intercostal muscles relax and the rib cage moves down and in (its weight and the elastic pull of the lungs help). 2. the diaphragm relaxes and returns to its dome shape. 3. the volume of the thoracic cavity decreases. 4. the pressure in the lungs rises above the outside pressure. 5. air is pushed out. forced exhalation, as in coughing, blowing out candles or hard exercise, is active: the internal intercostal muscles and the muscles of the abdomen contract and squeeze the air out. the mechanism of breathing ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-11', 4, 'Summary table', 'Compare the two actions. Intercostal muscles; External contract; External relax. Ribs; Move up and out; Move down and in. Diaphragm; Contracts and flattens; Relaxes and domes upwards. Chest volume; Increases; Decreases. Pressure in lungs; Lower than outside; Higher than outside. Air movement; In; Out.', 'summary table compare the two actions. intercostal muscles; external contract; external relax. ribs; move up and out; move down and in. diaphragm; contracts and flattens; relaxes and domes upwards. chest volume; increases; decreases. pressure in lungs; lower than outside; higher than outside. air movement; in; out. the mechanism of breathing ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-11', 5, 'A simple lung model', 'Take a plastic bottle and cut off the base. Push a Y-shaped tube into the neck with a balloon tied on each arm (the lungs). Seal the cut end with a rubber sheet (the diaphragm). Pull the rubber sheet down: the volume inside the bottle increases, the pressure drops and the balloons inflate (inhalation). Push the sheet up: the balloons deflate (exhalation). Limit of the model: the model cannot show the ribs and intercostal muscles, and real lungs are not hollow bags but spongy tissue with millions of alveoli.', 'a simple lung model take a plastic bottle and cut off the base. push a y-shaped tube into the neck with a balloon tied on each arm (the lungs). seal the cut end with a rubber sheet (the diaphragm). pull the rubber sheet down: the volume inside the bottle increases, the pressure drops and the balloons inflate (inhalation). push the sheet up: the balloons deflate (exhalation). limit of the model: the model cannot show the ribs and intercostal muscles, and real lungs are not hollow bags but spongy tissue with millions of alveoli. the mechanism of breathing ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-12', 'Cellular Respiration: ATP and Aerobic Respiration') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-12', 0, 'Cellular Respiration: ATP and Aerobic Respiration: summary', 'ATP as the cell''s energy currency, the equation and the three stages of aerobic respiration, with a note on the exact ATP yield. Key words: ATP, Glycolysis, Krebs cycle, Electron transport chain, Mitochondria, Aerobic respiration.', 'cellular respiration: atp and aerobic respiration: summary atp as the cell''s energy currency, the equation and the three stages of aerobic respiration, with a note on the exact atp yield. key words: atp, glycolysis, krebs cycle, electron transport chain, mitochondria, aerobic respiration. cellular respiration: atp and aerobic respiration ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-12', 1, 'What is cellular respiration?', 'Cellular respiration is the controlled release of energy from food, mainly glucose, inside living cells using enzymes. The energy is stored in a molecule called ATP (adenosine triphosphate), the ''energy currency'' of the cell. Think of glucose as a large banknote and ATP as small coins that the cell can spend on moving, making proteins, active transport, nerve impulses and keeping warm. ATP/ADP cycle: ATP has three phosphate groups. When a cell needs energy, an enzyme removes the last phosphate: ATP → ADP + Pᵢ + energy. Respiration provides the energy to join the phosphate back on: ADP + Pᵢ + energy → ATP. The cell keeps recycling the same molecules.', 'what is cellular respiration? cellular respiration is the controlled release of energy from food, mainly glucose, inside living cells using enzymes. the energy is stored in a molecule called atp (adenosine triphosphate), the ''energy currency'' of the cell. think of glucose as a large banknote and atp as small coins that the cell can spend on moving, making proteins, active transport, nerve impulses and keeping warm. atp/adp cycle: atp has three phosphate groups. when a cell needs energy, an enzyme removes the last phosphate: atp → adp + pᵢ + energy. respiration provides the energy to join the phosphate back on: adp + pᵢ + energy → atp. the cell keeps recycling the same molecules. cellular respiration: atp and aerobic respiration ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-12', 2, 'Aerobic respiration: the equation', 'Word equation: glucose + oxygen → carbon dioxide + water + energy (ATP). Balanced equation: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + ATP (about 38 ATP in the school syllabus). It is an oxidation reaction. The energy released was captured from sunlight in photosynthesis and stored in glucose.', 'aerobic respiration: the equation word equation: glucose + oxygen → carbon dioxide + water + energy (atp). balanced equation: c₆h₁₂o₆ + 6o₂ → 6co₂ + 6h₂o + atp (about 38 atp in the school syllabus). it is an oxidation reaction. the energy released was captured from sunlight in photosynthesis and stored in glucose. cellular respiration: atp and aerobic respiration ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-12', 3, 'The three stages', '1. Glycolysis (cytoplasm; no oxygen needed): one glucose (6 carbons) is split into two pyruvate molecules (3 carbons each). Net gain: 2 ATP and 2 NADH. 2. Krebs cycle (matrix of the mitochondrion; needs oxygen): pyruvate is completely broken down, giving off CO₂. It makes 2 ATP and loads many NADH and FADH₂ (electron carriers). 3. Electron transport chain (inner membrane of the mitochondrion): the electrons from NADH and FADH₂ pass along a chain of proteins and release energy that pumps hydrogen ions (H⁺) across the membrane. The ions flow back through the enzyme ATP synthase, which makes about 34 ATP. Oxygen is the final electron acceptor and joins with hydrogen to make water. This is why we must breathe in oxygen.', 'the three stages 1. glycolysis (cytoplasm; no oxygen needed): one glucose (6 carbons) is split into two pyruvate molecules (3 carbons each). net gain: 2 atp and 2 nadh. 2. krebs cycle (matrix of the mitochondrion; needs oxygen): pyruvate is completely broken down, giving off co₂. it makes 2 atp and loads many nadh and fadh₂ (electron carriers). 3. electron transport chain (inner membrane of the mitochondrion): the electrons from nadh and fadh₂ pass along a chain of proteins and release energy that pumps hydrogen ions (h⁺) across the membrane. the ions flow back through the enzyme atp synthase, which makes about 34 atp. oxygen is the final electron acceptor and joins with hydrogen to make water. this is why we must breathe in oxygen. cellular respiration: atp and aerobic respiration ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-12', 4, 'A note on the ATP total', 'The figure 38 ATP is the traditional maximum used in Nigerian exams. Newer measurements show that, because of energy lost in moving molecules across the membranes, the real yield is closer to 30 to 32 ATP per glucose. For WAEC and NECO, write 38 (or 36 to 38); in higher studies use about 30 to 32. Either way, aerobic respiration gives about 15 times more ATP than anaerobic.', 'a note on the atp total the figure 38 atp is the traditional maximum used in nigerian exams. newer measurements show that, because of energy lost in moving molecules across the membranes, the real yield is closer to 30 to 32 atp per glucose. for waec and neco, write 38 (or 36 to 38); in higher studies use about 30 to 32. either way, aerobic respiration gives about 15 times more atp than anaerobic. cellular respiration: atp and aerobic respiration ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-12', 5, 'Why mitochondria are called the powerhouse', 'Cells that need a lot of energy, such as muscle cells, sperm tails and the cells of the kidney tubule, have many mitochondria. The folded inner membrane (cristae) gives a large surface area for the electron transport chain.', 'why mitochondria are called the powerhouse cells that need a lot of energy, such as muscle cells, sperm tails and the cells of the kidney tubule, have many mitochondria. the folded inner membrane (cristae) gives a large surface area for the electron transport chain. cellular respiration: atp and aerobic respiration ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-13', 'Anaerobic Respiration, Oxygen Debt and Fermentation') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-13', 0, 'Anaerobic Respiration, Oxygen Debt and Fermentation: summary', 'Respiration without oxygen in muscle and in yeast, oxygen debt, the uses of fermentation, and a comparison with aerobic respiration. Key words: Anaerobic respiration, Lactic acid, Oxygen debt, Fermentation, Ethanol, Yeast.', 'anaerobic respiration, oxygen debt and fermentation: summary respiration without oxygen in muscle and in yeast, oxygen debt, the uses of fermentation, and a comparison with aerobic respiration. key words: anaerobic respiration, lactic acid, oxygen debt, fermentation, ethanol, yeast. anaerobic respiration, oxygen debt and fermentation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-13', 1, 'Anaerobic respiration', 'Anaerobic respiration is the partial breakdown of glucose without oxygen. It takes place in the cytoplasm only and yields just 2 ATP per glucose (from glycolysis), because most of the energy stays locked in the end product.', 'anaerobic respiration anaerobic respiration is the partial breakdown of glucose without oxygen. it takes place in the cytoplasm only and yields just 2 atp per glucose (from glycolysis), because most of the energy stays locked in the end product. anaerobic respiration, oxygen debt and fermentation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-13', 2, 'In animal cells: lactic acid', 'Equation: glucose → lactic acid + 2 ATP. During hard exercise, such as a sprint, the muscles use oxygen faster than the blood can bring it. Pyruvate is changed to lactic acid. This gives NAD⁺ back to the cell, so glycolysis can carry on making ATP quickly. The lactic acid builds up and causes tiredness, pain and cramp in the muscles. Oxygen debt: after exercise we keep breathing hard and the heart beats fast. The extra oxygen is used to remove the lactic acid: the liver changes much of it back to glucose and some is oxidised completely to CO₂ and water. This extra oxygen is the oxygen debt that is being ''repaid''.', 'in animal cells: lactic acid equation: glucose → lactic acid + 2 atp. during hard exercise, such as a sprint, the muscles use oxygen faster than the blood can bring it. pyruvate is changed to lactic acid. this gives nad⁺ back to the cell, so glycolysis can carry on making atp quickly. the lactic acid builds up and causes tiredness, pain and cramp in the muscles. oxygen debt: after exercise we keep breathing hard and the heart beats fast. the extra oxygen is used to remove the lactic acid: the liver changes much of it back to glucose and some is oxidised completely to co₂ and water. this extra oxygen is the oxygen debt that is being ''repaid''. anaerobic respiration, oxygen debt and fermentation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-13', 3, 'In yeast and plants: alcoholic fermentation', 'Equation: glucose → ethanol + carbon dioxide + 2 ATP. Pyruvate first loses CO₂ to become ethanal (acetaldehyde), which is then changed to ethanol. Uses: in baking, the CO₂ makes dough rise and the alcohol evaporates in the oven. In brewing, the ethanol makes palm wine, beer and other drinks (in Nigeria, burukutu and pito also use fermentation). In industry, yeast makes ethanol for biofuel from sugar cane or cassava starch.', 'in yeast and plants: alcoholic fermentation equation: glucose → ethanol + carbon dioxide + 2 atp. pyruvate first loses co₂ to become ethanal (acetaldehyde), which is then changed to ethanol. uses: in baking, the co₂ makes dough rise and the alcohol evaporates in the oven. in brewing, the ethanol makes palm wine, beer and other drinks (in nigeria, burukutu and pito also use fermentation). in industry, yeast makes ethanol for biofuel from sugar cane or cassava starch. anaerobic respiration, oxygen debt and fermentation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-13', 4, 'Aerobic and anaerobic respiration compared', 'Study the table. Oxygen; Needed; Not needed. Site; Cytoplasm and mitochondria; Cytoplasm only. Breakdown of glucose; Complete; Partial. End products; CO₂ and water; Lactic acid (animals) or ethanol and CO₂ (yeast, plants). ATP per glucose; About 38 (30 to 32 in recent figures); 2. Can it go on for long?; Yes, for hours; Only for short bursts.', 'aerobic and anaerobic respiration compared study the table. oxygen; needed; not needed. site; cytoplasm and mitochondria; cytoplasm only. breakdown of glucose; complete; partial. end products; co₂ and water; lactic acid (animals) or ethanol and co₂ (yeast, plants). atp per glucose; about 38 (30 to 32 in recent figures); 2. can it go on for long?; yes, for hours; only for short bursts. anaerobic respiration, oxygen debt and fermentation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-13', 5, 'Is anaerobic respiration a waste of glucose?', 'It is a less efficient use of glucose, but it is very useful: it gives a quick burst of energy when oxygen is short (a sprint, escaping danger), it lets yeast and some bacteria live where there is no oxygen, and it is the basis of baking, brewing, yoghurt and bio-fuel production. So the statement is only partly true.', 'is anaerobic respiration a waste of glucose? it is a less efficient use of glucose, but it is very useful: it gives a quick burst of energy when oxygen is short (a sprint, escaping danger), it lets yeast and some bacteria live where there is no oxygen, and it is the basis of baking, brewing, yoghurt and bio-fuel production. so the statement is only partly true. anaerobic respiration, oxygen debt and fermentation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-13', 6, 'Experiment: yeast and temperature', 'Mix yeast, sugar and warm water in separate tubes kept at 10, 25, 37 and 70 °C. Count the bubbles of CO₂ per minute (or collect the gas). Result: the rate rises with temperature up to about 37 to 40 °C, then drops sharply at 70 °C, because the enzymes are denatured.', 'experiment: yeast and temperature mix yeast, sugar and warm water in separate tubes kept at 10, 25, 37 and 70 °c. count the bubbles of co₂ per minute (or collect the gas). result: the rate rises with temperature up to about 37 to 40 °c, then drops sharply at 70 °c, because the enzymes are denatured. anaerobic respiration, oxygen debt and fermentation ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-14', 'Excretion and the Organs That Excrete') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-14', 0, 'Excretion and the Organs That Excrete: summary', 'Excretion compared with egestion, and how the lungs, skin and liver remove wastes, including deamination and the breakdown of haemoglobin. Key words: Excretion, Egestion, Deamination, Urea, Bilirubin, Sweat.', 'excretion and the organs that excrete: summary excretion compared with egestion, and how the lungs, skin and liver remove wastes, including deamination and the breakdown of haemoglobin. key words: excretion, egestion, deamination, urea, bilirubin, sweat. excretion and the organs that excrete ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-14', 1, 'Excretion and egestion', 'Excretion is the removal of the waste products of metabolism (chemical reactions in cells) from the body. Examples: carbon dioxide from respiration, and urea from the breakdown of amino acids. Egestion (defecation) is the removal of undigested food, such as the fibre from yam peel, which was never part of the body''s cells. Faeces are therefore egested, not excreted (a common exam trap).', 'excretion and egestion excretion is the removal of the waste products of metabolism (chemical reactions in cells) from the body. examples: carbon dioxide from respiration, and urea from the breakdown of amino acids. egestion (defecation) is the removal of undigested food, such as the fibre from yam peel, which was never part of the body''s cells. faeces are therefore egested, not excreted (a common exam trap). excretion and the organs that excrete ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-14', 2, 'The lungs', 'Carbon dioxide and water vapour from cell respiration diffuse from the blood into the alveoli and are breathed out.', 'the lungs carbon dioxide and water vapour from cell respiration diffuse from the blood into the alveoli and are breathed out. excretion and the organs that excrete ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-14', 3, 'The skin', 'Sweat glands release sweat: water, salts (NaCl), a little urea and lactic acid. Its main job is cooling by evaporation, but it also excretes a small amount of waste.', 'the skin sweat glands release sweat: water, salts (nacl), a little urea and lactic acid. its main job is cooling by evaporation, but it also excretes a small amount of waste. excretion and the organs that excrete ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-14', 4, 'The liver: the body''s chemical factory', 'The liver does not expel wastes itself. It changes them so they can be excreted. Deamination: excess amino acids cannot be stored. The liver removes the toxic amino group (–NH₂), which is changed into ammonia (NH₃) and quickly combined with CO₂ to make urea, a much less harmful substance. The remaining carbon part is used for energy or stored as fat. Urea goes into the blood to the kidneys. Breakdown of haemoglobin: old red blood cells (they live about 120 days) are broken down in the liver and spleen. The iron is recycled to make new haemoglobin. The rest is turned into bile pigments (bilirubin), which leave in the bile into the intestine and give faeces its brown colour. In jaundice, bilirubin builds up and the skin and eyes turn yellow. Detoxification: it changes alcohol, drugs and other poisons into harmless forms for the kidneys to excrete.', 'the liver: the body''s chemical factory the liver does not expel wastes itself. it changes them so they can be excreted. deamination: excess amino acids cannot be stored. the liver removes the toxic amino group (–nh₂), which is changed into ammonia (nh₃) and quickly combined with co₂ to make urea, a much less harmful substance. the remaining carbon part is used for energy or stored as fat. urea goes into the blood to the kidneys. breakdown of haemoglobin: old red blood cells (they live about 120 days) are broken down in the liver and spleen. the iron is recycled to make new haemoglobin. the rest is turned into bile pigments (bilirubin), which leave in the bile into the intestine and give faeces its brown colour. in jaundice, bilirubin builds up and the skin and eyes turn yellow. detoxification: it changes alcohol, drugs and other poisons into harmless forms for the kidneys to excrete. excretion and the organs that excrete ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-14', 5, 'The kidneys', 'The main organs of excretion for nitrogenous waste (especially urea). They also control the water and salt content of the blood (osmoregulation), which is the next topic.', 'the kidneys the main organs of excretion for nitrogenous waste (especially urea). they also control the water and salt content of the blood (osmoregulation), which is the next topic. excretion and the organs that excrete ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-15', 'The Urinary System and the Nephron') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-15', 0, 'The Urinary System and the Nephron: summary', 'The organs of the urinary system, the structure of the nephron and the two stages of urine formation: ultrafiltration and selective reabsorption. Key words: Kidney, Ureter, Bladder, Nephron, Glomerulus, Ultrafiltration, Reabsorption.', 'the urinary system and the nephron: summary the organs of the urinary system, the structure of the nephron and the two stages of urine formation: ultrafiltration and selective reabsorption. key words: kidney, ureter, bladder, nephron, glomerulus, ultrafiltration, reabsorption. the urinary system and the nephron ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-15', 1, 'The urinary system', 'Kidneys (2): bean-shaped organs at the back of the abdomen. They filter the blood and make urine. Ureters (2): muscular tubes that carry urine to the bladder by peristalsis. Urinary bladder: a stretchy muscular bag that stores urine. Urethra: the tube that takes urine out of the body; it is longer in males than in females. Blood reaches each kidney by the renal artery and leaves by the renal vein. A kidney has an outer cortex, an inner medulla and a space called the pelvis, which leads to the ureter.', 'the urinary system kidneys (2): bean-shaped organs at the back of the abdomen. they filter the blood and make urine. ureters (2): muscular tubes that carry urine to the bladder by peristalsis. urinary bladder: a stretchy muscular bag that stores urine. urethra: the tube that takes urine out of the body; it is longer in males than in females. blood reaches each kidney by the renal artery and leaves by the renal vein. a kidney has an outer cortex, an inner medulla and a space called the pelvis, which leads to the ureter. the urinary system and the nephron ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-15', 2, 'The nephron: the working unit', 'Each kidney has about one million microscopic nephrons. 1. The Malpighian body (renal corpuscle) is the filter. It has the glomerulus (a knot of capillaries) and the Bowman''s capsule, a cup around it that collects the filtrate. 2. The renal tubule is the modifier: the proximal convoluted tubule (PCT), the loop of Henle (a U-shaped loop dipping into the medulla), the distal convoluted tubule (DCT) and the collecting duct, which takes urine to the pelvis.', 'the nephron: the working unit each kidney has about one million microscopic nephrons. 1. the malpighian body (renal corpuscle) is the filter. it has the glomerulus (a knot of capillaries) and the bowman''s capsule, a cup around it that collects the filtrate. 2. the renal tubule is the modifier: the proximal convoluted tubule (pct), the loop of henle (a u-shaped loop dipping into the medulla), the distal convoluted tubule (dct) and the collecting duct, which takes urine to the pelvis. the urinary system and the nephron ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-15', 3, 'Stage 1: ultrafiltration (in the glomerulus)', 'The afferent arteriole bringing blood in is wider than the efferent arteriole taking blood out. This makes the blood pressure inside the glomerulus very high. The pressure forces water and small molecules (urea, glucose, amino acids, salts) through the capillary wall, the basement membrane and the podocytes into the Bowman''s capsule. Blood cells and large proteins are too big to pass. The fluid is called the glomerular filtrate: it is like plasma without proteins.', 'stage 1: ultrafiltration (in the glomerulus) the afferent arteriole bringing blood in is wider than the efferent arteriole taking blood out. this makes the blood pressure inside the glomerulus very high. the pressure forces water and small molecules (urea, glucose, amino acids, salts) through the capillary wall, the basement membrane and the podocytes into the bowman''s capsule. blood cells and large proteins are too big to pass. the fluid is called the glomerular filtrate: it is like plasma without proteins. the urinary system and the nephron ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-15', 4, 'Stage 2: selective reabsorption (in the tubule)', 'More than 99% of the filtrate goes back into the blood in the capillaries around the tubule, so the body does not lose useful things. PCT: all the glucose and amino acids, vitamins and most of the ions (Na⁺, K⁺, Cl⁻) are taken back by active transport. Water then follows by osmosis (about 80%). Loop of Henle: builds up a high salt concentration in the medulla, which is needed to save water. DCT: fine-tunes the amount of salts and water, under the control of hormones. Collecting duct: the last place where water is reabsorbed, under the control of ADH.', 'stage 2: selective reabsorption (in the tubule) more than 99% of the filtrate goes back into the blood in the capillaries around the tubule, so the body does not lose useful things. pct: all the glucose and amino acids, vitamins and most of the ions (na⁺, k⁺, cl⁻) are taken back by active transport. water then follows by osmosis (about 80%). loop of henle: builds up a high salt concentration in the medulla, which is needed to save water. dct: fine-tunes the amount of salts and water, under the control of hormones. collecting duct: the last place where water is reabsorbed, under the control of adh. the urinary system and the nephron ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-15', 5, 'What is in the filtrate, and what is in urine?', 'Compare these. Proteins; Yes; No; No. Glucose; Yes; Yes; No (all reabsorbed). Amino acids; Yes; Yes; No. Urea; Yes; Yes; Yes (more concentrated). Water; Yes; Yes; Most reabsorbed. Blood cells; Yes; No; No.', 'what is in the filtrate, and what is in urine? compare these. proteins; yes; no; no. glucose; yes; yes; no (all reabsorbed). amino acids; yes; yes; no. urea; yes; yes; yes (more concentrated). water; yes; yes; most reabsorbed. blood cells; yes; no; no. the urinary system and the nephron ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-15', 6, 'A diabetes clue', 'If glucose is in the urine, the tubule could not reabsorb all of it because the blood sugar was too high. This is one sign of diabetes mellitus, and a test strip dipped in urine can detect it.', 'a diabetes clue if glucose is in the urine, the tubule could not reabsorb all of it because the blood sugar was too high. this is one sign of diabetes mellitus, and a test strip dipped in urine can detect it. the urinary system and the nephron ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-16', 'Water Balance, ADH and Kidney Disorders') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-16', 0, 'Water Balance, ADH and Kidney Disorders: summary', 'How the hormone ADH controls the water content of the blood, and kidney stones, nephritis, kidney failure, dialysis and transplants. Key words: Osmoregulation, ADH, Dehydration, Dialysis, Kidney stones, Uraemia.', 'water balance, adh and kidney disorders: summary how the hormone adh controls the water content of the blood, and kidney stones, nephritis, kidney failure, dialysis and transplants. key words: osmoregulation, adh, dehydration, dialysis, kidney stones, uraemia. water balance, adh and kidney disorders ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-16', 1, 'Osmoregulation and ADH', 'The body must keep the water content of the blood steady. The hypothalamus in the brain detects the concentration of the blood. The pituitary gland releases the hormone ADH (antidiuretic hormone) into the blood, and ADH acts on the collecting ducts in the kidney.', 'osmoregulation and adh the body must keep the water content of the blood steady. the hypothalamus in the brain detects the concentration of the blood. the pituitary gland releases the hormone adh (antidiuretic hormone) into the blood, and adh acts on the collecting ducts in the kidney. water balance, adh and kidney disorders ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-16', 2, 'When you are dehydrated', 'The blood becomes too concentrated (low water potential). The hypothalamus signals the pituitary to release more ADH. ADH makes the walls of the collecting ducts more permeable to water, so more water is drawn back into the blood by the salty medulla. The result: a small volume of dark, concentrated urine, and you also feel thirsty.', 'when you are dehydrated the blood becomes too concentrated (low water potential). the hypothalamus signals the pituitary to release more adh. adh makes the walls of the collecting ducts more permeable to water, so more water is drawn back into the blood by the salty medulla. the result: a small volume of dark, concentrated urine, and you also feel thirsty. water balance, adh and kidney disorders ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-16', 3, 'When you have drunk a lot of water', 'The blood is too dilute. Less ADH is released. The collecting ducts are less permeable, so less water is reabsorbed. The result: a large volume of pale, dilute urine. So if a person drinks a large volume of water, urine output increases. This is a negative feedback loop: the body corrects any change to bring the water level back to normal.', 'when you have drunk a lot of water the blood is too dilute. less adh is released. the collecting ducts are less permeable, so less water is reabsorbed. the result: a large volume of pale, dilute urine. so if a person drinks a large volume of water, urine output increases. this is a negative feedback loop: the body corrects any change to bring the water level back to normal. water balance, adh and kidney disorders ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-16', 4, 'Diabetes insipidus and alcohol', 'If the body makes too little ADH (diabetes insipidus), a person passes very large volumes of dilute urine and is always thirsty. Alcohol blocks the release of ADH, which is why people urinate more and become dehydrated after drinking it.', 'diabetes insipidus and alcohol if the body makes too little adh (diabetes insipidus), a person passes very large volumes of dilute urine and is always thirsty. alcohol blocks the release of adh, which is why people urinate more and become dehydrated after drinking it. water balance, adh and kidney disorders ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-16', 5, 'Disorders of the excretory system', 'Kidney stones (renal calculi): crystals of salts such as calcium oxalate form in the kidney. If they move into the ureter, they cause severe pain and may block urine flow. Prevention: drink plenty of water. Nephritis: swelling of the kidney, usually from infection or from the body''s own immune system, which damages the nephrons. Kidney (renal) failure: the kidneys can no longer filter blood and urea builds up (uraemia). Treatment: dialysis, where a machine acts as an artificial kidney, filtering the blood through a membrane, or a kidney transplant, where a healthy kidney from a matching donor replaces the failed one. A person can live with one kidney, so a living relative can donate. Ethical issues: there are too few donors, and selling organs is illegal in Nigeria and many countries. Always take medical advice.', 'disorders of the excretory system kidney stones (renal calculi): crystals of salts such as calcium oxalate form in the kidney. if they move into the ureter, they cause severe pain and may block urine flow. prevention: drink plenty of water. nephritis: swelling of the kidney, usually from infection or from the body''s own immune system, which damages the nephrons. kidney (renal) failure: the kidneys can no longer filter blood and urea builds up (uraemia). treatment: dialysis, where a machine acts as an artificial kidney, filtering the blood through a membrane, or a kidney transplant, where a healthy kidney from a matching donor replaces the failed one. a person can live with one kidney, so a living relative can donate. ethical issues: there are too few donors, and selling organs is illegal in nigeria and many countries. always take medical advice. water balance, adh and kidney disorders ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-17', 'Nutrient Cycling and the Water Cycle') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-17', 0, 'Nutrient Cycling and the Water Cycle: summary', 'Why elements are recycled, and the processes of the water cycle: evaporation, transpiration, condensation, precipitation and run-off. Key words: Biogeochemical cycle, Evaporation, Transpiration, Condensation, Precipitation, Infiltration.', 'nutrient cycling and the water cycle: summary why elements are recycled, and the processes of the water cycle: evaporation, transpiration, condensation, precipitation and run-off. key words: biogeochemical cycle, evaporation, transpiration, condensation, precipitation, infiltration. nutrient cycling and the water cycle ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-17', 1, 'Why do we need cycles?', 'The amount of matter on Earth is fixed. Nothing new arrives, so the elements that make life, such as carbon, nitrogen and water, must be used over and over again. These biogeochemical cycles show how elements move from the environment into living things and back. Without recycling, the soil would run out of nutrients and ecosystems would collapse.', 'why do we need cycles? the amount of matter on earth is fixed. nothing new arrives, so the elements that make life, such as carbon, nitrogen and water, must be used over and over again. these biogeochemical cycles show how elements move from the environment into living things and back. without recycling, the soil would run out of nutrients and ecosystems would collapse. nutrient cycling and the water cycle ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-17', 2, 'The water cycle (hydrological cycle)', 'Water moves continuously on, above and below the surface of the Earth, powered by the Sun''s energy.', 'the water cycle (hydrological cycle) water moves continuously on, above and below the surface of the earth, powered by the sun''s energy. nutrient cycling and the water cycle ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-17', 3, 'The key processes', 'Evaporation: liquid water turns to vapour, mainly from oceans, lakes and rivers. Transpiration: loss of water vapour from the leaves of plants through the stomata. Together with evaporation it is called evapotranspiration. A large tree may release hundreds of litres a day. Condensation: rising vapour cools and condenses on dust particles to form clouds. Precipitation: water falls as rain, snow, sleet or hail when droplets become too heavy. Run-off: water flows over the land into streams and rivers and back to the sea. Infiltration (percolation): water soaks into the soil and refills underground water (aquifers). We get well and borehole water from this store.', 'the key processes evaporation: liquid water turns to vapour, mainly from oceans, lakes and rivers. transpiration: loss of water vapour from the leaves of plants through the stomata. together with evaporation it is called evapotranspiration. a large tree may release hundreds of litres a day. condensation: rising vapour cools and condenses on dust particles to form clouds. precipitation: water falls as rain, snow, sleet or hail when droplets become too heavy. run-off: water flows over the land into streams and rivers and back to the sea. infiltration (percolation): water soaks into the soil and refills underground water (aquifers). we get well and borehole water from this store. nutrient cycling and the water cycle ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-17', 4, 'Why water matters in biology', 'Water is the universal solvent for chemical reactions, the medium of transport in blood and in xylem, and it keeps plant cells turgid. It also gives a stable temperature to cells and lakes. Human influence: cutting down forests reduces transpiration and rainfall, and paving over soil reduces infiltration and increases flooding, a serious problem in Nigerian cities during the rainy season.', 'why water matters in biology water is the universal solvent for chemical reactions, the medium of transport in blood and in xylem, and it keeps plant cells turgid. it also gives a stable temperature to cells and lakes. human influence: cutting down forests reduces transpiration and rainfall, and paving over soil reduces infiltration and increases flooding, a serious problem in nigerian cities during the rainy season. nutrient cycling and the water cycle ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-18', 'The Carbon Cycle and Global Warming') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-18', 0, 'The Carbon Cycle and Global Warming: summary', 'How carbon moves through photosynthesis, respiration, decomposition and combustion, and how people have upset the cycle. Key words: Carbon cycle, Photosynthesis, Decomposition, Combustion, Greenhouse effect, Fossil fuels.', 'the carbon cycle and global warming: summary how carbon moves through photosynthesis, respiration, decomposition and combustion, and how people have upset the cycle. key words: carbon cycle, photosynthesis, decomposition, combustion, greenhouse effect, fossil fuels. the carbon cycle and global warming ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-18', 1, 'Carbon: the backbone of life', 'Every organic molecule (sugar, fat, protein, DNA) is built on carbon. The carbon cycle also shows the flow of energy, because carbon in food carries the energy that organisms use.', 'carbon: the backbone of life every organic molecule (sugar, fat, protein, dna) is built on carbon. the carbon cycle also shows the flow of energy, because carbon in food carries the energy that organisms use. the carbon cycle and global warming ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-18', 2, 'The main processes', 'Photosynthesis: 6CO₂ + 6H₂O + light energy → C₆H₁₂O₆ + 6O₂. Green plants and algae take CO₂ from the air or water and build glucose. This is the main way carbon enters living things, and the main process that removes CO₂ from the air on a large scale (the oceans also dissolve some). Respiration: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + ATP. All living things, including plants and decomposers, release CO₂ back to the air. Feeding: carbon passes from plants to animals along food chains. Decomposition: bacteria and fungi break down dead plants, animals and wastes, releasing CO₂ by respiration and returning nutrients to the soil. Where the dead remains are buried without oxygen over millions of years, they become coal, oil and natural gas (fossil fuels). Combustion: burning wood or fossil fuels releases CO₂. Natural examples are bush fires; human examples are generators, vehicles, gas flaring and factories.', 'the main processes photosynthesis: 6co₂ + 6h₂o + light energy → c₆h₁₂o₆ + 6o₂. green plants and algae take co₂ from the air or water and build glucose. this is the main way carbon enters living things, and the main process that removes co₂ from the air on a large scale (the oceans also dissolve some). respiration: c₆h₁₂o₆ + 6o₂ → 6co₂ + 6h₂o + atp. all living things, including plants and decomposers, release co₂ back to the air. feeding: carbon passes from plants to animals along food chains. decomposition: bacteria and fungi break down dead plants, animals and wastes, releasing co₂ by respiration and returning nutrients to the soil. where the dead remains are buried without oxygen over millions of years, they become coal, oil and natural gas (fossil fuels). combustion: burning wood or fossil fuels releases co₂. natural examples are bush fires; human examples are generators, vehicles, gas flaring and factories. the carbon cycle and global warming ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-18', 3, 'Human impact', 'Burning of fossil fuels adds large amounts of ''old'' carbon quickly, and deforestation reduces the number of plants that take in CO₂. The CO₂ level in the air has risen steadily. CO₂ is a greenhouse gas: it traps heat in the atmosphere, causing the enhanced greenhouse effect, global warming, melting ice, rising sea level and changes in rainfall. Ways to help: plant trees, use solar and other clean energy, reduce gas flaring, use public transport, and recycle.', 'human impact burning of fossil fuels adds large amounts of ''old'' carbon quickly, and deforestation reduces the number of plants that take in co₂. the co₂ level in the air has risen steadily. co₂ is a greenhouse gas: it traps heat in the atmosphere, causing the enhanced greenhouse effect, global warming, melting ice, rising sea level and changes in rainfall. ways to help: plant trees, use solar and other clean energy, reduce gas flaring, use public transport, and recycle. the carbon cycle and global warming ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T1:b21-19', 'The Nitrogen Cycle') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-19', 0, 'The Nitrogen Cycle: summary', 'The five processes of the nitrogen cycle, the bacteria that carry them out, and why leguminous crops improve the soil. Key words: Nitrogen fixation, Ammonification, Nitrification, Denitrification, Rhizobium, Nitrates.', 'the nitrogen cycle: summary the five processes of the nitrogen cycle, the bacteria that carry them out, and why leguminous crops improve the soil. key words: nitrogen fixation, ammonification, nitrification, denitrification, rhizobium, nitrates. the nitrogen cycle ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-19', 1, 'The problem of unusable nitrogen', 'Nitrogen gas (N₂) is about 78% of the air, but it is so unreactive that plants and animals cannot use it directly. They need it in the form of nitrates to build proteins, DNA and chlorophyll. The nitrogen cycle, driven by microbes, changes it into useful forms and back.', 'the problem of unusable nitrogen nitrogen gas (n₂) is about 78% of the air, but it is so unreactive that plants and animals cannot use it directly. they need it in the form of nitrates to build proteins, dna and chlorophyll. the nitrogen cycle, driven by microbes, changes it into useful forms and back. the nitrogen cycle ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-19', 2, 'The processes', 'Study the table. Nitrogen fixation; N₂ → ammonia/ammonium; Symbiotic Rhizobium in root nodules of legumes (beans, cowpea, groundnut); free-living Azotobacter and Clostridium; lightning; the Haber process in industry. Ammonification; Dead remains and wastes (urea, uric acid) → ammonia/ammonium; Decomposers: bacteria and fungi. Nitrification; Ammonium → nitrites → nitrates; Step 1: Nitrosomonas; step 2: Nitrobacter; needs oxygen, so it occurs in well-aerated soil. Assimilation; Plants absorb nitrates and make proteins, DNA and chlorophyll; animals get nitrogen by eating; Plants and animals. Denitrification; Nitrates → nitrogen gas; Denitrifying bacteria such as Pseudomonas; work without oxygen in waterlogged soil.', 'the processes study the table. nitrogen fixation; n₂ → ammonia/ammonium; symbiotic rhizobium in root nodules of legumes (beans, cowpea, groundnut); free-living azotobacter and clostridium; lightning; the haber process in industry. ammonification; dead remains and wastes (urea, uric acid) → ammonia/ammonium; decomposers: bacteria and fungi. nitrification; ammonium → nitrites → nitrates; step 1: nitrosomonas; step 2: nitrobacter; needs oxygen, so it occurs in well-aerated soil. assimilation; plants absorb nitrates and make proteins, dna and chlorophyll; animals get nitrogen by eating; plants and animals. denitrification; nitrates → nitrogen gas; denitrifying bacteria such as pseudomonas; work without oxygen in waterlogged soil. the nitrogen cycle ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-19', 3, 'Farming applications', 'Farmers use crop rotation or intercropping with legumes to put nitrogen back in the soil without buying fertiliser. Good drainage and ploughing keep soil aerated, so denitrification is low and nitrification is high. Too much nitrate fertiliser can be washed into rivers and lakes, causing eutrophication (a burst of algae growth that uses up the oxygen). The Haber process fixes nitrogen industrially: N₂ + 3H₂ ⇌ 2NH₃ makes fertiliser that feeds billions, but its misuse pollutes water. Both sides matter in the debate.', 'farming applications farmers use crop rotation or intercropping with legumes to put nitrogen back in the soil without buying fertiliser. good drainage and ploughing keep soil aerated, so denitrification is low and nitrification is high. too much nitrate fertiliser can be washed into rivers and lakes, causing eutrophication (a burst of algae growth that uses up the oxygen). the haber process fixes nitrogen industrially: n₂ + 3h₂ ⇌ 2nh₃ makes fertiliser that feeds billions, but its misuse pollutes water. both sides matter in the debate. the nitrogen cycle ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
