INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-20', 0, 'First Term Revision: Connecting the Systems: summary', 'The story of a glucose molecule and a protein molecule, a topic-by-topic revision guide and worked answers to the self-assessment questions. Key words: Revision, Integration, Active recall, Eutrophication, Turgidity.', 'first term revision: connecting the systems: summary the story of a glucose molecule and a protein molecule, a topic-by-topic revision guide and worked answers to the self-assessment questions. key words: revision, integration, active recall, eutrophication, turgidity. first term revision: connecting the systems ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-20', 1, 'Biology is one connected story', 'The digestive, circulatory, respiratory and excretory systems work together. Cycles in nature connect the whole organism to the environment. Revise by following a molecule from the plate to the cell to the waste.', 'biology is one connected story the digestive, circulatory, respiratory and excretory systems work together. cycles in nature connect the whole organism to the environment. revise by following a molecule from the plate to the cell to the waste. first term revision: connecting the systems ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-20', 2, 'The story of a glucose molecule (from bread)', 'Digestion: amylase in saliva and pancreatic juice and maltase in the ileum break starch to glucose. Absorption: glucose is actively transported into the villi of the ileum. Transport: the hepatic portal vein takes it to the liver, then the systemic circulation takes it to a muscle cell. Respiration: in the mitochondria, it is used in aerobic respiration to make ATP. Waste: CO₂ goes in the blood to the lungs and is breathed out; the water goes with the urine.', 'the story of a glucose molecule (from bread) digestion: amylase in saliva and pancreatic juice and maltase in the ileum break starch to glucose. absorption: glucose is actively transported into the villi of the ileum. transport: the hepatic portal vein takes it to the liver, then the systemic circulation takes it to a muscle cell. respiration: in the mitochondria, it is used in aerobic respiration to make atp. waste: co₂ goes in the blood to the lungs and is breathed out; the water goes with the urine. first term revision: connecting the systems ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-20', 3, 'The story of a protein molecule (from fish)', 'Digestion: pepsin (stomach), trypsin (duodenum) and peptidases (ileum) break it into amino acids. Absorption and transport: the amino acids go to the liver. Assimilation: used to build muscle and enzymes. Waste: excess amino acids are deaminated in the liver and make urea. Excretion: the urea is filtered by the kidneys and leaves in the urine.', 'the story of a protein molecule (from fish) digestion: pepsin (stomach), trypsin (duodenum) and peptidases (ileum) break it into amino acids. absorption and transport: the amino acids go to the liver. assimilation: used to build muscle and enzymes. waste: excess amino acids are deaminated in the liver and make urea. excretion: the urea is filtered by the kidneys and leaves in the urine. first term revision: connecting the systems ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-20', 4, 'Revision checklist', 'Digestive system: the five stages of nutrition, enzyme table, villus, ileum adaptations, role of bile. Transport: SA:V, diffusion, osmosis, active transport, heart, double circulation, vessels, blood and clotting. Respiratory system: path of air, alveoli adaptations, breathing mechanism, aerobic and anaerobic respiration, oxygen debt. Excretory system: excretion versus egestion, liver, nephron, ultrafiltration, reabsorption, ADH. Nutrient cycles: water, carbon, nitrogen and the bacteria involved. Diagrams to practise: alimentary canal; a villus; the heart; artery, vein and capillary; red cells in three solutions; respiratory tract; alveolus; breathing; urinary system; nephron; carbon and nitrogen cycles.', 'revision checklist digestive system: the five stages of nutrition, enzyme table, villus, ileum adaptations, role of bile. transport: sa:v, diffusion, osmosis, active transport, heart, double circulation, vessels, blood and clotting. respiratory system: path of air, alveoli adaptations, breathing mechanism, aerobic and anaerobic respiration, oxygen debt. excretory system: excretion versus egestion, liver, nephron, ultrafiltration, reabsorption, adh. nutrient cycles: water, carbon, nitrogen and the bacteria involved. diagrams to practise: alimentary canal; a villus; the heart; artery, vein and capillary; red cells in three solutions; respiratory tract; alveolus; breathing; urinary system; nephron; carbon and nitrogen cycles. first term revision: connecting the systems ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-20', 5, 'Worked answers to the self-test', '1. How do circulation and respiration supply a muscle cell? Air reaches the alveoli; oxygen diffuses into the blood and joins haemoglobin in the red cells; the heart pumps this blood through the aorta and arteries to the capillaries in the muscle; the oxygen is released and diffuses into the cell for respiration. CO₂ made by respiration diffuses into the blood, goes by the veins and vena cava to the heart, then through the pulmonary artery to the lungs, where it diffuses into the alveoli and is breathed out. 2. Fertiliser and fish deaths (eutrophication): nitrates wash into the lake after heavy rain. Algae grow rapidly (an algal bloom) and cover the surface. Light cannot reach plants below, which die. Bacteria decompose the dead algae and plants and use up the dissolved oxygen. The fish and other animals suffocate and die. 3. Celery in distilled water: the water has a higher water potential than the cells, so water enters the cells by osmosis. The cells become turgid and the celery stalk becomes firm and crisp.', 'worked answers to the self-test 1. how do circulation and respiration supply a muscle cell? air reaches the alveoli; oxygen diffuses into the blood and joins haemoglobin in the red cells; the heart pumps this blood through the aorta and arteries to the capillaries in the muscle; the oxygen is released and diffuses into the cell for respiration. co₂ made by respiration diffuses into the blood, goes by the veins and vena cava to the heart, then through the pulmonary artery to the lungs, where it diffuses into the alveoli and is breathed out. 2. fertiliser and fish deaths (eutrophication): nitrates wash into the lake after heavy rain. algae grow rapidly (an algal bloom) and cover the surface. light cannot reach plants below, which die. bacteria decompose the dead algae and plants and use up the dissolved oxygen. the fish and other animals suffocate and die. 3. celery in distilled water: the water has a higher water potential than the cells, so water enters the cells by osmosis. the cells become turgid and the celery stalk becomes firm and crisp. first term revision: connecting the systems ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T1', 'NG-SS2-BIO-T1:b21-20', 6, 'How to revise well', 'Active recall: close the book and draw or write from memory, then check. Spaced repetition: revise a topic on several days, not once. Teach someone: explain the nitrogen cycle to a friend. Past questions: practise under timed conditions, then list your three most common mistakes.', 'how to revise well active recall: close the book and draw or write from memory, then check. spaced repetition: revise a topic on several days, not once. teach someone: explain the nitrogen cycle to a friend. past questions: practise under timed conditions, then list your three most common mistakes. first term revision: connecting the systems ss2 biology, term 1') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
