INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-01', 0, 'Welcome and Table of Contents: summary', 'Welcome to SS2 Biology Second Term: ecology, pollution, conservation, crop pests and diseases, reproduction in vertebrates and plants, pollination and homeostasis. Key words: SS2 Biology - Second Term, Syllabus, Table of contents.', 'welcome and table of contents: summary welcome to ss2 biology second term: ecology, pollution, conservation, crop pests and diseases, reproduction in vertebrates and plants, pollination and homeostasis. key words: ss2 biology - second term, syllabus, table of contents. welcome and table of contents ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-01', 1, 'Welcome to SS2 Biology - Second Term', 'Welcome to SS2 Biology, Second Term. We begin with how living things relate to each other and to their surroundings, study pollution and how to conserve nature, look at crop pests and diseases, compare reproduction in vertebrates and flowering plants, and end with how the body keeps itself steady (homeostasis). Read each unit slowly, study the pictures and answer the short check questions. Where the original lesson note needed a correction or a Nigerian example, it is explained in the unit.', 'welcome to ss2 biology - second term welcome to ss2 biology, second term. we begin with how living things relate to each other and to their surroundings, study pollution and how to conserve nature, look at crop pests and diseases, compare reproduction in vertebrates and flowering plants, and end with how the body keeps itself steady (homeostasis). read each unit slowly, study the pictures and answer the short check questions. where the original lesson note needed a correction or a nigerian example, it is explained in the unit. welcome and table of contents ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-01', 2, 'Table of contents for SS2 Biology - Second Term', 'Here is the plan for the term. Tick each unit when you finish it. 1; -; Welcome and table of contents. 2; 1; Ecology: Levels of Organisation and Associations Between Organisms. 3; 1; Tolerance and Adaptation. 4; 2; Pollution: Air and Water. 5; 2; Pollution: Soil and Noise, and the Control of Pollution. 6; 3; Conservation of Natural Resources. 7; 4; Pests of Crops. 8; 4; Diseases of Crops. 9; 4; Control of Pests and Diseases. 10; 6; Reproduction in Vertebrates: Fertilisation and the Mammalian System. 11; 6; Comparing Reproduction in Fish, Amphibians, Reptiles, Birds and Mammals. 12; 8; The Flower and Its Parts. 13; 8; Types of Flowers: Bisexual, Unisexual, Monoecious, Dioecious, Monocot and Dicot. 14; 9; Pollination: Self and Cross. 15; 9; Agents of Pollination: Wind, Insects, Birds and Bats. 16; 10; Homeostasis and Temperature Control. 17; 10; Controlling Blood Sugar and Water: More Examples of Homeostasis. 18; 11; Second Term Revision.', 'table of contents for ss2 biology - second term here is the plan for the term. tick each unit when you finish it. 1; -; welcome and table of contents. 2; 1; ecology: levels of organisation and associations between organisms. 3; 1; tolerance and adaptation. 4; 2; pollution: air and water. 5; 2; pollution: soil and noise, and the control of pollution. 6; 3; conservation of natural resources. 7; 4; pests of crops. 8; 4; diseases of crops. 9; 4; control of pests and diseases. 10; 6; reproduction in vertebrates: fertilisation and the mammalian system. 11; 6; comparing reproduction in fish, amphibians, reptiles, birds and mammals. 12; 8; the flower and its parts. 13; 8; types of flowers: bisexual, unisexual, monoecious, dioecious, monocot and dicot. 14; 9; pollination: self and cross. 15; 9; agents of pollination: wind, insects, birds and bats. 16; 10; homeostasis and temperature control. 17; 10; controlling blood sugar and water: more examples of homeostasis. 18; 11; second term revision. welcome and table of contents ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-02', 'Ecology: Levels of Organisation and Associations Between Organisms') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-02', 0, 'Ecology: Levels of Organisation and Associations Between Organisms: summary', 'The meaning of ecology, biotic and abiotic factors, the levels from individual to biosphere, and the five kinds of association between living things. Key words: Ecology, Biotic factor, Abiotic factor, Population, Community, Symbiosis, Mutualism, Parasitism.', 'ecology: levels of organisation and associations between organisms: summary the meaning of ecology, biotic and abiotic factors, the levels from individual to biosphere, and the five kinds of association between living things. key words: ecology, biotic factor, abiotic factor, population, community, symbiosis, mutualism, parasitism. ecology: levels of organisation and associations between organisms ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-02', 1, 'What is ecology?', 'Ecology is the scientific study of the relationships between living things and their surroundings. The word comes from the Greek oikos (''house'') and logos (''study''): it is the study of the ''house'' in which living things live. Think of an ecosystem as a neighbourhood. Each organism has a job (its niche), deals with its neighbours (biotic factors, the living things such as plants, animals and microbes) and with the physical surroundings (abiotic factors, the non-living things such as rainfall, temperature, light, soil, pH and wind).', 'what is ecology? ecology is the scientific study of the relationships between living things and their surroundings. the word comes from the greek oikos (''house'') and logos (''study''): it is the study of the ''house'' in which living things live. think of an ecosystem as a neighbourhood. each organism has a job (its niche), deals with its neighbours (biotic factors, the living things such as plants, animals and microbes) and with the physical surroundings (abiotic factors, the non-living things such as rainfall, temperature, light, soil, ph and wind). ecology: levels of organisation and associations between organisms ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-02', 2, 'Levels of ecological organisation', 'From the smallest to the largest: Individual: one organism, for example one lion. Population: all the individuals of one species in one area, for example the pride of lions in Yankari Game Reserve. Community: all the populations of different species living and interacting in an area (lions, zebras, grasses, trees and bacteria). Ecosystem: the community together with its non-living environment (soil, rain, sunlight). Biome: a very large region with a similar climate and similar plants and animals, for example the tropical savanna or the tropical rainforest. Biosphere: all the parts of Earth where life exists, from the deepest ocean to the high mountains.', 'levels of ecological organisation from the smallest to the largest: individual: one organism, for example one lion. population: all the individuals of one species in one area, for example the pride of lions in yankari game reserve. community: all the populations of different species living and interacting in an area (lions, zebras, grasses, trees and bacteria). ecosystem: the community together with its non-living environment (soil, rain, sunlight). biome: a very large region with a similar climate and similar plants and animals, for example the tropical savanna or the tropical rainforest. biosphere: all the parts of earth where life exists, from the deepest ocean to the high mountains. ecology: levels of organisation and associations between organisms ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-02', 3, 'Associations (symbiosis)', 'No organism lives completely alone. Species form close, long-term relationships, called associations or symbiosis. The signs + (benefits), – (harmed) and 0 (not affected) are used to show who gains. Mutualism; + / +  both benefit; Bee and flower (nectar for the bee, pollination for the flower); Rhizobium in the root nodules of beans and groundnuts (the bacteria fix nitrogen, the plant gives sugar and a home). Commensalism; + / 0  one benefits, the other is not affected; Orchid growing on a tree branch (epiphyte); remora fish travelling on a shark and eating scraps. Parasitism; + / –  the parasite benefits, the host is harmed; Ectoparasites on the surface: ticks, lice, fleas. Endoparasites inside: tapeworm, Plasmodium (malaria), Ascaris. Predation; + / –  predator eats prey; Lion and zebra, hawk and chick, lizard and grasshopper. Competition; – / –  both lose; Lions and hyenas for the same prey; two crops for the same water and light.', 'associations (symbiosis) no organism lives completely alone. species form close, long-term relationships, called associations or symbiosis. the signs + (benefits), – (harmed) and 0 (not affected) are used to show who gains. mutualism; + / +  both benefit; bee and flower (nectar for the bee, pollination for the flower); rhizobium in the root nodules of beans and groundnuts (the bacteria fix nitrogen, the plant gives sugar and a home). commensalism; + / 0  one benefits, the other is not affected; orchid growing on a tree branch (epiphyte); remora fish travelling on a shark and eating scraps. parasitism; + / –  the parasite benefits, the host is harmed; ectoparasites on the surface: ticks, lice, fleas. endoparasites inside: tapeworm, plasmodium (malaria), ascaris. predation; + / –  predator eats prey; lion and zebra, hawk and chick, lizard and grasshopper. competition; – / –  both lose; lions and hyenas for the same prey; two crops for the same water and light. ecology: levels of organisation and associations between organisms ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-02', 4, 'A correction and a clarification', 'Strictly, scientists use ''symbiosis'' for close living-together such as mutualism, commensalism and parasitism. Predation and competition are interactions but not always called symbiosis. Also, the lesson note says ''the tree is neither harmed nor helped'' by the orchid; in a few cases a heavy load of epiphytes may harm a tree, but we treat the standard case as commensalism. The Serengeti example in many books is in Tanzania. In Nigeria you can use Yankari, Gashaka-Gumti or Okomu National Park instead.', 'a correction and a clarification strictly, scientists use ''symbiosis'' for close living-together such as mutualism, commensalism and parasitism. predation and competition are interactions but not always called symbiosis. also, the lesson note says ''the tree is neither harmed nor helped'' by the orchid; in a few cases a heavy load of epiphytes may harm a tree, but we treat the standard case as commensalism. the serengeti example in many books is in tanzania. in nigeria you can use yankari, gashaka-gumti or okomu national park instead. ecology: levels of organisation and associations between organisms ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-03', 'Tolerance and Adaptation') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-03', 0, 'Tolerance and Adaptation: summary', 'Shelford''s law of tolerance, the zones of the tolerance curve, and the structural, physiological and behavioural adaptations of organisms. Key words: Tolerance, Optimum, Physiological stress, Adaptation, Xerophyte, Hibernation.', 'tolerance and adaptation: summary shelford''s law of tolerance, the zones of the tolerance curve, and the structural, physiological and behavioural adaptations of organisms. key words: tolerance, optimum, physiological stress, adaptation, xerophyte, hibernation. tolerance and adaptation ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-03', 1, 'Shelford''s law of tolerance', 'Tolerance is the ability of an organism to live and reproduce within a certain range of an environmental factor, such as temperature, pH or salt concentration. Shelford''s law says that each organism has a minimum, an optimum and a maximum for each factor, and it cannot survive outside this range.', 'shelford''s law of tolerance tolerance is the ability of an organism to live and reproduce within a certain range of an environmental factor, such as temperature, ph or salt concentration. shelford''s law says that each organism has a minimum, an optimum and a maximum for each factor, and it cannot survive outside this range. tolerance and adaptation ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-03', 2, 'The zones of the curve', 'Optimum range (the middle of the curve): the factor is at its best level, so the population is largest, healthiest and breeds well. Zones of physiological stress (on both sides): the factor is too low or too high. The organism lives but is weak, grows slowly and cannot breed well. Zones of intolerance (the far ends): the organism cannot live and soon dies. Example: the fish tilapia has a temperature range. If the pond becomes too cold or too hot, the fish move into stress zones and die if they cannot escape. Different species have different ranges; a species with a wide range (such as the rat) is widespread, while one with a narrow range (such as some corals) is easily harmed by change.', 'the zones of the curve optimum range (the middle of the curve): the factor is at its best level, so the population is largest, healthiest and breeds well. zones of physiological stress (on both sides): the factor is too low or too high. the organism lives but is weak, grows slowly and cannot breed well. zones of intolerance (the far ends): the organism cannot live and soon dies. example: the fish tilapia has a temperature range. if the pond becomes too cold or too hot, the fish move into stress zones and die if they cannot escape. different species have different ranges; a species with a wide range (such as the rat) is widespread, while one with a narrow range (such as some corals) is easily harmed by change. tolerance and adaptation ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-03', 3, 'Adaptation', 'An adaptation is an inherited feature that helps an organism to survive and reproduce in its environment. There are three kinds.', 'adaptation an adaptation is an inherited feature that helps an organism to survive and reproduce in its environment. there are three kinds. tolerance and adaptation ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-03', 4, 'Structural, physiological and behavioural adaptations', 'Structural adaptations are body features. Cactus (xerophyte): spines (leaves reduced to cut water loss), thick fleshy stem that stores water, deep or wide roots. Fish: streamlined body to reduce drag, gills to take oxygen from water, fins for steering. Camel: hump stores fat, long eyelashes and closable nostrils keep out sand, broad pads do not sink in sand. Physiological adaptations are internal processes. Cactus (CAM photosynthesis): opens stomata at night to take in CO₂ and so loses less water in the hot day. Bears in cold lands hibernate (slow their body activity) to save energy. Salt-water fish pass out the extra salt through their gills and make little urine. Nigerian example: the lungfish aestivates in the mud during the dry season. Behavioural adaptations are actions. Wildebeest migrate to areas with fresh grass and water. Desert animals are nocturnal (active at night) to avoid the heat. Birds make nests and weaver birds build hanging nests to avoid snakes.', 'structural, physiological and behavioural adaptations structural adaptations are body features. cactus (xerophyte): spines (leaves reduced to cut water loss), thick fleshy stem that stores water, deep or wide roots. fish: streamlined body to reduce drag, gills to take oxygen from water, fins for steering. camel: hump stores fat, long eyelashes and closable nostrils keep out sand, broad pads do not sink in sand. physiological adaptations are internal processes. cactus (cam photosynthesis): opens stomata at night to take in co₂ and so loses less water in the hot day. bears in cold lands hibernate (slow their body activity) to save energy. salt-water fish pass out the extra salt through their gills and make little urine. nigerian example: the lungfish aestivates in the mud during the dry season. behavioural adaptations are actions. wildebeest migrate to areas with fresh grass and water. desert animals are nocturnal (active at night) to avoid the heat. birds make nests and weaver birds build hanging nests to avoid snakes. tolerance and adaptation ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-04', 'Pollution: Air and Water') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-04', 0, 'Pollution: Air and Water: summary', 'The meaning of pollution, and the causes, effects and control of air pollution (including acid rain) and water pollution (including eutrophication). Key words: Pollutant, Acid rain, Greenhouse effect, Eutrophication, Sewage, Oil spill.', 'pollution: air and water: summary the meaning of pollution, and the causes, effects and control of air pollution (including acid rain) and water pollution (including eutrophication). key words: pollutant, acid rain, greenhouse effect, eutrophication, sewage, oil spill. pollution: air and water ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-04', 1, 'What is pollution?', 'Pollution is the introduction of harmful substances (pollutants) into the environment, causing harm to living things or to the environment itself. A pollutant is any substance in the wrong place, in the wrong amount, or at the wrong time.', 'what is pollution? pollution is the introduction of harmful substances (pollutants) into the environment, causing harm to living things or to the environment itself. a pollutant is any substance in the wrong place, in the wrong amount, or at the wrong time. pollution: air and water ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-04', 2, 'Air pollution', 'Causes: factory fumes (sulphur dioxide SO₂ and oxides of nitrogen NOx); smoke and carbon monoxide from vehicles, generators and power plants; bush burning; dust from quarrying and cement factories; gas flaring in oil-producing areas; aerosol sprays (CFCs). Effects: breathing diseases such as asthma, bronchitis and lung cancer; carbon monoxide (CO) joins with haemoglobin and prevents it from carrying oxygen (this is why using a generator in a closed room can kill); acid rain, in which SO₂ and NOx dissolve in rain to form acids that damage buildings (zinc roofs corrode), kill fish and harm crops and forests; global warming and climate change caused by greenhouse gases such as CO₂ and methane; and damage to the ozone layer by CFCs. Control: use cleaner energy (solar, wind, hydro, natural gas); fit catalytic converters in vehicles and filters on factory chimneys; make and enforce laws about emissions; plant trees (afforestation); stop bush burning and gas flaring.', 'air pollution causes: factory fumes (sulphur dioxide so₂ and oxides of nitrogen nox); smoke and carbon monoxide from vehicles, generators and power plants; bush burning; dust from quarrying and cement factories; gas flaring in oil-producing areas; aerosol sprays (cfcs). effects: breathing diseases such as asthma, bronchitis and lung cancer; carbon monoxide (co) joins with haemoglobin and prevents it from carrying oxygen (this is why using a generator in a closed room can kill); acid rain, in which so₂ and nox dissolve in rain to form acids that damage buildings (zinc roofs corrode), kill fish and harm crops and forests; global warming and climate change caused by greenhouse gases such as co₂ and methane; and damage to the ozone layer by cfcs. control: use cleaner energy (solar, wind, hydro, natural gas); fit catalytic converters in vehicles and filters on factory chimneys; make and enforce laws about emissions; plant trees (afforestation); stop bush burning and gas flaring. pollution: air and water ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-04', 3, 'Water pollution', 'Causes: untreated sewage and household waste; factory waste (effluent) containing metals and chemicals; run-off from farms carrying fertiliser and pesticides; oil spills from tankers and pipelines (a serious problem in the Niger Delta); dumping of refuse in drains and rivers. Effects: eutrophication; water-borne diseases such as cholera, typhoid and dysentery; poisoning and death of fish and other water life; oil on the water surface cuts oxygen and light, and coats the feathers of water birds; heavy metals such as mercury build up in food chains and harm people who eat the fish. Control: build and maintain sewage treatment plants; treat factory effluent before release; make laws against dumping and punish offenders; educate the public; use fertiliser in the right amounts; clean up oil spills with booms, skimmers and bacteria that eat oil.', 'water pollution causes: untreated sewage and household waste; factory waste (effluent) containing metals and chemicals; run-off from farms carrying fertiliser and pesticides; oil spills from tankers and pipelines (a serious problem in the niger delta); dumping of refuse in drains and rivers. effects: eutrophication; water-borne diseases such as cholera, typhoid and dysentery; poisoning and death of fish and other water life; oil on the water surface cuts oxygen and light, and coats the feathers of water birds; heavy metals such as mercury build up in food chains and harm people who eat the fish. control: build and maintain sewage treatment plants; treat factory effluent before release; make laws against dumping and punish offenders; educate the public; use fertiliser in the right amounts; clean up oil spills with booms, skimmers and bacteria that eat oil. pollution: air and water ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-04', 4, 'Eutrophication step by step', '1. Fertiliser or sewage, rich in nitrates and phosphates, enters a river or lake. 2. Algae grow very fast and cover the surface (an algal bloom). 3. The algae block the light, so the plants below die. 4. Bacteria decompose the dead algae and plants and use up the dissolved oxygen. 5. Fish and other animals suffocate and die. 6. The water becomes smelly and unfit to drink.', 'eutrophication step by step 1. fertiliser or sewage, rich in nitrates and phosphates, enters a river or lake. 2. algae grow very fast and cover the surface (an algal bloom). 3. the algae block the light, so the plants below die. 4. bacteria decompose the dead algae and plants and use up the dissolved oxygen. 5. fish and other animals suffocate and die. 6. the water becomes smelly and unfit to drink. pollution: air and water ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-05', 'Pollution: Soil and Noise, and the Control of Pollution') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-05', 0, 'Pollution: Soil and Noise, and the Control of Pollution: summary', 'The causes, effects and control of land pollution and noise pollution, with a summary table of all four types. Key words: Soil pollution, Leaching, 3 R''s, Bioremediation, Noise pollution, Biodegradable.', 'pollution: soil and noise, and the control of pollution: summary the causes, effects and control of land pollution and noise pollution, with a summary table of all four types. key words: soil pollution, leaching, 3 r''s, bioremediation, noise pollution, biodegradable. pollution: soil and noise, and the control of pollution ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-05', 1, 'Soil (land) pollution', 'Causes: dumping of domestic and industrial solid waste, especially non-biodegradable materials such as plastics, polythene bags and sachet-water bags; too much fertiliser and pesticide; mining and quarrying; oil spills and chemical waste; electronic waste (e-waste). Effects: the soil loses fertility and crop yield falls; poisons seep through the soil into underground water (leaching); soil organisms such as earthworms and useful bacteria die; flooding, because refuse blocks drains; breeding places for flies, mosquitoes and rats which spread diseases. Control: the 3 R''s: Reduce (use less), Reuse (use again) and Recycle (turn waste into new things); use biodegradable products; bioremediation (using bacteria and fungi to clean polluted soil); organic farming; proper waste disposal and sanitary landfill; planting cover crops.', 'soil (land) pollution causes: dumping of domestic and industrial solid waste, especially non-biodegradable materials such as plastics, polythene bags and sachet-water bags; too much fertiliser and pesticide; mining and quarrying; oil spills and chemical waste; electronic waste (e-waste). effects: the soil loses fertility and crop yield falls; poisons seep through the soil into underground water (leaching); soil organisms such as earthworms and useful bacteria die; flooding, because refuse blocks drains; breeding places for flies, mosquitoes and rats which spread diseases. control: the 3 r''s: reduce (use less), reuse (use again) and recycle (turn waste into new things); use biodegradable products; bioremediation (using bacteria and fungi to clean polluted soil); organic farming; proper waste disposal and sanitary landfill; planting cover crops. pollution: soil and noise, and the control of pollution ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-05', 2, 'Noise pollution', 'Noise is unwanted loud sound, measured in decibels (dB). Sound above about 85 dB over a long time can damage hearing. Causes: traffic and horns, factories, generators, aircraft, loudspeakers at markets, churches, mosques and parties. Effects: hearing loss; stress, headache and high blood pressure; poor sleep and poor concentration; it disturbs communication of animals and may drive them away. Control: plant trees as sound barriers; use silencers on engines and generators; fit soundproof materials in buildings; keep factories away from homes; make and enforce laws about noise levels.', 'noise pollution noise is unwanted loud sound, measured in decibels (db). sound above about 85 db over a long time can damage hearing. causes: traffic and horns, factories, generators, aircraft, loudspeakers at markets, churches, mosques and parties. effects: hearing loss; stress, headache and high blood pressure; poor sleep and poor concentration; it disturbs communication of animals and may drive them away. control: plant trees as sound barriers; use silencers on engines and generators; fit soundproof materials in buildings; keep factories away from homes; make and enforce laws about noise levels. pollution: soil and noise, and the control of pollution ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-05', 3, 'Summary of the four types', 'Study the table. Air; Vehicle exhaust, gas flaring; Respiratory disease, acid rain; Catalytic converters, clean energy. Water; Sewage, oil spill, fertiliser; Eutrophication, cholera; Treatment plants, laws. Soil; Plastics, agrochemicals; Lower fertility, leaching; 3 R''s, bioremediation. Noise; Generators, horns; Hearing loss, stress; Silencers, trees, laws.', 'summary of the four types study the table. air; vehicle exhaust, gas flaring; respiratory disease, acid rain; catalytic converters, clean energy. water; sewage, oil spill, fertiliser; eutrophication, cholera; treatment plants, laws. soil; plastics, agrochemicals; lower fertility, leaching; 3 r''s, bioremediation. noise; generators, horns; hearing loss, stress; silencers, trees, laws. pollution: soil and noise, and the control of pollution ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-05', 4, 'The responsibility of a citizen', 'Do not litter, do not burn rubbish in the open, sort waste, use sachet-water bags only once and recycle them, service your generator, and write to local government about problems in your community. Good laws only work when people obey them.', 'the responsibility of a citizen do not litter, do not burn rubbish in the open, sort waste, use sachet-water bags only once and recycle them, service your generator, and write to local government about problems in your community. good laws only work when people obey them. pollution: soil and noise, and the control of pollution ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-06', 'Conservation of Natural Resources') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-06', 0, 'Conservation of Natural Resources: summary', 'Conservation versus preservation, and the methods of conserving soil, water, forests and wildlife. Key words: Conservation, Preservation, Contour ploughing, Afforestation, Poaching, Game reserve.', 'conservation of natural resources: summary conservation versus preservation, and the methods of conserving soil, water, forests and wildlife. key words: conservation, preservation, contour ploughing, afforestation, poaching, game reserve. conservation of natural resources ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-06', 1, 'What is conservation?', 'Conservation is the wise and sustainable use and management of natural resources so that they are not wasted, destroyed or made extinct, and are available for future generations. Conservation is not the same as preservation. In conservation resources are used wisely (for example, selective felling, where only mature trees are cut). In preservation, nature is protected from any use at all (for example, a strict nature reserve where people cannot enter).', 'what is conservation? conservation is the wise and sustainable use and management of natural resources so that they are not wasted, destroyed or made extinct, and are available for future generations. conservation is not the same as preservation. in conservation resources are used wisely (for example, selective felling, where only mature trees are cut). in preservation, nature is protected from any use at all (for example, a strict nature reserve where people cannot enter). conservation of natural resources ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-06', 2, 'Soil conservation', 'Importance: soil grows our food, filters water and supports many living things. Erosion by rain and wind removes the fertile top layer (a big problem in the south-east of Nigeria with gully erosion, and desert encroachment in the north). Methods: contour ploughing (ploughing across the slope, not up and down, to slow run-off); terracing steep slopes; crop rotation (changing crops each season to keep nutrients); cover crops such as beans or sweet potato; mulching (covering the soil with dead leaves); planting trees and grass as windbreaks and shelter belts; adding manure; avoiding over-grazing.', 'soil conservation importance: soil grows our food, filters water and supports many living things. erosion by rain and wind removes the fertile top layer (a big problem in the south-east of nigeria with gully erosion, and desert encroachment in the north). methods: contour ploughing (ploughing across the slope, not up and down, to slow run-off); terracing steep slopes; crop rotation (changing crops each season to keep nutrients); cover crops such as beans or sweet potato; mulching (covering the soil with dead leaves); planting trees and grass as windbreaks and shelter belts; adding manure; avoiding over-grazing. conservation of natural resources ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-06', 3, 'Water conservation', 'Importance: water is needed for all life, for farming and for industry. Methods: drip irrigation (water goes straight to the roots); rainwater harvesting; building dams and reservoirs; repairing leaking pipes; protecting river banks and wetlands; not wasting water; treating and reusing waste water.', 'water conservation importance: water is needed for all life, for farming and for industry. methods: drip irrigation (water goes straight to the roots); rainwater harvesting; building dams and reservoirs; repairing leaking pipes; protecting river banks and wetlands; not wasting water; treating and reusing waste water. conservation of natural resources ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-06', 4, 'Forest conservation', 'Importance: forests give timber, firewood, food and medicine; they take in CO₂ and give out oxygen; they control climate and rainfall; they stop erosion and floods; and they shelter many species. Methods: afforestation (planting trees where there were none) and reforestation (replanting where trees were cut); selective felling instead of clear-felling; forest reserves and national parks; laws against illegal logging; use of gas, kerosene or solar energy instead of firewood and charcoal; tree-planting campaigns.', 'forest conservation importance: forests give timber, firewood, food and medicine; they take in co₂ and give out oxygen; they control climate and rainfall; they stop erosion and floods; and they shelter many species. methods: afforestation (planting trees where there were none) and reforestation (replanting where trees were cut); selective felling instead of clear-felling; forest reserves and national parks; laws against illegal logging; use of gas, kerosene or solar energy instead of firewood and charcoal; tree-planting campaigns. conservation of natural resources ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-06', 5, 'Wildlife conservation', 'Importance: keeps biodiversity and the balance of nature, gives food and medicine, supports tourism and has scientific and beauty value. Methods: game reserves and national parks (for example Yankari, Kainji Lake, Cross River National Park and Okomu); laws against poaching (illegal hunting) and trade in animal products such as ivory and pangolin scales; captive breeding of endangered species (for example in zoos) to release later; education and community involvement; controlling hunting seasons.', 'wildlife conservation importance: keeps biodiversity and the balance of nature, gives food and medicine, supports tourism and has scientific and beauty value. methods: game reserves and national parks (for example yankari, kainji lake, cross river national park and okomu); laws against poaching (illegal hunting) and trade in animal products such as ivory and pangolin scales; captive breeding of endangered species (for example in zoos) to release later; education and community involvement; controlling hunting seasons. conservation of natural resources ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-07', 'Pests of Crops') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-07', 0, 'Pests of Crops: summary', 'The kinds of crop pests (chewing, piercing and sucking, boring, nematodes, birds and rodents), the damage they do and the effects of pests on production. Key words: Pest, Defoliation, Vector, Stem borer, Nematode, Fall armyworm.', 'pests of crops: summary the kinds of crop pests (chewing, piercing and sucking, boring, nematodes, birds and rodents), the damage they do and the effects of pests on production. key words: pest, defoliation, vector, stem borer, nematode, fall armyworm. pests of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-07', 1, 'What is a pest?', 'A pest is any organism that harms crops, livestock or people or causes economic loss. Most crop pests are insects.', 'what is a pest? a pest is any organism that harms crops, livestock or people or causes economic loss. most crop pests are insects. pests of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-07', 2, 'Insect pests', 'Biting and chewing insects have strong jaws (mandibles) that cut leaves, stems and fruits. Examples: grasshoppers, locusts, beetles, caterpillars, fall armyworm. Damage: notched or eaten leaves (defoliation), holes in fruits. Piercing and sucking insects have needle-like mouthparts (stylets) that pierce the plant and suck sap. Examples: aphids, mealybugs, whiteflies, leafhoppers, cotton stainers. Damage: yellow leaves (chlorosis), wilting, stunted growth, sticky honeydew on which sooty mould grows. They are dangerous as vectors: they carry viruses from sick plants to healthy ones as they feed (whiteflies spread cassava mosaic disease). Boring insects have larvae (or adults) that bore into stems, fruits and seeds. Examples: stem borers in maize and sugar cane, maize weevils, bean weevils, cowpea beetles. Damage: hidden, because the harm is inside; plants wilt and die and stored grain is hollowed out.', 'insect pests biting and chewing insects have strong jaws (mandibles) that cut leaves, stems and fruits. examples: grasshoppers, locusts, beetles, caterpillars, fall armyworm. damage: notched or eaten leaves (defoliation), holes in fruits. piercing and sucking insects have needle-like mouthparts (stylets) that pierce the plant and suck sap. examples: aphids, mealybugs, whiteflies, leafhoppers, cotton stainers. damage: yellow leaves (chlorosis), wilting, stunted growth, sticky honeydew on which sooty mould grows. they are dangerous as vectors: they carry viruses from sick plants to healthy ones as they feed (whiteflies spread cassava mosaic disease). boring insects have larvae (or adults) that bore into stems, fruits and seeds. examples: stem borers in maize and sugar cane, maize weevils, bean weevils, cowpea beetles. damage: hidden, because the harm is inside; plants wilt and die and stored grain is hollowed out. pests of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-07', 3, 'Other pests', 'Nematodes (eelworms) are tiny worms in the soil. Root-knot nematodes make swellings (galls) on roots, so the plant cannot take in water and minerals and becomes stunted and wilts. Birds, such as quelea and weaver birds, eat ripening cereals (millet, sorghum, rice). Rodents (rats, squirrels, cane rats) gnaw stems and eat stored grain and tubers. Others: monkeys, snails and slugs.', 'other pests nematodes (eelworms) are tiny worms in the soil. root-knot nematodes make swellings (galls) on roots, so the plant cannot take in water and minerals and becomes stunted and wilts. birds, such as quelea and weaver birds, eat ripening cereals (millet, sorghum, rice). rodents (rats, squirrels, cane rats) gnaw stems and eat stored grain and tubers. others: monkeys, snails and slugs. pests of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-07', 4, 'Effects of pests on production', 'Lower yield and lower quality, so the farmer earns less. Higher cost of production (chemicals and labour). Heavy losses in stores (post-harvest losses), leading to food shortage. Total crop failure in bad outbreaks (locust swarms, fall armyworm). Contamination of food with droppings and with poisons made by moulds. Fall armyworm, first found in Nigeria in 2016, has reduced the yields of maize across many states.', 'effects of pests on production lower yield and lower quality, so the farmer earns less. higher cost of production (chemicals and labour). heavy losses in stores (post-harvest losses), leading to food shortage. total crop failure in bad outbreaks (locust swarms, fall armyworm). contamination of food with droppings and with poisons made by moulds. fall armyworm, first found in nigeria in 2016, has reduced the yields of maize across many states. pests of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-08', 'Diseases of Crops') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-08', 0, 'Diseases of Crops: summary', 'Fungal, bacterial and viral crop diseases, their symptoms, how they spread and the causal agent of each. Key words: Disease, Pathogen, Fungus, Bacterium, Virus, Cassava mosaic, Black pod.', 'diseases of crops: summary fungal, bacterial and viral crop diseases, their symptoms, how they spread and the causal agent of each. key words: disease, pathogen, fungus, bacterium, virus, cassava mosaic, black pod. diseases of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-08', 1, 'What is a plant disease?', 'A disease is any change from the normal growth and working of a plant, caused by a pathogen (a germ) or by something in the environment (such as lack of a mineral). Most are caused by fungi, bacteria and viruses.', 'what is a plant disease? a disease is any change from the normal growth and working of a plant, caused by a pathogen (a germ) or by something in the environment (such as lack of a mineral). most are caused by fungi, bacteria and viruses. diseases of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-08', 2, 'Fungal diseases', 'Fungi are the most common cause of plant disease. They spread by spores carried by wind, water splash, insects and soil. Black pod of cocoa: black patches rot the pods and the beans. Maize smut: large black swellings (galls) full of powdery spores on the cobs, tassels or stalks. Rusts: orange, red or brown powdery spots on leaves (maize rust). Mildews: white, powdery or downy growth on leaf surfaces. Others: anthracnose and leaf spots on many crops.', 'fungal diseases fungi are the most common cause of plant disease. they spread by spores carried by wind, water splash, insects and soil. black pod of cocoa: black patches rot the pods and the beans. maize smut: large black swellings (galls) full of powdery spores on the cobs, tassels or stalks. rusts: orange, red or brown powdery spots on leaves (maize rust). mildews: white, powdery or downy growth on leaf surfaces. others: anthracnose and leaf spots on many crops. diseases of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-08', 3, 'Bacterial diseases', 'Spread by splashes of rain, by tools, by insects and by infected planting material. Examples: Cassava bacterial blight (angular leaf spots, wilting and dying back of shoots); citrus canker (raised corky spots on fruits, leaves and stems); bacterial wilt of tomato and pepper.', 'bacterial diseases spread by splashes of rain, by tools, by insects and by infected planting material. examples: cassava bacterial blight (angular leaf spots, wilting and dying back of shoots); citrus canker (raised corky spots on fruits, leaves and stems); bacterial wilt of tomato and pepper. diseases of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-08', 4, 'Viral diseases', 'Viruses are carried by vectors, mainly sap-sucking insects such as aphids and whiteflies, and by cuttings taken from sick plants. Examples: Cassava mosaic disease (yellow and green mosaic on leaves, small twisted leaves and a big loss of yield); Maize streak virus (yellow streaks along the veins, stunted plants; carried by leafhoppers); groundnut rosette (carried by aphids); cocoa swollen shoot (carried by mealybugs). Viruses cannot be cured with sprays. We can only prevent them, by killing the vectors, removing sick plants and planting resistant varieties.', 'viral diseases viruses are carried by vectors, mainly sap-sucking insects such as aphids and whiteflies, and by cuttings taken from sick plants. examples: cassava mosaic disease (yellow and green mosaic on leaves, small twisted leaves and a big loss of yield); maize streak virus (yellow streaks along the veins, stunted plants; carried by leafhoppers); groundnut rosette (carried by aphids); cocoa swollen shoot (carried by mealybugs). viruses cannot be cured with sprays. we can only prevent them, by killing the vectors, removing sick plants and planting resistant varieties. diseases of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-08', 5, 'Who causes what?', 'Maize smut: fungus. Citrus canker: bacterium. Cassava mosaic disease: virus. Black pod: fungus (Phytophthora, an oomycete often grouped with fungi). Cassava bacterial blight: bacterium.', 'who causes what? maize smut: fungus. citrus canker: bacterium. cassava mosaic disease: virus. black pod: fungus (phytophthora, an oomycete often grouped with fungi). cassava bacterial blight: bacterium. diseases of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-08', 6, 'Effects of diseases', 'Reduced yield and quality; money lost on chemicals; failure of whole crops in an epidemic; and mycotoxins (poisons made by some fungi, such as aflatoxin in groundnuts and maize) that can harm people and animals.', 'effects of diseases reduced yield and quality; money lost on chemicals; failure of whole crops in an epidemic; and mycotoxins (poisons made by some fungi, such as aflatoxin in groundnuts and maize) that can harm people and animals. diseases of crops ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-09', 'Control of Pests and Diseases') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-09', 0, 'Control of Pests and Diseases: summary', 'Cultural, biological, chemical, physical, legal and genetic control, and the idea of integrated pest management. Key words: Crop rotation, Biological control, Pesticide, Quarantine, Resistant variety, Integrated pest management.', 'control of pests and diseases: summary cultural, biological, chemical, physical, legal and genetic control, and the idea of integrated pest management. key words: crop rotation, biological control, pesticide, quarantine, resistant variety, integrated pest management. control of pests and diseases ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-09', 1, 'Ways of control', 'There is no single best way. Farmers combine several, which is called integrated pest management (IPM).', 'ways of control there is no single best way. farmers combine several, which is called integrated pest management (ipm). control of pests and diseases ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-09', 2, 'The methods', 'Cultural control (changing the way we farm): crop rotation (pests of one crop starve when another is planted); field sanitation (removing and destroying crop remains and weeds that hide pests; burying or composting is better than burning, because open burning pollutes the air); using clean seeds and healthy planting materials; correct spacing for air flow, which lowers the humidity that fungi like; early or late planting to avoid the pest peak; clean weeding. Biological control (using natural enemies): ladybirds eat aphids; the bacterium Bacillus thuringiensis (Bt) kills certain caterpillars but is harmless to people; parasitic wasps lay eggs in pests; encouraging insect-eating birds. It is safe and long-lasting, but slow and works only for some pests. Chemical control (pesticides): insecticides for insects, fungicides for fungi, nematicides for nematodes, rodenticides for rodents, herbicides for weeds. It is fast and effective, but it is expensive, can pollute soil and water, can kill useful insects such as bees, and pests can become resistant. Always follow the label, wear protective clothing and keep chemicals away from children and food. Physical or mechanical control: hand-picking caterpillars; traps (light, sticky and pheromone traps); nets and scarecrows against birds; drying and proper storage of grain; flooding or heating soil. Legal (quarantine) control: laws and inspection at borders to stop foreign pests and diseases from being brought in on seeds and plants. Genetic control (plant breeding): breeding resistant varieties, such as cassava resistant to mosaic disease (the TME varieties) and insect-resistant cowpea.', 'the methods cultural control (changing the way we farm): crop rotation (pests of one crop starve when another is planted); field sanitation (removing and destroying crop remains and weeds that hide pests; burying or composting is better than burning, because open burning pollutes the air); using clean seeds and healthy planting materials; correct spacing for air flow, which lowers the humidity that fungi like; early or late planting to avoid the pest peak; clean weeding. biological control (using natural enemies): ladybirds eat aphids; the bacterium bacillus thuringiensis (bt) kills certain caterpillars but is harmless to people; parasitic wasps lay eggs in pests; encouraging insect-eating birds. it is safe and long-lasting, but slow and works only for some pests. chemical control (pesticides): insecticides for insects, fungicides for fungi, nematicides for nematodes, rodenticides for rodents, herbicides for weeds. it is fast and effective, but it is expensive, can pollute soil and water, can kill useful insects such as bees, and pests can become resistant. always follow the label, wear protective clothing and keep chemicals away from children and food. physical or mechanical control: hand-picking caterpillars; traps (light, sticky and pheromone traps); nets and scarecrows against birds; drying and proper storage of grain; flooding or heating soil. legal (quarantine) control: laws and inspection at borders to stop foreign pests and diseases from being brought in on seeds and plants. genetic control (plant breeding): breeding resistant varieties, such as cassava resistant to mosaic disease (the tme varieties) and insect-resistant cowpea. control of pests and diseases ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-09', 3, 'Biological and chemical control compared', 'Biological: advantage, safe for the environment and long-lasting; disadvantage, slow and may not completely remove the pest. Chemical: advantage, fast and effective; disadvantage, harmful to the environment and non-target organisms, and pests may become resistant.', 'biological and chemical control compared biological: advantage, safe for the environment and long-lasting; disadvantage, slow and may not completely remove the pest. chemical: advantage, fast and effective; disadvantage, harmful to the environment and non-target organisms, and pests may become resistant. control of pests and diseases ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-10', 'Reproduction in Vertebrates: Fertilisation and the Mammalian System') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-10', 0, 'Reproduction in Vertebrates: Fertilisation and the Mammalian System: summary', 'Gonads, gametes, external and internal fertilisation, and the male and female reproductive organs of a mammal. Key words: Gonad, Gamete, Zygote, External fertilisation, Internal fertilisation, Testis, Ovary.', 'reproduction in vertebrates: fertilisation and the mammalian system: summary gonads, gametes, external and internal fertilisation, and the male and female reproductive organs of a mammal. key words: gonad, gamete, zygote, external fertilisation, internal fertilisation, testis, ovary. reproduction in vertebrates: fertilisation and the mammalian system ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-10', 1, 'Sexual reproduction', 'Reproduction produces new individuals. In vertebrates (fish, amphibians, reptiles, birds and mammals) it is mostly sexual: a male gamete (sperm) joins with a female gamete (egg or ovum) to make a zygote. The gonads are the main sex organs that make the gametes: testes in males and ovaries in females. External fertilisation takes place outside the female''s body, usually in water (most fish and amphibians). The female lays eggs and the male sheds sperm over them. Internal fertilisation takes place inside the female''s body (reptiles, birds and mammals). Fewer eggs are needed because more of them are fertilised and protected.', 'sexual reproduction reproduction produces new individuals. in vertebrates (fish, amphibians, reptiles, birds and mammals) it is mostly sexual: a male gamete (sperm) joins with a female gamete (egg or ovum) to make a zygote. the gonads are the main sex organs that make the gametes: testes in males and ovaries in females. external fertilisation takes place outside the female''s body, usually in water (most fish and amphibians). the female lays eggs and the male sheds sperm over them. internal fertilisation takes place inside the female''s body (reptiles, birds and mammals). fewer eggs are needed because more of them are fertilised and protected. reproduction in vertebrates: fertilisation and the mammalian system ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-10', 2, 'The male system of a mammal', 'Testes (2): make sperm and the hormone testosterone. They hang in the scrotum, where the temperature is about 2 to 3 °C lower than the body, which sperm need. Epididymis: a coiled tube where sperm mature and are stored. Vas deferens (sperm duct): carries sperm to the urethra. Glands (seminal vesicles, prostate gland): add fluids that feed and carry the sperm; sperm plus the fluid is semen. Urethra: carries both semen and urine (never at the same time). Penis: places sperm inside the female.', 'the male system of a mammal testes (2): make sperm and the hormone testosterone. they hang in the scrotum, where the temperature is about 2 to 3 °c lower than the body, which sperm need. epididymis: a coiled tube where sperm mature and are stored. vas deferens (sperm duct): carries sperm to the urethra. glands (seminal vesicles, prostate gland): add fluids that feed and carry the sperm; sperm plus the fluid is semen. urethra: carries both semen and urine (never at the same time). penis: places sperm inside the female. reproduction in vertebrates: fertilisation and the mammalian system ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-10', 3, 'The female system of a mammal', 'Ovaries (2): make eggs and the hormones oestrogen and progesterone. Oviduct (Fallopian tube): has a funnel with cilia that catches the egg; fertilisation happens here; the egg is moved to the uterus. Uterus (womb): a muscular organ where the embryo implants and grows into a foetus. Cervix: the neck of the uterus; it opens wide in childbirth. Vagina: the birth canal and the place where sperm are deposited.', 'the female system of a mammal ovaries (2): make eggs and the hormones oestrogen and progesterone. oviduct (fallopian tube): has a funnel with cilia that catches the egg; fertilisation happens here; the egg is moved to the uterus. uterus (womb): a muscular organ where the embryo implants and grows into a foetus. cervix: the neck of the uterus; it opens wide in childbirth. vagina: the birth canal and the place where sperm are deposited. reproduction in vertebrates: fertilisation and the mammalian system ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-10', 4, 'Checking the facts', 'The lesson note says the urethra in males has a dual function (urine and semen); that is correct. In females the urethra only carries urine and opens separately from the vagina.', 'checking the facts the lesson note says the urethra in males has a dual function (urine and semen); that is correct. in females the urethra only carries urine and opens separately from the vagina. reproduction in vertebrates: fertilisation and the mammalian system ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-11', 'Comparing Reproduction in Fish, Amphibians, Reptiles, Birds and Mammals') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-11', 0, 'Comparing Reproduction in Fish, Amphibians, Reptiles, Birds and Mammals: summary', 'A comparison of fertilisation, development and parental care in the five vertebrate classes, the amniotic egg and the trends in evolution. Key words: Oviparous, Viviparous, Metamorphosis, Amniotic egg, Placenta, Lactation.', 'comparing reproduction in fish, amphibians, reptiles, birds and mammals: summary a comparison of fertilisation, development and parental care in the five vertebrate classes, the amniotic egg and the trends in evolution. key words: oviparous, viviparous, metamorphosis, amniotic egg, placenta, lactation. comparing reproduction in fish, amphibians, reptiles, birds and mammals ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-11', 1, 'The five classes compared', 'Study the table. Oviparous means egg-laying with development outside the mother''s body. Viviparous means giving birth to live young that developed inside the mother. Fish (e.g. tilapia); External; External, in soft jelly-covered eggs; Very many small eggs; usually no parental care, so many young die. Amphibians (e.g. frog); External; External, in water or damp places; Tadpole (larva) changes into adult by metamorphosis; little or no parental care. Reptiles (e.g. lizard, snake); Internal; External, in leathery-shelled eggs; Amniotic egg with membranes (amnion, chorion, allantois, yolk sac); no larva; usually little care. Birds (e.g. hen); Internal; External, in hard-shelled eggs; Eggs must be kept warm (incubated); parents feed and protect the chicks. Mammals (e.g. goat, human); Internal; Internal, in the uterus; Placenta feeds the foetus; milk from mammary glands (lactation); long parental care.', 'the five classes compared study the table. oviparous means egg-laying with development outside the mother''s body. viviparous means giving birth to live young that developed inside the mother. fish (e.g. tilapia); external; external, in soft jelly-covered eggs; very many small eggs; usually no parental care, so many young die. amphibians (e.g. frog); external; external, in water or damp places; tadpole (larva) changes into adult by metamorphosis; little or no parental care. reptiles (e.g. lizard, snake); internal; external, in leathery-shelled eggs; amniotic egg with membranes (amnion, chorion, allantois, yolk sac); no larva; usually little care. birds (e.g. hen); internal; external, in hard-shelled eggs; eggs must be kept warm (incubated); parents feed and protect the chicks. mammals (e.g. goat, human); internal; internal, in the uterus; placenta feeds the foetus; milk from mammary glands (lactation); long parental care. comparing reproduction in fish, amphibians, reptiles, birds and mammals ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-11', 2, 'The amniotic egg', 'The amniotic egg is a ''private pond'' for the embryo. A shell protects it; the amnion holds a watery liquid that cushions it; the yolk sac is food; the allantois stores waste and helps with gas exchange; the chorion lets oxygen in. It lets reptiles and birds lay eggs on dry land, so they no longer need water to breed. This was a major step in evolution.', 'the amniotic egg the amniotic egg is a ''private pond'' for the embryo. a shell protects it; the amnion holds a watery liquid that cushions it; the yolk sac is food; the allantois stores waste and helps with gas exchange; the chorion lets oxygen in. it lets reptiles and birds lay eggs on dry land, so they no longer need water to breed. this was a major step in evolution. comparing reproduction in fish, amphibians, reptiles, birds and mammals ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-11', 3, 'Trends from fish to mammals', '1. Fertilisation changes from external to internal (suits life on land). 2. The egg changes from a soft jelly egg to a shelled amniotic egg, and then to development inside the mother. 3. Fewer eggs or young are produced but each has a better chance of survival. 4. Parental care increases in length and complexity. Notes and exceptions: some fish (sharks, guppies) have internal fertilisation and even give birth to live young; some snakes and lizards also give birth to live young; and the platypus and echidna are mammals that lay eggs (monotremes). These exceptions show that the table gives the general pattern.', 'trends from fish to mammals 1. fertilisation changes from external to internal (suits life on land). 2. the egg changes from a soft jelly egg to a shelled amniotic egg, and then to development inside the mother. 3. fewer eggs or young are produced but each has a better chance of survival. 4. parental care increases in length and complexity. notes and exceptions: some fish (sharks, guppies) have internal fertilisation and even give birth to live young; some snakes and lizards also give birth to live young; and the platypus and echidna are mammals that lay eggs (monotremes). these exceptions show that the table gives the general pattern. comparing reproduction in fish, amphibians, reptiles, birds and mammals ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-11', 4, 'Birds versus mammals', 'Birds: internal fertilisation; the egg is laid with a hard shell and the chick develops outside, kept warm by the parent; parents feed it. Mammals: internal fertilisation and internal development; the placenta passes food and oxygen from mother to foetus and takes away waste; after birth, the young are fed on milk. Both show a lot of parental care.', 'birds versus mammals birds: internal fertilisation; the egg is laid with a hard shell and the chick develops outside, kept warm by the parent; parents feed it. mammals: internal fertilisation and internal development; the placenta passes food and oxygen from mother to foetus and takes away waste; after birth, the young are fed on milk. both show a lot of parental care. comparing reproduction in fish, amphibians, reptiles, birds and mammals ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-12', 'The Flower and Its Parts') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-12', 0, 'The Flower and Its Parts: summary', 'The structure and functions of the parts of a flower, from the sepals to the ovule, and how the ovary becomes a fruit and the ovule a seed. Key words: Calyx, Corolla, Stamen, Carpel, Ovary, Ovule.', 'the flower and its parts: summary the structure and functions of the parts of a flower, from the sepals to the ovule, and how the ovary becomes a fruit and the ovule a seed. key words: calyx, corolla, stamen, carpel, ovary, ovule. the flower and its parts ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-12', 1, 'The flower: a shoot for reproduction', 'A flower is the reproductive organ of a flowering plant (angiosperm). It is a shoot whose leaves have changed to do the job of reproduction.', 'the flower: a shoot for reproduction a flower is the reproductive organ of a flowering plant (angiosperm). it is a shoot whose leaves have changed to do the job of reproduction. the flower and its parts ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-12', 2, 'Parts that are not directly reproductive', 'Pedicel: the stalk of a flower. Receptacle: the swollen tip of the pedicel on which the floral parts are fixed. Calyx (the sepals): the outer ring, usually green, which protects the flower while it is still a bud. Corolla (the petals): the next ring, often bright and scented; it attracts insects and other pollinators.', 'parts that are not directly reproductive pedicel: the stalk of a flower. receptacle: the swollen tip of the pedicel on which the floral parts are fixed. calyx (the sepals): the outer ring, usually green, which protects the flower while it is still a bud. corolla (the petals): the next ring, often bright and scented; it attracts insects and other pollinators. the flower and its parts ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-12', 3, 'The male parts: androecium', 'The androecium is made of the stamens. Each stamen has a filament (the thin stalk) and an anther (usually two lobes), which makes pollen grains. Each pollen grain holds the male gamete cells.', 'the male parts: androecium the androecium is made of the stamens. each stamen has a filament (the thin stalk) and an anther (usually two lobes), which makes pollen grains. each pollen grain holds the male gamete cells. the flower and its parts ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-12', 4, 'The female parts: gynoecium (pistil)', 'The gynoecium is made of one or more carpels. Each carpel has a stigma (the sticky top that catches pollen), a style (the tube joining the stigma to the ovary) and an ovary (the swollen base) that contains ovules. Each ovule has an embryo sac with the egg cell. After fertilisation, the ovule becomes the seed and the ovary becomes the fruit. So ''the ovary becomes the fruit and the ovule becomes the seed''.', 'the female parts: gynoecium (pistil) the gynoecium is made of one or more carpels. each carpel has a stigma (the sticky top that catches pollen), a style (the tube joining the stigma to the ovary) and an ovary (the swollen base) that contains ovules. each ovule has an embryo sac with the egg cell. after fertilisation, the ovule becomes the seed and the ovary becomes the fruit. so ''the ovary becomes the fruit and the ovule becomes the seed''. the flower and its parts ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-12', 5, 'How to dissect a flower', 'Use a hibiscus or pride-of-Barbados flower. Remove the sepals and petals, then the stamens. Cut the ovary in half lengthwise with a blade and look at the ovules with a hand lens. Stick the parts on paper and label them. Note whether the flower is bisexual (both stamens and carpels) or unisexual.', 'how to dissect a flower use a hibiscus or pride-of-barbados flower. remove the sepals and petals, then the stamens. cut the ovary in half lengthwise with a blade and look at the ovules with a hand lens. stick the parts on paper and label them. note whether the flower is bisexual (both stamens and carpels) or unisexual. the flower and its parts ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-13', 'Types of Flowers: Bisexual, Unisexual, Monoecious, Dioecious, Monocot and Dicot') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-13', 0, 'Types of Flowers: Bisexual, Unisexual, Monoecious, Dioecious, Monocot and Dicot: summary', 'Classifying flowers by their sex organs and plants by where the male and female flowers are, plus a comparison of monocot and dicot flowers. Key words: Bisexual, Unisexual, Monoecious, Dioecious, Monocot, Dicot.', 'types of flowers: bisexual, unisexual, monoecious, dioecious, monocot and dicot: summary classifying flowers by their sex organs and plants by where the male and female flowers are, plus a comparison of monocot and dicot flowers. key words: bisexual, unisexual, monoecious, dioecious, monocot, dicot. types of flowers: bisexual, unisexual, monoecious, dioecious, monocot and dicot ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-13', 1, 'By the sex organs in the flower', 'Bisexual (hermaphrodite or perfect) flowers have both stamens and carpels, for example hibiscus, tomato, pride of Barbados. Unisexual (imperfect) flowers have only one sex: a staminate (male) flower has stamens only; a pistillate (female) flower has carpels only.', 'by the sex organs in the flower bisexual (hermaphrodite or perfect) flowers have both stamens and carpels, for example hibiscus, tomato, pride of barbados. unisexual (imperfect) flowers have only one sex: a staminate (male) flower has stamens only; a pistillate (female) flower has carpels only. types of flowers: bisexual, unisexual, monoecious, dioecious, monocot and dicot ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-13', 2, 'By where the unisexual flowers are found', 'Monoecious plants (''one house'') carry male and female flowers on the same plant, for example maize (the male flowers form the tassel at the top and the female flowers form the cob), coconut, cucumber and castor oil. Dioecious plants (''two houses'') have male flowers on one plant and female flowers on another, for example pawpaw (most plants) and date palm. In dioecious plants a male plant must be near females for pollination to occur.', 'by where the unisexual flowers are found monoecious plants (''one house'') carry male and female flowers on the same plant, for example maize (the male flowers form the tassel at the top and the female flowers form the cob), coconut, cucumber and castor oil. dioecious plants (''two houses'') have male flowers on one plant and female flowers on another, for example pawpaw (most plants) and date palm. in dioecious plants a male plant must be near females for pollination to occur. types of flowers: bisexual, unisexual, monoecious, dioecious, monocot and dicot ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-13', 3, 'Monocot and dicot flowers', 'Study the table. Number of floral parts; In threes or multiples of three; In fours or fives, or multiples. Sepals and petals; Often alike in colour and shape (called tepals); Usually different: green sepals and coloured petals. Leaf veins; Parallel; Net-like (reticulate). Seed leaves; One; Two. Roots; Fibrous; Tap root.', 'monocot and dicot flowers study the table. number of floral parts; in threes or multiples of three; in fours or fives, or multiples. sepals and petals; often alike in colour and shape (called tepals); usually different: green sepals and coloured petals. leaf veins; parallel; net-like (reticulate). seed leaves; one; two. roots; fibrous; tap root. types of flowers: bisexual, unisexual, monoecious, dioecious, monocot and dicot ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-13', 4, 'Worked example', 'A flower has 6 petals and 6 stamens. It is probably a monocot, because 6 is a multiple of 3. (To be sure, also check the leaf veins: if they are parallel, it is a monocot.)', 'worked example a flower has 6 petals and 6 stamens. it is probably a monocot, because 6 is a multiple of 3. (to be sure, also check the leaf veins: if they are parallel, it is a monocot.) types of flowers: bisexual, unisexual, monoecious, dioecious, monocot and dicot ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-13', 5, 'Corrections and cautions', 'The lesson note names maize as monoecious: correct. Oil palm is also monoecious (male and female flower clusters on the same tree, at different times), so do not use it as a dioecious example. Rules about ''multiples of 3 or 4/5'' are guides only; a few plants break them.', 'corrections and cautions the lesson note names maize as monoecious: correct. oil palm is also monoecious (male and female flower clusters on the same tree, at different times), so do not use it as a dioecious example. rules about ''multiples of 3 or 4/5'' are guides only; a few plants break them. types of flowers: bisexual, unisexual, monoecious, dioecious, monocot and dicot ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-14', 'Pollination: Self and Cross') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-14', 0, 'Pollination: Self and Cross: summary', 'What pollination is, how it differs from fertilisation, self- and cross-pollination and the ways plants avoid self-pollination. Key words: Pollination, Self-pollination, Cross-pollination, Dichogamy, Self-incompatibility, Herkogamy.', 'pollination: self and cross: summary what pollination is, how it differs from fertilisation, self- and cross-pollination and the ways plants avoid self-pollination. key words: pollination, self-pollination, cross-pollination, dichogamy, self-incompatibility, herkogamy. pollination: self and cross ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-14', 1, 'What is pollination?', 'Pollination is the transfer of pollen grains from the anther to the stigma. It comes before fertilisation but is not the same. Fertilisation is the joining of the male gamete (from the pollen) with the egg cell in the ovule, after the pollen grain has grown a pollen tube down the style.', 'what is pollination? pollination is the transfer of pollen grains from the anther to the stigma. it comes before fertilisation but is not the same. fertilisation is the joining of the male gamete (from the pollen) with the egg cell in the ovule, after the pollen grain has grown a pollen tube down the style. pollination: self and cross ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-14', 2, 'Self-pollination (autogamy)', 'Pollen goes from the anther to the stigma of the same flower or another flower on the same plant. Because all the genes come from one parent, the offspring are almost identical to the parent and to each other (strictly, clones are produced only if the parent is pure-breeding). Advantages: seed is certain even if pollinators are absent; the plant does not waste energy on petals, scent and nectar; good traits are kept. Disadvantages: little variation, so a disease can kill all the plants; harmful genes can appear (inbreeding depression); the crop may weaken over generations.', 'self-pollination (autogamy) pollen goes from the anther to the stigma of the same flower or another flower on the same plant. because all the genes come from one parent, the offspring are almost identical to the parent and to each other (strictly, clones are produced only if the parent is pure-breeding). advantages: seed is certain even if pollinators are absent; the plant does not waste energy on petals, scent and nectar; good traits are kept. disadvantages: little variation, so a disease can kill all the plants; harmful genes can appear (inbreeding depression); the crop may weaken over generations. pollination: self and cross ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-14', 3, 'Cross-pollination (allogamy)', 'Pollen goes from the anther of one plant to the stigma of a flower on a different plant of the same species. Advantages: new gene combinations, more variation and healthier, stronger offspring (hybrid vigour); a better chance of adapting to change. Disadvantages: depends on agents such as wind and insects; uncertain; much pollen is wasted; the plant must spend energy on attracting pollinators.', 'cross-pollination (allogamy) pollen goes from the anther of one plant to the stigma of a flower on a different plant of the same species. advantages: new gene combinations, more variation and healthier, stronger offspring (hybrid vigour); a better chance of adapting to change. disadvantages: depends on agents such as wind and insects; uncertain; much pollen is wasted; the plant must spend energy on attracting pollinators. pollination: self and cross ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-14', 4, 'How plants avoid self-pollination', 'Dichogamy: the anthers and stigmas ripen at different times. Protandry: the anthers ripen first (sunflower). Protogyny: the stigma ripens first (avocado pear). Self-incompatibility: the plant''s own pollen cannot grow on its own stigma, or the pollen tube stops in the style (cocoa). Herkogamy (structural barrier): the stigma is higher or lower than the anthers so that pollen cannot fall on it (primrose). Dioecious plants: male and female flowers on different plants (pawpaw). Monoecious plants such as maize also help cross-pollination because the male and female flowers are in different places.', 'how plants avoid self-pollination dichogamy: the anthers and stigmas ripen at different times. protandry: the anthers ripen first (sunflower). protogyny: the stigma ripens first (avocado pear). self-incompatibility: the plant''s own pollen cannot grow on its own stigma, or the pollen tube stops in the style (cocoa). herkogamy (structural barrier): the stigma is higher or lower than the anthers so that pollen cannot fall on it (primrose). dioecious plants: male and female flowers on different plants (pawpaw). monoecious plants such as maize also help cross-pollination because the male and female flowers are in different places. pollination: self and cross ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-15', 'Agents of Pollination: Wind, Insects, Birds and Bats') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-15', 0, 'Agents of Pollination: Wind, Insects, Birds and Bats: summary', 'The adaptations of flowers and pollen to wind, insects, birds and bats, with examples and a comparison of wind- and insect-pollinated flowers. Key words: Anemophily, Entomophily, Ornithophily, Chiropterophily, Nectar, Stigma.', 'agents of pollination: wind, insects, birds and bats: summary the adaptations of flowers and pollen to wind, insects, birds and bats, with examples and a comparison of wind- and insect-pollinated flowers. key words: anemophily, entomophily, ornithophily, chiropterophily, nectar, stigma. agents of pollination: wind, insects, birds and bats ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-15', 1, 'Four main agents', 'Study the table. Wind (anemophily); Small, dull, no scent or nectar; stamens hang outside the flower; large, feathery, long stigmas to catch pollen; Light, smooth, dry and dusty; made in huge amounts; Grasses, maize, rice, millet, sugar cane. Insects (entomophily); Large, bright petals; scent; nectar; guide marks that show insects the way in; sticky stigma inside the flower; Sticky or spiny to cling to the insect; made in smaller amounts; Hibiscus, sunflower, pride of Barbados, orange, beans, orchids. Birds (ornithophily); Bright red or orange; tubular; lots of watery nectar; little scent (birds smell poorly); Sticky; Some hibiscus, kapok (silk cotton tree), Erythrina (coral tree). Bats (chiropterophily); Open at night; large and strong; dull white or green; strong musty or fruity smell; Plenty, sticky; Baobab, Parkia (locust bean tree, ''dawadawa''), agave.', 'four main agents study the table. wind (anemophily); small, dull, no scent or nectar; stamens hang outside the flower; large, feathery, long stigmas to catch pollen; light, smooth, dry and dusty; made in huge amounts; grasses, maize, rice, millet, sugar cane. insects (entomophily); large, bright petals; scent; nectar; guide marks that show insects the way in; sticky stigma inside the flower; sticky or spiny to cling to the insect; made in smaller amounts; hibiscus, sunflower, pride of barbados, orange, beans, orchids. birds (ornithophily); bright red or orange; tubular; lots of watery nectar; little scent (birds smell poorly); sticky; some hibiscus, kapok (silk cotton tree), erythrina (coral tree). bats (chiropterophily); open at night; large and strong; dull white or green; strong musty or fruity smell; plenty, sticky; baobab, parkia (locust bean tree, ''dawadawa''), agave. agents of pollination: wind, insects, birds and bats ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-15', 2, 'Wind and insect flowers compared', 'A wind-pollinated flower such as maize has exposed, hanging stamens that shake pollen into the wind, and feathery stigmas. A disadvantage compared with insect pollination is that it is wasteful: much pollen is lost and the chance of reaching a stigma is small. An insect-pollinated flower such as hibiscus ''advertises'' with colour and scent, rewards the visitor with nectar, and places sticky pollen on the insect''s body, so pollen reaches the right flower more accurately.', 'wind and insect flowers compared a wind-pollinated flower such as maize has exposed, hanging stamens that shake pollen into the wind, and feathery stigmas. a disadvantage compared with insect pollination is that it is wasteful: much pollen is lost and the chance of reaching a stigma is small. an insect-pollinated flower such as hibiscus ''advertises'' with colour and scent, rewards the visitor with nectar, and places sticky pollen on the insect''s body, so pollen reaches the right flower more accurately. agents of pollination: wind, insects, birds and bats ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-15', 3, 'Three adaptations of an insect-pollinated flower', '1. Large coloured petals attract insects from a distance. 2. Nectar gives the insect a reward so it keeps coming back. 3. Sticky or rough pollen sticks to the insect''s body and is carried to the next flower. 4. A sticky stigma inside the flower catches pollen from the visiting insect.', 'three adaptations of an insect-pollinated flower 1. large coloured petals attract insects from a distance. 2. nectar gives the insect a reward so it keeps coming back. 3. sticky or rough pollen sticks to the insect''s body and is carried to the next flower. 4. a sticky stigma inside the flower catches pollen from the visiting insect. agents of pollination: wind, insects, birds and bats ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-15', 4, 'Why this matters to people', 'Many crops need insect pollinators. In Nigeria, bees pollinate cashew, oranges, melon and cowpea. Protecting bees from careless pesticide use protects our food. Bats pollinate and spread seeds of the locust bean tree. Learn to see farms as part of the ecosystem.', 'why this matters to people many crops need insect pollinators. in nigeria, bees pollinate cashew, oranges, melon and cowpea. protecting bees from careless pesticide use protects our food. bats pollinate and spread seeds of the locust bean tree. learn to see farms as part of the ecosystem. agents of pollination: wind, insects, birds and bats ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-16', 'Homeostasis and Temperature Control') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-16', 0, 'Homeostasis and Temperature Control: summary', 'The meaning of homeostasis, negative feedback, and how the body keeps its temperature steady in hot and cold conditions. Key words: Homeostasis, Negative feedback, Hypothalamus, Vasodilation, Vasoconstriction, Shivering.', 'homeostasis and temperature control: summary the meaning of homeostasis, negative feedback, and how the body keeps its temperature steady in hot and cold conditions. key words: homeostasis, negative feedback, hypothalamus, vasodilation, vasoconstriction, shivering. homeostasis and temperature control ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-16', 1, 'What is homeostasis?', 'Homeostasis is the keeping of a steady internal environment in the body even when the outside conditions change. Cells and enzymes work best in narrow conditions. Examples of conditions that are regulated: body temperature (about 37 °C), blood glucose, water and salt content, blood pH and blood pressure.', 'what is homeostasis? homeostasis is the keeping of a steady internal environment in the body even when the outside conditions change. cells and enzymes work best in narrow conditions. examples of conditions that are regulated: body temperature (about 37 °c), blood glucose, water and salt content, blood ph and blood pressure. homeostasis and temperature control ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-16', 2, 'Negative feedback', 'Homeostasis works mainly by negative feedback. A change is detected, and the body acts to reverse it and bring the level back to the set point. Steps: stimulus (a change) → receptor (detects it) → control centre (the brain or an organ that compares it with the set point) → effector (a muscle or gland that acts) → response (restores normal level), and the loop goes on. Think of an air-conditioner with a thermostat: when the room is too hot it switches on; when it is cool enough it switches off.', 'negative feedback homeostasis works mainly by negative feedback. a change is detected, and the body acts to reverse it and bring the level back to the set point. steps: stimulus (a change) → receptor (detects it) → control centre (the brain or an organ that compares it with the set point) → effector (a muscle or gland that acts) → response (restores normal level), and the loop goes on. think of an air-conditioner with a thermostat: when the room is too hot it switches on; when it is cool enough it switches off. homeostasis and temperature control ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-16', 3, 'Control of body temperature', 'The control centre is the hypothalamus in the brain. It receives information from temperature receptors in the skin and in the blood. If the body is too hot: vasodilation (the blood vessels in the skin widen, more blood flows near the surface and heat is lost by radiation); sweating (sweat evaporates and takes heat from the skin); the erector pili muscles relax and the hairs lie flat (less trapped air); behaviour, such as resting in shade and drinking. If the body is too cold: vasoconstriction (the skin blood vessels narrow, less heat is lost); shivering (rapid muscle contractions release heat); the erector pili muscles contract and hairs stand up, trapping air (goose pimples; they are useful in furry animals but only a remnant in humans); thyroxine and adrenaline increase the metabolic rate; stopping sweating; behaviour, such as putting on clothes.', 'control of body temperature the control centre is the hypothalamus in the brain. it receives information from temperature receptors in the skin and in the blood. if the body is too hot: vasodilation (the blood vessels in the skin widen, more blood flows near the surface and heat is lost by radiation); sweating (sweat evaporates and takes heat from the skin); the erector pili muscles relax and the hairs lie flat (less trapped air); behaviour, such as resting in shade and drinking. if the body is too cold: vasoconstriction (the skin blood vessels narrow, less heat is lost); shivering (rapid muscle contractions release heat); the erector pili muscles contract and hairs stand up, trapping air (goose pimples; they are useful in furry animals but only a remnant in humans); thyroxine and adrenaline increase the metabolic rate; stopping sweating; behaviour, such as putting on clothes. homeostasis and temperature control ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-16', 4, 'Fever', 'In an infection, the set point is raised, so the body feels cold and shivers until the temperature reaches the new level (fever). When the infection is over, the set point returns to normal and the body sweats. A very high fever (above 40 °C) is dangerous. Note: homeostasis is possible only in warm-blooded animals (birds and mammals) in the sense of keeping a constant body temperature; reptiles and fish depend on the surroundings.', 'fever in an infection, the set point is raised, so the body feels cold and shivers until the temperature reaches the new level (fever). when the infection is over, the set point returns to normal and the body sweats. a very high fever (above 40 °c) is dangerous. note: homeostasis is possible only in warm-blooded animals (birds and mammals) in the sense of keeping a constant body temperature; reptiles and fish depend on the surroundings. homeostasis and temperature control ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T2:b22-17', 'Controlling Blood Sugar and Water: More Examples of Homeostasis') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-17', 0, 'Controlling Blood Sugar and Water: More Examples of Homeostasis: summary', 'Insulin and glucagon in blood glucose control, diabetes, and a recap of osmoregulation with ADH as negative feedback. Key words: Insulin, Glucagon, Pancreas, Diabetes mellitus, ADH, Osmoregulation.', 'controlling blood sugar and water: more examples of homeostasis: summary insulin and glucagon in blood glucose control, diabetes, and a recap of osmoregulation with adh as negative feedback. key words: insulin, glucagon, pancreas, diabetes mellitus, adh, osmoregulation. controlling blood sugar and water: more examples of homeostasis ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-17', 1, 'Blood glucose', 'The blood glucose level is kept at about 4 to 6 mmol per litre (roughly 70 to 100 mg per 100 ml). Special cells of the pancreas (islets of Langerhans) detect it and make two hormones that work in opposite ways. After a meal, blood glucose rises. The pancreas releases insulin. Insulin makes the liver and muscle cells take up glucose and turn it into glycogen, and makes cells use more glucose. Blood glucose falls. If blood glucose falls (between meals or in exercise), the pancreas releases glucagon. Glucagon makes the liver change glycogen to glucose, so blood glucose rises. Together insulin and glucagon are a negative feedback pair.', 'blood glucose the blood glucose level is kept at about 4 to 6 mmol per litre (roughly 70 to 100 mg per 100 ml). special cells of the pancreas (islets of langerhans) detect it and make two hormones that work in opposite ways. after a meal, blood glucose rises. the pancreas releases insulin. insulin makes the liver and muscle cells take up glucose and turn it into glycogen, and makes cells use more glucose. blood glucose falls. if blood glucose falls (between meals or in exercise), the pancreas releases glucagon. glucagon makes the liver change glycogen to glucose, so blood glucose rises. together insulin and glucagon are a negative feedback pair. controlling blood sugar and water: more examples of homeostasis ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-17', 2, 'Diabetes mellitus', 'In diabetes, the blood glucose stays too high. In type 1 diabetes the pancreas does not make enough insulin; the person needs insulin injections, a healthy diet and exercise. In type 2 diabetes, the body cells do not respond well to insulin; it is linked to overweight and lack of exercise, and is managed with diet, exercise and medicine. Signs: thirst, passing much urine, tiredness, weight loss and glucose in the urine. Untreated diabetes can damage the eyes, kidneys, nerves and heart.', 'diabetes mellitus in diabetes, the blood glucose stays too high. in type 1 diabetes the pancreas does not make enough insulin; the person needs insulin injections, a healthy diet and exercise. in type 2 diabetes, the body cells do not respond well to insulin; it is linked to overweight and lack of exercise, and is managed with diet, exercise and medicine. signs: thirst, passing much urine, tiredness, weight loss and glucose in the urine. untreated diabetes can damage the eyes, kidneys, nerves and heart. controlling blood sugar and water: more examples of homeostasis ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-17', 3, 'Water balance with ADH', 'This was explained in the first term. When the blood is too concentrated (dehydrated), the hypothalamus detects it, the pituitary releases more ADH, the collecting ducts reabsorb more water, and a small amount of concentrated urine is passed. When the blood is too dilute (over-hydrated), less ADH is released, less water is reabsorbed, and a large amount of dilute urine is passed. This is negative feedback.', 'water balance with adh this was explained in the first term. when the blood is too concentrated (dehydrated), the hypothalamus detects it, the pituitary releases more adh, the collecting ducts reabsorb more water, and a small amount of concentrated urine is passed. when the blood is too dilute (over-hydrated), less adh is released, less water is reabsorbed, and a large amount of dilute urine is passed. this is negative feedback. controlling blood sugar and water: more examples of homeostasis ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-17', 4, 'Summary of homeostatic systems', 'Compare these systems. Temperature; Hypothalamus; Skin vessels, sweat glands, muscles; Steady 37 °C. Blood glucose; Pancreas; Insulin and glucagon acting on liver; Steady blood sugar. Water; Hypothalamus and pituitary; ADH acting on kidney tubules; Steady water content.', 'summary of homeostatic systems compare these systems. temperature; hypothalamus; skin vessels, sweat glands, muscles; steady 37 °c. blood glucose; pancreas; insulin and glucagon acting on liver; steady blood sugar. water; hypothalamus and pituitary; adh acting on kidney tubules; steady water content. controlling blood sugar and water: more examples of homeostasis ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
