INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-18', 0, 'Second Term Revision: summary', 'A revision guide of the term''s topics with worked answers to the self-test questions on pollination, reproduction, a crop disease, cold-response and negative feedback. Key words: Revision, Symbiosis, Eutrophication, Vector, Negative feedback.', 'second term revision: summary a revision guide of the term''s topics with worked answers to the self-test questions on pollination, reproduction, a crop disease, cold-response and negative feedback. key words: revision, symbiosis, eutrophication, vector, negative feedback. second term revision ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-18', 1, 'Topic checklist', 'Ecology: levels of organisation; the five associations (mutualism, commensalism, parasitism, predation, competition) with examples; Shelford''s law; structural, physiological and behavioural adaptations. Pollution: air, water, soil and noise: three causes, three effects and three controls each; eutrophication in steps. Conservation: conservation and preservation; methods for soil, water, forest and wildlife. Pests and diseases: biting, piercing and boring pests; fungal, bacterial and viral diseases; five kinds of control. Vertebrate reproduction: external and internal fertilisation; the amniotic egg; the trends from fish to mammals. Plants: parts of a flower; bisexual or unisexual; monoecious or dioecious; monocot or dicot; pollination, its types, agents and adaptations. Homeostasis: negative feedback; temperature control; blood sugar; water (ADH).', 'topic checklist ecology: levels of organisation; the five associations (mutualism, commensalism, parasitism, predation, competition) with examples; shelford''s law; structural, physiological and behavioural adaptations. pollution: air, water, soil and noise: three causes, three effects and three controls each; eutrophication in steps. conservation: conservation and preservation; methods for soil, water, forest and wildlife. pests and diseases: biting, piercing and boring pests; fungal, bacterial and viral diseases; five kinds of control. vertebrate reproduction: external and internal fertilisation; the amniotic egg; the trends from fish to mammals. plants: parts of a flower; bisexual or unisexual; monoecious or dioecious; monocot or dicot; pollination, its types, agents and adaptations. homeostasis: negative feedback; temperature control; blood sugar; water (adh). second term revision ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-18', 2, 'Worked answers to the checkpoint', '1. Wind-pollinated flower: small, dull petals (no need to attract insects); stamens hang outside so that the wind can blow the light pollen away; long, feathery stigmas hang out to catch pollen from the air; pollen is light, smooth and plentiful. Disadvantage: it is wasteful and not accurate; most pollen never reaches a stigma, unlike insect pollination, where the insect carries pollen straight to another flower. 2. Reptile and mammal (lizard and goat): fertilisation is internal in both; the lizard lays leathery-shelled eggs outside the body, while the goat''s young develop inside the uterus; the lizard''s embryo feeds on yolk, the goat''s foetus feeds through the placenta; the lizard gives no milk, the kid is fed on milk; the lizard gives little or no parental care, the goat gives a lot. 3. Maize with stunted growth and yellow streaks along the veins: this is maize streak virus. The vector is the leafhopper. Control: remove infected plants, use resistant varieties, spray insecticide on the leafhoppers or use a natural enemy, weed the field, and avoid planting near old maize. 4. Response to a fall in temperature: skin receptors detect the cold and send impulses to the hypothalamus. The hypothalamus sends impulses to the skin and muscles: the skin blood vessels narrow (vasoconstriction), sweating stops, the hairs stand up and trap air, the muscles shiver and release heat, and thyroxine and adrenaline raise metabolism. Body temperature returns to 37 °C. 5. Negative feedback with water: if the blood is too concentrated, more ADH is released and more water is reabsorbed; the blood becomes more dilute and ADH falls. If the blood is too dilute, less ADH is released and more water is lost in urine. The change is always reversed.', 'worked answers to the checkpoint 1. wind-pollinated flower: small, dull petals (no need to attract insects); stamens hang outside so that the wind can blow the light pollen away; long, feathery stigmas hang out to catch pollen from the air; pollen is light, smooth and plentiful. disadvantage: it is wasteful and not accurate; most pollen never reaches a stigma, unlike insect pollination, where the insect carries pollen straight to another flower. 2. reptile and mammal (lizard and goat): fertilisation is internal in both; the lizard lays leathery-shelled eggs outside the body, while the goat''s young develop inside the uterus; the lizard''s embryo feeds on yolk, the goat''s foetus feeds through the placenta; the lizard gives no milk, the kid is fed on milk; the lizard gives little or no parental care, the goat gives a lot. 3. maize with stunted growth and yellow streaks along the veins: this is maize streak virus. the vector is the leafhopper. control: remove infected plants, use resistant varieties, spray insecticide on the leafhoppers or use a natural enemy, weed the field, and avoid planting near old maize. 4. response to a fall in temperature: skin receptors detect the cold and send impulses to the hypothalamus. the hypothalamus sends impulses to the skin and muscles: the skin blood vessels narrow (vasoconstriction), sweating stops, the hairs stand up and trap air, the muscles shiver and release heat, and thyroxine and adrenaline raise metabolism. body temperature returns to 37 °c. 5. negative feedback with water: if the blood is too concentrated, more adh is released and more water is reabsorbed; the blood becomes more dilute and adh falls. if the blood is too dilute, less adh is released and more water is lost in urine. the change is always reversed. second term revision ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T2', 'NG-SS2-BIO-T2:b22-18', 3, 'A reminder about study methods', 'Use active recall (test yourself without notes), spaced revision, teaching a friend, and timed past questions. For each topic you rate 3 or less out of 5, write one action you will take.', 'a reminder about study methods use active recall (test yourself without notes), spaced revision, teaching a friend, and timed past questions. for each topic you rate 3 or less out of 5, write one action you will take. second term revision ss2 biology, term 2') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
