INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-01', 0, 'Welcome and Table of Contents: summary', 'Welcome to SS2 Biology Third Term: the nervous system, sense organs, populations and ecosystems, human reproduction, seeds, fruits and animal behaviour. Key words: SS2 Biology - Third Term, Syllabus, Table of contents.', 'welcome and table of contents: summary welcome to ss2 biology third term: the nervous system, sense organs, populations and ecosystems, human reproduction, seeds, fruits and animal behaviour. key words: ss2 biology - third term, syllabus, table of contents. welcome and table of contents ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-01', 1, 'Welcome to SS2 Biology - Third Term', 'Welcome to SS2 Biology, Third Term. This term explains how the body senses and responds to the world through nerves, the brain and the sense organs, how populations and ecosystems work, how humans reproduce, how flowering plants make seeds and fruits, and how animals court and care for their young. Read each unit slowly, study the pictures and answer the short check questions. Where the original lesson note needed a correction or a Nigerian example, it is explained in the unit.', 'welcome to ss2 biology - third term welcome to ss2 biology, third term. this term explains how the body senses and responds to the world through nerves, the brain and the sense organs, how populations and ecosystems work, how humans reproduce, how flowering plants make seeds and fruits, and how animals court and care for their young. read each unit slowly, study the pictures and answer the short check questions. where the original lesson note needed a correction or a nigerian example, it is explained in the unit. welcome and table of contents ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-01', 2, 'Table of contents for SS2 Biology - Third Term', 'Here is the plan for the term. Tick each unit when you finish it. 1; -; Welcome and table of contents. 2; 1; Coordination and the Neuron. 3; 1; How a Nerve Impulse Travels and Crosses a Synapse. 4; 1; The Central Nervous System: Brain and Spinal Cord. 5; 1; The Peripheral and Autonomic Nervous System and Reflex Actions. 6; 2; The Eye: Structure and How We See. 7; 2; Accommodation, the Pupil Reflex and Defects of the Eye. 8; 2; The Ear: Hearing and Balance. 9; 2; Nose, Tongue and Skin: Smell, Taste and Touch. 10; 3; Ecology of Population: Size, Density, Growth and Limiting Factors. 11; 3; Estimating Population Size: Quadrats and Capture-Mark-Recapture. 12; 4; The Ecosystem, Food Chains, Food Webs and Energy Flow. 13; 4; Ecological Pyramids, Cycles and the Balance of Nature. 14; 6; The Male Reproductive System. 15; 6; The Female Reproductive System and the Gametes. 16; 6; Ovulation and the Menstrual Cycle. 17; 6; Fertilisation, Pregnancy and Birth. 18; 8; From Pollination to Fertilisation in Flowering Plants. 19; 8; The Structure of Seeds: Bean and Maize. 20; 8; Germination of Seeds. 21; 9; Fruits: Structure and Classification. 22; 9; Seed and Fruit Dispersal and Parthenocarpy. 23; 10; Courtship Behaviour in Animals. 24; 10; Parental Care in Animals. 25; 11; Third Term Revision and Exam Practice.', 'table of contents for ss2 biology - third term here is the plan for the term. tick each unit when you finish it. 1; -; welcome and table of contents. 2; 1; coordination and the neuron. 3; 1; how a nerve impulse travels and crosses a synapse. 4; 1; the central nervous system: brain and spinal cord. 5; 1; the peripheral and autonomic nervous system and reflex actions. 6; 2; the eye: structure and how we see. 7; 2; accommodation, the pupil reflex and defects of the eye. 8; 2; the ear: hearing and balance. 9; 2; nose, tongue and skin: smell, taste and touch. 10; 3; ecology of population: size, density, growth and limiting factors. 11; 3; estimating population size: quadrats and capture-mark-recapture. 12; 4; the ecosystem, food chains, food webs and energy flow. 13; 4; ecological pyramids, cycles and the balance of nature. 14; 6; the male reproductive system. 15; 6; the female reproductive system and the gametes. 16; 6; ovulation and the menstrual cycle. 17; 6; fertilisation, pregnancy and birth. 18; 8; from pollination to fertilisation in flowering plants. 19; 8; the structure of seeds: bean and maize. 20; 8; germination of seeds. 21; 9; fruits: structure and classification. 22; 9; seed and fruit dispersal and parthenocarpy. 23; 10; courtship behaviour in animals. 24; 10; parental care in animals. 25; 11; third term revision and exam practice. welcome and table of contents ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-02', 'Coordination and the Neuron') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-02', 0, 'Coordination and the Neuron: summary', 'Why animals need coordination, the nervous and endocrine systems compared, and the structure and kinds of neuron. Key words: Stimulus, Coordination, Neuron, Axon, Dendrite, Myelin sheath, Node of Ranvier.', 'coordination and the neuron: summary why animals need coordination, the nervous and endocrine systems compared, and the structure and kinds of neuron. key words: stimulus, coordination, neuron, axon, dendrite, myelin sheath, node of ranvier. coordination and the neuron ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-02', 1, 'Detecting change and responding', 'Living things must detect changes (stimuli) inside and outside the body and respond correctly so that the body stays balanced (homeostasis). In animals, two systems work together to do this. The nervous system sends fast electrical messages that act quickly and last a short time. The endocrine system sends chemical messages (hormones) in the blood that act slowly and last longer. Compare them: nervous messages travel along nerves, are very fast (milliseconds), act on a small area (a muscle or gland) and stop quickly, for example pulling your hand from a hot pot. Hormonal messages travel in the blood, are slow (seconds to hours), may act on many organs and may last a long time, for example growth hormone or insulin.', 'detecting change and responding living things must detect changes (stimuli) inside and outside the body and respond correctly so that the body stays balanced (homeostasis). in animals, two systems work together to do this. the nervous system sends fast electrical messages that act quickly and last a short time. the endocrine system sends chemical messages (hormones) in the blood that act slowly and last longer. compare them: nervous messages travel along nerves, are very fast (milliseconds), act on a small area (a muscle or gland) and stop quickly, for example pulling your hand from a hot pot. hormonal messages travel in the blood, are slow (seconds to hours), may act on many organs and may last a long time, for example growth hormone or insulin. coordination and the neuron ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-02', 2, 'The neuron: the basic unit', 'The nervous system contains billions of nerve cells called neurons, supported by glial cells (neuroglia), which feed and protect them.', 'the neuron: the basic unit the nervous system contains billions of nerve cells called neurons, supported by glial cells (neuroglia), which feed and protect them. coordination and the neuron ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-02', 3, 'Parts of a neuron', 'Cell body (soma): has the nucleus, many mitochondria for energy and Nissl granules (groups of ribosomes that make proteins). Dendrites: short, much-branched fibres that receive messages and carry them towards the cell body. Axon: one long fibre that carries impulses away from the cell body; its cytoplasm is the axoplasm and its membrane is the axolemma. Myelin sheath: a fatty insulating layer made by Schwann cells (in nerves) or oligodendrocytes (in the brain and spinal cord); it stops the signal leaking out and makes it faster. Nodes of Ranvier: gaps in the myelin where the axon membrane is exposed. Synaptic knobs: swellings at the end of the axon that contain vesicles full of chemicals called neurotransmitters.', 'parts of a neuron cell body (soma): has the nucleus, many mitochondria for energy and nissl granules (groups of ribosomes that make proteins). dendrites: short, much-branched fibres that receive messages and carry them towards the cell body. axon: one long fibre that carries impulses away from the cell body; its cytoplasm is the axoplasm and its membrane is the axolemma. myelin sheath: a fatty insulating layer made by schwann cells (in nerves) or oligodendrocytes (in the brain and spinal cord); it stops the signal leaking out and makes it faster. nodes of ranvier: gaps in the myelin where the axon membrane is exposed. synaptic knobs: swellings at the end of the axon that contain vesicles full of chemicals called neurotransmitters. coordination and the neuron ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-02', 4, 'Kinds of neuron', 'Sensory (afferent) neurons carry impulses from receptors (skin, eyes, ears) to the central nervous system (CNS); the cell body sits to one side (unipolar). Motor (efferent) neurons carry impulses from the CNS to effectors (muscles and glands); they are multipolar. Relay neurons (interneurons) lie wholly in the CNS and link sensory to motor neurons and process information. The CNS is the brain and spinal cord; the peripheral nervous system (PNS) is all the nerves outside.', 'kinds of neuron sensory (afferent) neurons carry impulses from receptors (skin, eyes, ears) to the central nervous system (cns); the cell body sits to one side (unipolar). motor (efferent) neurons carry impulses from the cns to effectors (muscles and glands); they are multipolar. relay neurons (interneurons) lie wholly in the cns and link sensory to motor neurons and process information. the cns is the brain and spinal cord; the peripheral nervous system (pns) is all the nerves outside. coordination and the neuron ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-03', 'How a Nerve Impulse Travels and Crosses a Synapse') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-03', 0, 'How a Nerve Impulse Travels and Crosses a Synapse: summary', 'The resting potential, the action potential, saltatory conduction and synaptic transmission with neurotransmitters. Key words: Resting potential, Action potential, Depolarisation, Sodium-potassium pump, Synapse, Neurotransmitter.', 'how a nerve impulse travels and crosses a synapse: summary the resting potential, the action potential, saltatory conduction and synaptic transmission with neurotransmitters. key words: resting potential, action potential, depolarisation, sodium-potassium pump, synapse, neurotransmitter. how a nerve impulse travels and crosses a synapse ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-03', 1, 'A nerve impulse is not an electric current in a wire', 'It is a travelling wave of electrical and chemical change along the surface of the axon, much slower than a current in a wire.', 'a nerve impulse is not an electric current in a wire it is a travelling wave of electrical and chemical change along the surface of the axon, much slower than a current in a wire. how a nerve impulse travels and crosses a synapse ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-03', 2, 'The resting potential', 'A neuron at rest is like a charged battery: the inside of the axon is negative (about –70 mV) compared with the outside. This is called polarised. It happens because (1) the membrane lets potassium ions (K⁺) leak out much more easily than sodium ions (Na⁺) leak in, and (2) the sodium-potassium pump uses ATP to push 3 Na⁺ out for every 2 K⁺ it brings in. More positive charge is therefore outside than inside.', 'the resting potential a neuron at rest is like a charged battery: the inside of the axon is negative (about –70 mv) compared with the outside. this is called polarised. it happens because (1) the membrane lets potassium ions (k⁺) leak out much more easily than sodium ions (na⁺) leak in, and (2) the sodium-potassium pump uses atp to push 3 na⁺ out for every 2 k⁺ it brings in. more positive charge is therefore outside than inside. how a nerve impulse travels and crosses a synapse ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-03', 3, 'The action potential (the impulse)', 'When a stimulus is strong enough to reach the threshold (about –55 mV), the following happens in order: 1. Depolarisation: voltage-gated sodium channels open and Na⁺ rushes in. The inside quickly becomes positive (about +40 mV). 2. Repolarisation: sodium channels close and potassium channels open, so K⁺ rushes out and the inside becomes negative again. 3. Hyperpolarisation: potassium channels stay open slightly too long, so the inside becomes a little more negative than the resting level (about –80 mV) for a moment. The pump then restores the resting state. 4. Refractory period: for a short time the neuron cannot fire again. This makes the impulse move in one direction only. All-or-none law: a stimulus below the threshold produces no impulse; at or above the threshold, a full-size impulse always occurs. A stronger stimulus gives more frequent impulses, not bigger ones.', 'the action potential (the impulse) when a stimulus is strong enough to reach the threshold (about –55 mv), the following happens in order: 1. depolarisation: voltage-gated sodium channels open and na⁺ rushes in. the inside quickly becomes positive (about +40 mv). 2. repolarisation: sodium channels close and potassium channels open, so k⁺ rushes out and the inside becomes negative again. 3. hyperpolarisation: potassium channels stay open slightly too long, so the inside becomes a little more negative than the resting level (about –80 mv) for a moment. the pump then restores the resting state. 4. refractory period: for a short time the neuron cannot fire again. this makes the impulse move in one direction only. all-or-none law: a stimulus below the threshold produces no impulse; at or above the threshold, a full-size impulse always occurs. a stronger stimulus gives more frequent impulses, not bigger ones. how a nerve impulse travels and crosses a synapse ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-03', 4, 'Saltatory conduction', 'In a myelinated axon the ions cannot cross the fatty sheath, so the action potential occurs only at the nodes of Ranvier and the impulse seems to ''jump'' from node to node. This saltatory conduction raises the speed from about 2 m/s in unmyelinated fibres to as much as 120 m/s, and it saves energy.', 'saltatory conduction in a myelinated axon the ions cannot cross the fatty sheath, so the action potential occurs only at the nodes of ranvier and the impulse seems to ''jump'' from node to node. this saltatory conduction raises the speed from about 2 m/s in unmyelinated fibres to as much as 120 m/s, and it saves energy. how a nerve impulse travels and crosses a synapse ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-03', 5, 'The synapse', 'A synapse is the junction between two neurons (the gap is about 20 nm wide, a thousand times thinner than a hair). The impulse cannot jump the gap electrically, so a chemical does it.', 'the synapse a synapse is the junction between two neurons (the gap is about 20 nm wide, a thousand times thinner than a hair). the impulse cannot jump the gap electrically, so a chemical does it. how a nerve impulse travels and crosses a synapse ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-03', 6, 'The steps at a synapse', '1. The impulse reaches the pre-synaptic knob. 2. Calcium ions (Ca²⁺) enter through voltage-gated channels. 3. The calcium makes vesicles join the membrane and release the neurotransmitter into the cleft (exocytosis). 4. The neurotransmitter diffuses across and binds to receptors on the post-synaptic membrane. 5. Ion channels open and a new action potential starts in the next neuron. 6. An enzyme (for example acetylcholinesterase) breaks down the neurotransmitter so that it does not fire again and again. Common neurotransmitters: acetylcholine (muscle contraction and many nerves), dopamine (reward and movement), serotonin (mood and sleep). A synapse allows messages to travel in one direction only, and lets one neuron combine signals from many others. Some drugs and poisons act here: curare blocks acetylcholine receptors, and organophosphate pesticides block acetylcholinesterase, so they are dangerous to farmers.', 'the steps at a synapse 1. the impulse reaches the pre-synaptic knob. 2. calcium ions (ca²⁺) enter through voltage-gated channels. 3. the calcium makes vesicles join the membrane and release the neurotransmitter into the cleft (exocytosis). 4. the neurotransmitter diffuses across and binds to receptors on the post-synaptic membrane. 5. ion channels open and a new action potential starts in the next neuron. 6. an enzyme (for example acetylcholinesterase) breaks down the neurotransmitter so that it does not fire again and again. common neurotransmitters: acetylcholine (muscle contraction and many nerves), dopamine (reward and movement), serotonin (mood and sleep). a synapse allows messages to travel in one direction only, and lets one neuron combine signals from many others. some drugs and poisons act here: curare blocks acetylcholine receptors, and organophosphate pesticides block acetylcholinesterase, so they are dangerous to farmers. how a nerve impulse travels and crosses a synapse ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-04', 'The Central Nervous System: Brain and Spinal Cord') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-04', 0, 'The Central Nervous System: Brain and Spinal Cord: summary', 'The protection of the CNS, the parts of the brain and their jobs, and the structure of the spinal cord. Key words: Meninges, Cerebrum, Cerebellum, Medulla oblongata, Hypothalamus, Grey matter, White matter.', 'the central nervous system: brain and spinal cord: summary the protection of the cns, the parts of the brain and their jobs, and the structure of the spinal cord. key words: meninges, cerebrum, cerebellum, medulla oblongata, hypothalamus, grey matter, white matter. the central nervous system: brain and spinal cord ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-04', 1, 'Protection', 'The brain is protected by the skull and the spinal cord by the vertebral column (backbone). Both are wrapped in three membranes called the meninges (outer dura mater, middle arachnoid, inner pia mater) with a cushioning cerebrospinal fluid. Infection of the meninges is called meningitis, a danger well known in northern Nigeria.', 'protection the brain is protected by the skull and the spinal cord by the vertebral column (backbone). both are wrapped in three membranes called the meninges (outer dura mater, middle arachnoid, inner pia mater) with a cushioning cerebrospinal fluid. infection of the meninges is called meningitis, a danger well known in northern nigeria. the central nervous system: brain and spinal cord ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-04', 2, 'The brain', 'Forebrain: The cerebrum has a left and right hemisphere. Its outer layer, the cerebral cortex, is grey matter (cell bodies) and the inner part is white matter (axons). It is folded to give a large surface area for more neurons. It controls thinking, memory, learning, speech, vision, hearing and voluntary movement. The thalamus relays sensory information to the cortex. The hypothalamus is the control centre for homeostasis: temperature, water balance, hunger, and it controls the pituitary gland. Midbrain: includes the optic lobes that control visual reflexes such as the size of the pupil. Hindbrain: the cerebellum coordinates voluntary movement, posture and balance; if it is damaged the person has jerky, unsteady movements and loses balance (ataxia). The medulla oblongata controls vital involuntary actions: heart beat, breathing rate, swallowing, coughing, vomiting and peristalsis.', 'the brain forebrain: the cerebrum has a left and right hemisphere. its outer layer, the cerebral cortex, is grey matter (cell bodies) and the inner part is white matter (axons). it is folded to give a large surface area for more neurons. it controls thinking, memory, learning, speech, vision, hearing and voluntary movement. the thalamus relays sensory information to the cortex. the hypothalamus is the control centre for homeostasis: temperature, water balance, hunger, and it controls the pituitary gland. midbrain: includes the optic lobes that control visual reflexes such as the size of the pupil. hindbrain: the cerebellum coordinates voluntary movement, posture and balance; if it is damaged the person has jerky, unsteady movements and loses balance (ataxia). the medulla oblongata controls vital involuntary actions: heart beat, breathing rate, swallowing, coughing, vomiting and peristalsis. the central nervous system: brain and spinal cord ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-04', 3, 'The spinal cord', 'A cylinder of nervous tissue running inside the backbone. In cross-section its arrangement is the opposite of the brain''s: the grey matter is inside in an H or butterfly shape, and the white matter (axons) is on the outside. A small hole in the centre, the central canal, contains fluid. Each spinal nerve joins the cord by two roots: the dorsal (back) root carries sensory impulses into the cord and has a swelling, the dorsal root ganglion, with the sensory cell bodies; the ventral (front) root carries motor impulses out to the muscles. The spinal cord carries messages up to the brain and down from it, and controls reflex actions.', 'the spinal cord a cylinder of nervous tissue running inside the backbone. in cross-section its arrangement is the opposite of the brain''s: the grey matter is inside in an h or butterfly shape, and the white matter (axons) is on the outside. a small hole in the centre, the central canal, contains fluid. each spinal nerve joins the cord by two roots: the dorsal (back) root carries sensory impulses into the cord and has a swelling, the dorsal root ganglion, with the sensory cell bodies; the ventral (front) root carries motor impulses out to the muscles. the spinal cord carries messages up to the brain and down from it, and controls reflex actions. the central nervous system: brain and spinal cord ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-04', 4, 'Putting it together', 'Study the table. Cerebrum; Thinking, memory, speech, senses, voluntary movement. Thalamus; Relay of sensory messages. Hypothalamus; Homeostasis; controls pituitary gland. Cerebellum; Balance, posture, smooth movement. Medulla oblongata; Heart rate, breathing, swallowing. Spinal cord; Link between brain and body; reflex centre.', 'putting it together study the table. cerebrum; thinking, memory, speech, senses, voluntary movement. thalamus; relay of sensory messages. hypothalamus; homeostasis; controls pituitary gland. cerebellum; balance, posture, smooth movement. medulla oblongata; heart rate, breathing, swallowing. spinal cord; link between brain and body; reflex centre. the central nervous system: brain and spinal cord ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-05', 'The Peripheral and Autonomic Nervous System and Reflex Actions') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-05', 0, 'The Peripheral and Autonomic Nervous System and Reflex Actions: summary', 'Cranial and spinal nerves, the somatic and autonomic systems, sympathetic and parasympathetic control, and the reflex arc. Key words: Autonomic nervous system, Sympathetic, Parasympathetic, Reflex arc, Conditioned reflex.', 'the peripheral and autonomic nervous system and reflex actions: summary cranial and spinal nerves, the somatic and autonomic systems, sympathetic and parasympathetic control, and the reflex arc. key words: autonomic nervous system, sympathetic, parasympathetic, reflex arc, conditioned reflex. the peripheral and autonomic nervous system and reflex actions ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-05', 1, 'The peripheral nervous system (PNS)', 'The PNS joins the CNS to the rest of the body. It has 12 pairs of cranial nerves (from the brain, for example the optic nerve and the vagus nerve) and 31 pairs of spinal nerves (from the spinal cord). The somatic system controls voluntary actions of the skeletal muscles (writing, walking). The autonomic nervous system (ANS) controls involuntary actions of internal organs (heart, gut, glands, bladder) without conscious thought.', 'the peripheral nervous system (pns) the pns joins the cns to the rest of the body. it has 12 pairs of cranial nerves (from the brain, for example the optic nerve and the vagus nerve) and 31 pairs of spinal nerves (from the spinal cord). the somatic system controls voluntary actions of the skeletal muscles (writing, walking). the autonomic nervous system (ans) controls involuntary actions of internal organs (heart, gut, glands, bladder) without conscious thought. the peripheral and autonomic nervous system and reflex actions ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-05', 2, 'Sympathetic and parasympathetic systems', 'The ANS has two opposite parts. The sympathetic system prepares the body for ''fight or flight'' (a man sees a snake and runs). The parasympathetic system is for ''rest and digest''. Neurotransmitter; Noradrenaline; Acetylcholine. Heart rate; Increases; Decreases. Pupil; Dilates; Constricts. Digestion; Slowed (peristalsis decreases); Stimulated. Bronchi (air tubes); Widen (more air); Narrow. Liver; Glycogen to glucose (more energy); Promotes storage of glucose. Bladder; Relaxes (holds urine); Contracts (releases urine).', 'sympathetic and parasympathetic systems the ans has two opposite parts. the sympathetic system prepares the body for ''fight or flight'' (a man sees a snake and runs). the parasympathetic system is for ''rest and digest''. neurotransmitter; noradrenaline; acetylcholine. heart rate; increases; decreases. pupil; dilates; constricts. digestion; slowed (peristalsis decreases); stimulated. bronchi (air tubes); widen (more air); narrow. liver; glycogen to glucose (more energy); promotes storage of glucose. bladder; relaxes (holds urine); contracts (releases urine). the peripheral and autonomic nervous system and reflex actions ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-05', 3, 'The snake example', 'When a man sees a snake, the sympathetic system works together with adrenaline from the adrenal glands: the heart beats faster, the breathing is quicker and deeper, the pupils widen, the blood vessels to the gut narrow and those to the muscles widen, the liver releases glucose, and the body sweats. All these supply muscles with energy and oxygen to run or fight.', 'the snake example when a man sees a snake, the sympathetic system works together with adrenaline from the adrenal glands: the heart beats faster, the breathing is quicker and deeper, the pupils widen, the blood vessels to the gut narrow and those to the muscles widen, the liver releases glucose, and the body sweats. all these supply muscles with energy and oxygen to run or fight. the peripheral and autonomic nervous system and reflex actions ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-05', 4, 'Reflex actions', 'A reflex is a fast, automatic response to a stimulus, which does not need thinking. The path is the reflex arc: receptor (detects the stimulus, for example heat) → sensory neuron (through the dorsal root) → relay neuron in the grey matter of the spinal cord → motor neuron (leaves through the ventral root) → effector (a muscle that contracts, pulling the hand away). Because the arc goes through the spinal cord only, the response is very fast and the brain is bypassed; the brain is told afterwards, so we feel the pain a little later.', 'reflex actions a reflex is a fast, automatic response to a stimulus, which does not need thinking. the path is the reflex arc: receptor (detects the stimulus, for example heat) → sensory neuron (through the dorsal root) → relay neuron in the grey matter of the spinal cord → motor neuron (leaves through the ventral root) → effector (a muscle that contracts, pulling the hand away). because the arc goes through the spinal cord only, the response is very fast and the brain is bypassed; the brain is told afterwards, so we feel the pain a little later. the peripheral and autonomic nervous system and reflex actions ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-05', 5, 'Simple and conditioned reflexes', 'Simple (unconditioned) reflexes are inborn: knee-jerk, blinking, pupil reflex, sneezing, withdrawing the hand. A conditioned reflex is learned by association: in Pavlov''s experiment dogs learned to salivate at the sound of a bell that was rung with food. A conditioned reflex needs the cerebrum because the brain must learn the link; a simple reflex does not. (Skills such as cycling are learned habits, not true reflexes, but they also use the cerebrum and cerebellum.)', 'simple and conditioned reflexes simple (unconditioned) reflexes are inborn: knee-jerk, blinking, pupil reflex, sneezing, withdrawing the hand. a conditioned reflex is learned by association: in pavlov''s experiment dogs learned to salivate at the sound of a bell that was rung with food. a conditioned reflex needs the cerebrum because the brain must learn the link; a simple reflex does not. (skills such as cycling are learned habits, not true reflexes, but they also use the cerebrum and cerebellum.) the peripheral and autonomic nervous system and reflex actions ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-05', 6, 'Reflex and voluntary action compared', 'Reflex: fast, automatic, no thinking, passes through the spinal cord. Voluntary: slower, needs thought, involves the cerebrum.', 'reflex and voluntary action compared reflex: fast, automatic, no thinking, passes through the spinal cord. voluntary: slower, needs thought, involves the cerebrum. the peripheral and autonomic nervous system and reflex actions ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-06', 'The Eye: Structure and How We See') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-06', 0, 'The Eye: Structure and How We See: summary', 'Sense organs as transducers, the layers and parts of the eye, rods and cones, the blind spot and how an image is formed. Key words: Receptor, Cornea, Retina, Rods, Cones, Fovea, Blind spot.', 'the eye: structure and how we see: summary sense organs as transducers, the layers and parts of the eye, rods and cones, the blind spot and how an image is formed. key words: receptor, cornea, retina, rods, cones, fovea, blind spot. the eye: structure and how we see ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-06', 1, 'Sense organs as transducers', 'Sense organs are our windows to the world. They contain receptors that change (transduce) light, sound, pressure and chemicals into nerve impulses for the brain. A stimulus is a detectable change; a receptor detects it; an effector (a muscle or gland) responds.', 'sense organs as transducers sense organs are our windows to the world. they contain receptors that change (transduce) light, sound, pressure and chemicals into nerve impulses for the brain. a stimulus is a detectable change; a receptor detects it; an effector (a muscle or gland) responds. the eye: structure and how we see ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-06', 2, 'The structure of the eye', 'The eye is a fluid-filled ball protected by the bony socket (orbit), eyelids and tears. Outer layer: the sclera is the tough white of the eye, which keeps the shape and protects. The cornea is the clear front window, with no blood vessels so it stays clear; it gets oxygen from the air and does about two thirds of the bending of light. The conjunctiva is a thin transparent membrane over the sclera and inside the eyelids; infection causes conjunctivitis (in Nigeria, the red-eye type is popularly called ''Apollo''). Middle layer: the choroid has many blood vessels and dark pigment; it feeds the retina and absorbs stray light so that vision is not blurred. The ciliary body has ciliary muscles that change the shape of the lens, and ciliary processes that make the aqueous humour. Suspensory ligaments hold the lens. The iris is the coloured muscular ring whose hole, the pupil, controls how much light enters. Inner layer: the retina contains the light-sensitive cells. Rods (about 120 million) work in dim light, contain rhodopsin (visual purple) and give black and white vision and detect movement; they are at the edges. Cones (about 6 million) work in bright light, give colour vision and sharp detail, and are mostly at the centre. The fovea (yellow spot) has only cones and is the point of sharpest vision. The blind spot (optic disc) is where the optic nerve leaves; it has no receptors.', 'the structure of the eye the eye is a fluid-filled ball protected by the bony socket (orbit), eyelids and tears. outer layer: the sclera is the tough white of the eye, which keeps the shape and protects. the cornea is the clear front window, with no blood vessels so it stays clear; it gets oxygen from the air and does about two thirds of the bending of light. the conjunctiva is a thin transparent membrane over the sclera and inside the eyelids; infection causes conjunctivitis (in nigeria, the red-eye type is popularly called ''apollo''). middle layer: the choroid has many blood vessels and dark pigment; it feeds the retina and absorbs stray light so that vision is not blurred. the ciliary body has ciliary muscles that change the shape of the lens, and ciliary processes that make the aqueous humour. suspensory ligaments hold the lens. the iris is the coloured muscular ring whose hole, the pupil, controls how much light enters. inner layer: the retina contains the light-sensitive cells. rods (about 120 million) work in dim light, contain rhodopsin (visual purple) and give black and white vision and detect movement; they are at the edges. cones (about 6 million) work in bright light, give colour vision and sharp detail, and are mostly at the centre. the fovea (yellow spot) has only cones and is the point of sharpest vision. the blind spot (optic disc) is where the optic nerve leaves; it has no receptors. the eye: structure and how we see ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-06', 3, 'The transparent parts (refractive media)', 'Aqueous humour: a watery fluid between the cornea and lens that keeps the eye pressure steady and feeds the cornea and lens. Lens: a clear, elastic, biconvex structure that changes shape to focus light. Vitreous humour: a clear jelly filling the large chamber behind the lens, which holds the retina against the choroid and keeps the eyeball round.', 'the transparent parts (refractive media) aqueous humour: a watery fluid between the cornea and lens that keeps the eye pressure steady and feeds the cornea and lens. lens: a clear, elastic, biconvex structure that changes shape to focus light. vitreous humour: a clear jelly filling the large chamber behind the lens, which holds the retina against the choroid and keeps the eyeball round. the eye: structure and how we see ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-06', 4, 'How an image is formed', 'Light passes through the cornea, aqueous humour, pupil, lens and vitreous humour to the retina. These parts bend (refract) the rays to focus them on the retina. The image on the retina is real, upside-down and smaller than the object. The rods and cones make impulses that travel along the optic nerve to the brain (the visual area of the cerebrum), which turns the picture the right way up.', 'how an image is formed light passes through the cornea, aqueous humour, pupil, lens and vitreous humour to the retina. these parts bend (refract) the rays to focus them on the retina. the image on the retina is real, upside-down and smaller than the object. the rods and cones make impulses that travel along the optic nerve to the brain (the visual area of the cerebrum), which turns the picture the right way up. the eye: structure and how we see ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-06', 5, 'Dark adaptation', 'When you walk from bright sunlight into a dark cinema hall, you cannot see for a minute or two, because the rods in the retina have been bleached by strong light. In the dark, rhodopsin is rebuilt slowly, and the rods become sensitive again, so you gradually see. The pupil also widens at once.', 'dark adaptation when you walk from bright sunlight into a dark cinema hall, you cannot see for a minute or two, because the rods in the retina have been bleached by strong light. in the dark, rhodopsin is rebuilt slowly, and the rods become sensitive again, so you gradually see. the pupil also widens at once. the eye: structure and how we see ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-07', 'Accommodation, the Pupil Reflex and Defects of the Eye') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-07', 0, 'Accommodation, the Pupil Reflex and Defects of the Eye: summary', 'How the lens focuses on near and far objects, how the pupil changes size, and the causes and correction of short sight, long sight, astigmatism and presbyopia. Key words: Accommodation, Ciliary muscle, Pupil reflex, Myopia, Hypermetropia, Concave lens, Convex lens.', 'accommodation, the pupil reflex and defects of the eye: summary how the lens focuses on near and far objects, how the pupil changes size, and the causes and correction of short sight, long sight, astigmatism and presbyopia. key words: accommodation, ciliary muscle, pupil reflex, myopia, hypermetropia, concave lens, convex lens. accommodation, the pupil reflex and defects of the eye ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-07', 1, 'Accommodation: focusing near and far', 'Accommodation is the automatic adjustment of the lens to see things at different distances. The ciliary muscles and suspensory ligaments work in opposite ways. Near (reading); Contract; Slacken; Thick, rounder; Short (stronger lens). Far (a distant mountain); Relax; Tighten (pull); Thin, flatter; Long (weaker lens).', 'accommodation: focusing near and far accommodation is the automatic adjustment of the lens to see things at different distances. the ciliary muscles and suspensory ligaments work in opposite ways. near (reading); contract; slacken; thick, rounder; short (stronger lens). far (a distant mountain); relax; tighten (pull); thin, flatter; long (weaker lens). accommodation, the pupil reflex and defects of the eye ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-07', 2, 'The pupil reflex', 'Bright light: the circular muscles of the iris contract and the radial muscles relax, so the pupil gets smaller. This stops dazzling and protects the retina. Dim light: the radial muscles contract and the circular muscles relax, so the pupil widens to let in more light. This is a reflex controlled by the midbrain.', 'the pupil reflex bright light: the circular muscles of the iris contract and the radial muscles relax, so the pupil gets smaller. this stops dazzling and protects the retina. dim light: the radial muscles contract and the circular muscles relax, so the pupil widens to let in more light. this is a reflex controlled by the midbrain. accommodation, the pupil reflex and defects of the eye ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-07', 3, 'Defects of the eye', 'Myopia (short-sightedness): near objects are clear but distant ones are blurred. The eyeball is too long, or the lens is too strong. The image forms in front of the retina. It is corrected with a concave (diverging) lens. Hypermetropia (long-sightedness): distant objects are clear but near ones are blurred. The eyeball is too short, or the lens is too weak. The image forms behind the retina. It is corrected with a convex (converging) lens. Astigmatism: the cornea or lens is not evenly curved, so the image is distorted; corrected with cylindrical lenses. Presbyopia: in old age the lens loses its elasticity and cannot focus on near things; corrected with reading glasses or bifocal lenses.', 'defects of the eye myopia (short-sightedness): near objects are clear but distant ones are blurred. the eyeball is too long, or the lens is too strong. the image forms in front of the retina. it is corrected with a concave (diverging) lens. hypermetropia (long-sightedness): distant objects are clear but near ones are blurred. the eyeball is too short, or the lens is too weak. the image forms behind the retina. it is corrected with a convex (converging) lens. astigmatism: the cornea or lens is not evenly curved, so the image is distorted; corrected with cylindrical lenses. presbyopia: in old age the lens loses its elasticity and cannot focus on near things; corrected with reading glasses or bifocal lenses. accommodation, the pupil reflex and defects of the eye ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-07', 4, 'Other eye conditions', 'Cataract: the lens becomes cloudy, causing blurred vision; it is treated by replacing the lens in surgery. Glaucoma: the pressure in the eye rises and damages the optic nerve, causing loss of side vision; it is treated with drops or surgery. Night blindness: caused by lack of vitamin A, so eat carrots, palm oil (red oil), liver and green leaves. Cheap checks and early treatment can prevent blindness.', 'other eye conditions cataract: the lens becomes cloudy, causing blurred vision; it is treated by replacing the lens in surgery. glaucoma: the pressure in the eye rises and damages the optic nerve, causing loss of side vision; it is treated with drops or surgery. night blindness: caused by lack of vitamin a, so eat carrots, palm oil (red oil), liver and green leaves. cheap checks and early treatment can prevent blindness. accommodation, the pupil reflex and defects of the eye ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-07', 5, 'Two eyes or one', 'Predators such as lions and owls have both eyes at the front, giving binocular vision and a good judgement of distance. Prey animals such as antelopes and rabbits have eyes at the sides for a very wide field of view to spot danger.', 'two eyes or one predators such as lions and owls have both eyes at the front, giving binocular vision and a good judgement of distance. prey animals such as antelopes and rabbits have eyes at the sides for a very wide field of view to spot danger. accommodation, the pupil reflex and defects of the eye ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-08', 'The Ear: Hearing and Balance') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-08', 0, 'The Ear: Hearing and Balance: summary', 'The parts of the outer, middle and inner ear, how sound becomes nerve impulses, and how the ear keeps balance. Key words: Eardrum, Ossicles, Cochlea, Organ of Corti, Semicircular canals, Otoliths.', 'the ear: hearing and balance: summary the parts of the outer, middle and inner ear, how sound becomes nerve impulses, and how the ear keeps balance. key words: eardrum, ossicles, cochlea, organ of corti, semicircular canals, otoliths. the ear: hearing and balance ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-08', 1, 'The parts of the ear', 'The ear has two jobs: hearing and balance.', 'the parts of the ear the ear has two jobs: hearing and balance. the ear: hearing and balance ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-08', 2, 'Outer ear', 'Pinna (auricle): a flap of cartilage that collects sound. Auditory canal: a tube with hairs and wax glands that trap dust and insects. Eardrum (tympanic membrane): a thin membrane that vibrates when sound arrives and separates the outer from the middle ear.', 'outer ear pinna (auricle): a flap of cartilage that collects sound. auditory canal: a tube with hairs and wax glands that trap dust and insects. eardrum (tympanic membrane): a thin membrane that vibrates when sound arrives and separates the outer from the middle ear. the ear: hearing and balance ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-08', 3, 'Middle ear', 'An air-filled space in the skull bone. The three smallest bones in the body, the ossicles, are the malleus (hammer), incus (anvil) and stapes (stirrup), in that order from the eardrum. They pass the vibrations to the oval window and make them about 20 times stronger. The Eustachian tube joins the middle ear to the throat and opens when you swallow or yawn, so that the air pressure on both sides of the eardrum is equal. If it is blocked (for example by a cold), the ears hurt in an aeroplane.', 'middle ear an air-filled space in the skull bone. the three smallest bones in the body, the ossicles, are the malleus (hammer), incus (anvil) and stapes (stirrup), in that order from the eardrum. they pass the vibrations to the oval window and make them about 20 times stronger. the eustachian tube joins the middle ear to the throat and opens when you swallow or yawn, so that the air pressure on both sides of the eardrum is equal. if it is blocked (for example by a cold), the ears hurt in an aeroplane. the ear: hearing and balance ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-08', 4, 'Inner ear', 'A fluid-filled maze (labyrinth) in the bone. The cochlea is a coiled tube with the Organ of Corti (the receptor for hearing). The vestibular apparatus is for balance: three semicircular canals at right angles to each other, and the utricle and saccule, chambers that hold otoliths.', 'inner ear a fluid-filled maze (labyrinth) in the bone. the cochlea is a coiled tube with the organ of corti (the receptor for hearing). the vestibular apparatus is for balance: three semicircular canals at right angles to each other, and the utricle and saccule, chambers that hold otoliths. the ear: hearing and balance ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-08', 5, 'How we hear', '1. The pinna collects sound waves into the canal. 2. The waves hit the eardrum and make it vibrate. 3. The ossicles vibrate and amplify the force; the stapes pushes like a piston on the oval window. 4. This makes pressure waves in the fluid of the cochlea. 5. The waves move the basilar membrane, and the hair cells of the Organ of Corti are bent against the tectorial membrane. 6. The bending makes nerve impulses that go along the auditory nerve to the brain. 7. The pressure is released through the round window.', 'how we hear 1. the pinna collects sound waves into the canal. 2. the waves hit the eardrum and make it vibrate. 3. the ossicles vibrate and amplify the force; the stapes pushes like a piston on the oval window. 4. this makes pressure waves in the fluid of the cochlea. 5. the waves move the basilar membrane, and the hair cells of the organ of corti are bent against the tectorial membrane. 6. the bending makes nerve impulses that go along the auditory nerve to the brain. 7. the pressure is released through the round window. the ear: hearing and balance ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-08', 6, 'How we keep balance', 'Dynamic balance (movement of the head): when the head turns, the fluid in the semicircular canals lags behind and bends the hair cells of the cupula, telling the brain the direction and speed of rotation. Static balance (position): in the utricle and saccule, tiny crystals of calcium carbonate (otoliths) are pulled by gravity when the head tilts and bend the hair cells. Dizziness after spinning happens because the fluid keeps moving after you stop.', 'how we keep balance dynamic balance (movement of the head): when the head turns, the fluid in the semicircular canals lags behind and bends the hair cells of the cupula, telling the brain the direction and speed of rotation. static balance (position): in the utricle and saccule, tiny crystals of calcium carbonate (otoliths) are pulled by gravity when the head tilts and bend the hair cells. dizziness after spinning happens because the fluid keeps moving after you stop. the ear: hearing and balance ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-09', 'Nose, Tongue and Skin: Smell, Taste and Touch') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-09', 0, 'Nose, Tongue and Skin: Smell, Taste and Touch: summary', 'Chemoreceptors for smell and taste, the real facts about the tongue, the receptors in the skin and why a cold spoils taste. Key words: Olfaction, Taste buds, Umami, Mechanoreceptor, Thermoreceptor, Nociceptor.', 'nose, tongue and skin: smell, taste and touch: summary chemoreceptors for smell and taste, the real facts about the tongue, the receptors in the skin and why a cold spoils taste. key words: olfaction, taste buds, umami, mechanoreceptor, thermoreceptor, nociceptor. nose, tongue and skin: smell, taste and touch ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-09', 1, 'The nose (smell)', 'The olfactory epithelium in the roof of the nasal cavity contains chemoreceptors that detect gas molecules dissolved in the mucus. Smell is much more sensitive than taste, and it is closely linked with the part of the brain that stores memory and emotion, which is why a smell can bring back a memory.', 'the nose (smell) the olfactory epithelium in the roof of the nasal cavity contains chemoreceptors that detect gas molecules dissolved in the mucus. smell is much more sensitive than taste, and it is closely linked with the part of the brain that stores memory and emotion, which is why a smell can bring back a memory. nose, tongue and skin: smell, taste and touch ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-09', 2, 'The tongue (taste)', 'Taste buds are in small bumps called papillae. They detect chemicals dissolved in saliva. The five basic tastes are sweet, salty, sour, bitter and umami (savoury, as in meat, crayfish and seasoning). A correction: the old ''tongue map'' (sweet at the tip, sour at the sides, bitter at the back) is a myth. Every taste can be sensed on all parts of the tongue that have taste buds, although some places are a little more sensitive. What we call flavour is taste plus smell plus texture and temperature.', 'the tongue (taste) taste buds are in small bumps called papillae. they detect chemicals dissolved in saliva. the five basic tastes are sweet, salty, sour, bitter and umami (savoury, as in meat, crayfish and seasoning). a correction: the old ''tongue map'' (sweet at the tip, sour at the sides, bitter at the back) is a myth. every taste can be sensed on all parts of the tongue that have taste buds, although some places are a little more sensitive. what we call flavour is taste plus smell plus texture and temperature. nose, tongue and skin: smell, taste and touch ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-09', 3, 'Why food tastes bland with a cold', 'With a blocked nose, the smell molecules cannot reach the olfactory cells, so the flavour is lost even though taste buds still work. Pinch your nose while eating a sweet and notice how the flavour changes.', 'why food tastes bland with a cold with a blocked nose, the smell molecules cannot reach the olfactory cells, so the flavour is lost even though taste buds still work. pinch your nose while eating a sweet and notice how the flavour changes. nose, tongue and skin: smell, taste and touch ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-09', 4, 'The skin (touch and feeling)', 'The skin is the largest organ and has many types of receptors: mechanoreceptors, such as Meissner''s corpuscles for light touch and Pacinian corpuscles for deep pressure and vibration; thermoreceptors, for warmth and cold; and nociceptors (free nerve endings) for pain. Pain is useful because it warns us of damage. Some body parts, such as the fingertips and lips, have many more receptors, so they are more sensitive than the back.', 'the skin (touch and feeling) the skin is the largest organ and has many types of receptors: mechanoreceptors, such as meissner''s corpuscles for light touch and pacinian corpuscles for deep pressure and vibration; thermoreceptors, for warmth and cold; and nociceptors (free nerve endings) for pain. pain is useful because it warns us of damage. some body parts, such as the fingertips and lips, have many more receptors, so they are more sensitive than the back. nose, tongue and skin: smell, taste and touch ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-09', 5, 'Summary table', 'Compare the senses. Eye; Photoreceptors (rods and cones); Light. Ear; Mechanoreceptors (hair cells); Sound and movement. Nose; Chemoreceptors; Gases in air. Tongue; Chemoreceptors; Chemicals in solution. Skin; Mechano-, thermo- and nociceptors; Touch, temperature, pain.', 'summary table compare the senses. eye; photoreceptors (rods and cones); light. ear; mechanoreceptors (hair cells); sound and movement. nose; chemoreceptors; gases in air. tongue; chemoreceptors; chemicals in solution. skin; mechano-, thermo- and nociceptors; touch, temperature, pain. nose, tongue and skin: smell, taste and touch ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-10', 'Ecology of Population: Size, Density, Growth and Limiting Factors') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-10', 0, 'Ecology of Population: Size, Density, Growth and Limiting Factors: summary', 'The meaning of a population, its size, density, frequency and distribution, the four factors that change its size, growth curves and the factors that limit growth. Key words: Population, Population density, Natality, Mortality, Immigration, Emigration, Carrying capacity.', 'ecology of population: size, density, growth and limiting factors: summary the meaning of a population, its size, density, frequency and distribution, the four factors that change its size, growth curves and the factors that limit growth. key words: population, population density, natality, mortality, immigration, emigration, carrying capacity. ecology of population: size, density, growth and limiting factors ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-10', 1, 'What is a population?', 'A population is a group of organisms of the same species living together in a particular place at a particular time. The key phrase is ''same species'': all the tilapia in a school pond are a population. If we count the tilapia, frogs and water weeds together, we are counting a community, not a population.', 'what is a population? a population is a group of organisms of the same species living together in a particular place at a particular time. the key phrase is ''same species'': all the tilapia in a school pond are a population. if we count the tilapia, frogs and water weeds together, we are counting a community, not a population. ecology of population: size, density, growth and limiting factors ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-10', 2, 'Characteristics of a population', 'Population size is the total number of individuals of the species in the habitat (for example, 500 students in a school). Population density is the number of individuals per unit area (on land) or per unit volume (in water). Population density = number of individuals ÷ area. It tells how crowded the place is. High density leads to overcrowding and competition; very low density makes it hard to find mates. Worked example: 200 Tridax plants in a school garden of 50 m² give a density of 200 ÷ 50 = 4 plants per m². Population frequency is how often a species turns up in different samples of the habitat. If you throw a quadrat 10 times and find Tridax in 6 of them, the frequency is 6 ÷ 10 × 100 = 60%. Distribution (dispersion) is how the individuals are arranged. Clumped: in groups, such as a school of fish or a herd of cattle (the most common pattern in nature). Uniform: evenly spaced, such as maize or oil palms in a farm. Random: scattered without a pattern, such as plants grown from wind-blown seeds.', 'characteristics of a population population size is the total number of individuals of the species in the habitat (for example, 500 students in a school). population density is the number of individuals per unit area (on land) or per unit volume (in water). population density = number of individuals ÷ area. it tells how crowded the place is. high density leads to overcrowding and competition; very low density makes it hard to find mates. worked example: 200 tridax plants in a school garden of 50 m² give a density of 200 ÷ 50 = 4 plants per m². population frequency is how often a species turns up in different samples of the habitat. if you throw a quadrat 10 times and find tridax in 6 of them, the frequency is 6 ÷ 10 × 100 = 60%. distribution (dispersion) is how the individuals are arranged. clumped: in groups, such as a school of fish or a herd of cattle (the most common pattern in nature). uniform: evenly spaced, such as maize or oil palms in a farm. random: scattered without a pattern, such as plants grown from wind-blown seeds. ecology of population: size, density, growth and limiting factors ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-10', 3, 'Changes in population size', 'Four things change the size of a population: natality (birth rate: increases the population); mortality (death rate: decreases it); immigration (individuals moving into the area: increases it); and emigration (individuals moving out of the area: decreases it). Change in population = (births + immigrants) – (deaths + emigrants). Immigration is movement in; emigration is movement out (remember: Immigration = In).', 'changes in population size four things change the size of a population: natality (birth rate: increases the population); mortality (death rate: decreases it); immigration (individuals moving into the area: increases it); and emigration (individuals moving out of the area: decreases it). change in population = (births + immigrants) – (deaths + emigrants). immigration is movement in; emigration is movement out (remember: immigration = in). ecology of population: size, density, growth and limiting factors ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-10', 4, 'Growth curves', 'Exponential (J-shaped) growth happens when there is plenty of everything and no enemies: the population grows slowly at first, then shoots up very fast. Examples: bacteria in a culture, insects in the early rainy season. It cannot last, because food runs out and the population crashes. Logistic (S-shaped or sigmoid) growth is the usual pattern in nature. Lag phase: growth is slow because there are few parents, which are still settling in and finding mates. Log (exponential) phase: growth is fast because food is plentiful and many young are born. Stationary phase: the population levels off because births equal deaths. The level is the carrying capacity: the largest population that the environment can support without damage.', 'growth curves exponential (j-shaped) growth happens when there is plenty of everything and no enemies: the population grows slowly at first, then shoots up very fast. examples: bacteria in a culture, insects in the early rainy season. it cannot last, because food runs out and the population crashes. logistic (s-shaped or sigmoid) growth is the usual pattern in nature. lag phase: growth is slow because there are few parents, which are still settling in and finding mates. log (exponential) phase: growth is fast because food is plentiful and many young are born. stationary phase: the population levels off because births equal deaths. the level is the carrying capacity: the largest population that the environment can support without damage. ecology of population: size, density, growth and limiting factors ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-10', 5, 'What limits growth? (Environmental resistance)', 'Density-dependent factors have more effect when the population is crowded: shortage of food, competition for space, water and mates, disease (spreads quicker in crowds), predation (predators find prey easily when there are many). Competition is density-dependent because the more individuals there are, the more they compete for the same limited resources. Density-independent factors kill whatever the size of the population: floods, fire, drought, earthquakes, sudden cold or heat, and pesticides.', 'what limits growth? (environmental resistance) density-dependent factors have more effect when the population is crowded: shortage of food, competition for space, water and mates, disease (spreads quicker in crowds), predation (predators find prey easily when there are many). competition is density-dependent because the more individuals there are, the more they compete for the same limited resources. density-independent factors kill whatever the size of the population: floods, fire, drought, earthquakes, sudden cold or heat, and pesticides. ecology of population: size, density, growth and limiting factors ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-11', 'Estimating Population Size: Quadrats and Capture-Mark-Recapture') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-11', 0, 'Estimating Population Size: Quadrats and Capture-Mark-Recapture: summary', 'How to estimate the number of plants and animals by sampling, with the formulas and worked examples. Key words: Quadrat, Sampling, Capture-mark-recapture, Lincoln index, Estimate.', 'estimating population size: quadrats and capture-mark-recapture: summary how to estimate the number of plants and animals by sampling, with the formulas and worked examples. key words: quadrat, sampling, capture-mark-recapture, lincoln index, estimate. estimating population size: quadrats and capture-mark-recapture ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-11', 1, 'Why we sample', 'We cannot count every ant or blade of grass, so we count a small, fair part of the population (a sample) and use it to estimate the whole.', 'why we sample we cannot count every ant or blade of grass, so we count a small, fair part of the population (a sample) and use it to estimate the whole. estimating population size: quadrats and capture-mark-recapture ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-11', 2, 'The quadrat method (for plants and slow animals)', 'A quadrat is a square frame, usually 1 m × 1 m. Steps: 1. Throw the quadrat at random (for example, throw it backwards over your shoulder) so that the choice is fair. 2. Count the plants of the species in the quadrat. 3. Repeat many times (for example 10 or more). 4. Calculate the mean number per quadrat. 5. Multiply by the total area of the field (in the same units as the quadrat) to estimate the total number. Worked example: in 10 throws of a 1 m² quadrat, the Tridax counts are 4, 6, 3, 5, 7, 2, 6, 5, 4, 8. The total is 50, so the mean is 5 per m². The field is 400 m², so the estimate is 5 × 400 = 2 000 plants.', 'the quadrat method (for plants and slow animals) a quadrat is a square frame, usually 1 m × 1 m. steps: 1. throw the quadrat at random (for example, throw it backwards over your shoulder) so that the choice is fair. 2. count the plants of the species in the quadrat. 3. repeat many times (for example 10 or more). 4. calculate the mean number per quadrat. 5. multiply by the total area of the field (in the same units as the quadrat) to estimate the total number. worked example: in 10 throws of a 1 m² quadrat, the tridax counts are 4, 6, 3, 5, 7, 2, 6, 5, 4, 8. the total is 50, so the mean is 5 per m². the field is 400 m², so the estimate is 5 × 400 = 2 000 plants. estimating population size: quadrats and capture-mark-recapture ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-11', 3, 'The capture-mark-recapture method (for moving animals)', 'Used for grasshoppers, rats, fish and birds. Steps: 1. Catch a number of animals (first catch, M). 2. Mark each harmlessly (a dot of non-toxic paint) and release them. 3. Wait for them to mix freely with the others. 4. Catch a second sample (C). 5. Count how many of them are marked (R). Formula: estimated population = (M × C) ÷ R, because the fraction of marked animals in the second catch is taken to be the same as the fraction of marked animals in the whole population (R ÷ C = M ÷ N). Worked example: 40 grasshoppers are caught, marked and released. A second catch has 60 grasshoppers, of which 12 are marked. N = (40 × 60) ÷ 12 = 2 400 ÷ 12 = 200 grasshoppers.', 'the capture-mark-recapture method (for moving animals) used for grasshoppers, rats, fish and birds. steps: 1. catch a number of animals (first catch, m). 2. mark each harmlessly (a dot of non-toxic paint) and release them. 3. wait for them to mix freely with the others. 4. catch a second sample (c). 5. count how many of them are marked (r). formula: estimated population = (m × c) ÷ r, because the fraction of marked animals in the second catch is taken to be the same as the fraction of marked animals in the whole population (r ÷ c = m ÷ n). worked example: 40 grasshoppers are caught, marked and released. a second catch has 60 grasshoppers, of which 12 are marked. n = (40 × 60) ÷ 12 = 2 400 ÷ 12 = 200 grasshoppers. estimating population size: quadrats and capture-mark-recapture ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-11', 4, 'Assumptions and limits', 'The method works only if: the marks do not wear off or make the animals easier for predators to see; the marked animals mix fully with the rest; no big birth, death, immigration or emigration happens between the catches; and all animals have an equal chance of being caught. Advantage: it does not harm the animals and avoids counting all of them. For quadrats: the sample must be random, and large enough, or the estimate may be wrong if the plants are clumped.', 'assumptions and limits the method works only if: the marks do not wear off or make the animals easier for predators to see; the marked animals mix fully with the rest; no big birth, death, immigration or emigration happens between the catches; and all animals have an equal chance of being caught. advantage: it does not harm the animals and avoids counting all of them. for quadrats: the sample must be random, and large enough, or the estimate may be wrong if the plants are clumped. estimating population size: quadrats and capture-mark-recapture ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-12', 'The Ecosystem, Food Chains, Food Webs and Energy Flow') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-12', 0, 'The Ecosystem, Food Chains, Food Webs and Energy Flow: summary', 'The abiotic and biotic components of an ecosystem, producers, consumers and decomposers, food chains, webs, trophic levels and the 10% rule. Key words: Ecosystem, Producer, Consumer, Decomposer, Food chain, Food web, Trophic level.', 'the ecosystem, food chains, food webs and energy flow: summary the abiotic and biotic components of an ecosystem, producers, consumers and decomposers, food chains, webs, trophic levels and the 10% rule. key words: ecosystem, producer, consumer, decomposer, food chain, food web, trophic level. the ecosystem, food chains, food webs and energy flow ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-12', 1, 'What is an ecosystem?', 'An ecosystem is a self-supporting unit where living things (plants, animals and microbes) interact with each other and with the non-living environment. Examples: a pond, a forest, a farm, a savanna. The biosphere is the part of the Earth (land, water and air) where life exists.', 'what is an ecosystem? an ecosystem is a self-supporting unit where living things (plants, animals and microbes) interact with each other and with the non-living environment. examples: a pond, a forest, a farm, a savanna. the biosphere is the part of the earth (land, water and air) where life exists. the ecosystem, food chains, food webs and energy flow ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-12', 2, 'Abiotic components (non-living)', 'Climatic factors: temperature, rainfall, humidity, light and wind. Edaphic (soil) factors: texture, pH, water and mineral content. Topographic factors: the slope, height and shape of the land.', 'abiotic components (non-living) climatic factors: temperature, rainfall, humidity, light and wind. edaphic (soil) factors: texture, ph, water and mineral content. topographic factors: the slope, height and shape of the land. the ecosystem, food chains, food webs and energy flow ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-12', 3, 'Biotic components (living)', 'Producers (autotrophs) make their own food from simple substances, by photosynthesis (using sunlight) or by chemosynthesis (using chemical energy). Examples: green plants, algae, phytoplankton. They trap the Sun''s energy and change it into chemical energy. Consumers (heterotrophs) cannot make their own food. Primary consumers are herbivores that eat plants (grasshopper, goat, cow). Secondary consumers are carnivores that eat herbivores (lizard, toad, cat). Tertiary consumers are top carnivores that eat other carnivores (lion, hawk, shark). Omnivores eat both plants and animals (humans, pigs). Decomposers (saprophytes) are bacteria and fungi (mushrooms, moulds) that break down dead bodies and wastes. They release minerals such as nitrates into the soil for plants. Without them, the ecosystem would be buried in dead material and nutrients would run out.', 'biotic components (living) producers (autotrophs) make their own food from simple substances, by photosynthesis (using sunlight) or by chemosynthesis (using chemical energy). examples: green plants, algae, phytoplankton. they trap the sun''s energy and change it into chemical energy. consumers (heterotrophs) cannot make their own food. primary consumers are herbivores that eat plants (grasshopper, goat, cow). secondary consumers are carnivores that eat herbivores (lizard, toad, cat). tertiary consumers are top carnivores that eat other carnivores (lion, hawk, shark). omnivores eat both plants and animals (humans, pigs). decomposers (saprophytes) are bacteria and fungi (mushrooms, moulds) that break down dead bodies and wastes. they release minerals such as nitrates into the soil for plants. without them, the ecosystem would be buried in dead material and nutrients would run out. the ecosystem, food chains, food webs and energy flow ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-12', 4, 'Food chains, food webs and trophic levels', 'A food chain is a straight line of who eats whom. The arrow means ''is eaten by'' or ''energy goes to''. Terrestrial example: grass → grasshopper → toad → snake → hawk. Aquatic example: phytoplankton → zooplankton → small fish → large fish → fish eagle. Maize → grasshopper → toad → snake: the toad is the secondary consumer. A food web is a network of many linked food chains, because most animals eat more than one food. It makes the ecosystem stable: if one food source fails, the animal can switch to another. A trophic level is the feeding position: level 1 producers, level 2 primary consumers, level 3 secondary consumers, level 4 tertiary consumers.', 'food chains, food webs and trophic levels a food chain is a straight line of who eats whom. the arrow means ''is eaten by'' or ''energy goes to''. terrestrial example: grass → grasshopper → toad → snake → hawk. aquatic example: phytoplankton → zooplankton → small fish → large fish → fish eagle. maize → grasshopper → toad → snake: the toad is the secondary consumer. a food web is a network of many linked food chains, because most animals eat more than one food. it makes the ecosystem stable: if one food source fails, the animal can switch to another. a trophic level is the feeding position: level 1 producers, level 2 primary consumers, level 3 secondary consumers, level 4 tertiary consumers. the ecosystem, food chains, food webs and energy flow ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-12', 5, 'Energy flow and the 10% rule', 'Energy comes from the Sun and flows in one direction: Sun → producers → consumers. It is not recycled; it is lost as heat. At each step only about 10% of the energy passes to the next level. The grasshopper uses energy for movement and flying, loses heat in respiration, and loses energy in faeces and excretion; only about 10% is stored in its body to pass to the lizard. Because of this, food chains are short (usually 4 or 5 links) and there are fewer top carnivores than herbivores, which explains why lions are rare compared with zebras.', 'energy flow and the 10% rule energy comes from the sun and flows in one direction: sun → producers → consumers. it is not recycled; it is lost as heat. at each step only about 10% of the energy passes to the next level. the grasshopper uses energy for movement and flying, loses heat in respiration, and loses energy in faeces and excretion; only about 10% is stored in its body to pass to the lizard. because of this, food chains are short (usually 4 or 5 links) and there are fewer top carnivores than herbivores, which explains why lions are rare compared with zebras. the ecosystem, food chains, food webs and energy flow ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-13', 'Ecological Pyramids, Cycles and the Balance of Nature') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-13', 0, 'Ecological Pyramids, Cycles and the Balance of Nature: summary', 'Pyramids of numbers, biomass and energy, the carbon and water cycles, and how predator and prey populations balance each other. Key words: Pyramid of numbers, Pyramid of biomass, Pyramid of energy, Predator-prey, Dynamic equilibrium.', 'ecological pyramids, cycles and the balance of nature: summary pyramids of numbers, biomass and energy, the carbon and water cycles, and how predator and prey populations balance each other. key words: pyramid of numbers, pyramid of biomass, pyramid of energy, predator-prey, dynamic equilibrium. ecological pyramids, cycles and the balance of nature ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-13', 1, 'Ecological pyramids', 'Pyramid of numbers: the number of organisms at each level. It is usually upright (many grass plants, fewer grasshoppers, one lizard). It can be inverted: one big mango tree can feed hundreds of caterpillars. Pyramid of biomass: the total mass of living matter at each level. It is usually upright. It can be inverted in the sea, where the small mass of phytoplankton at any moment is smaller than the mass of the zooplankton that eat it, because phytoplankton reproduce so fast that they replace themselves within days. (The lesson note says the phytoplankton support ''massive whales''; most big whales actually eat krill, which are zooplankton, so the correct link is phytoplankton to zooplankton.) Pyramid of energy: the amount of energy at each level over a year. It is always upright, because energy is lost at every step and can never increase.', 'ecological pyramids pyramid of numbers: the number of organisms at each level. it is usually upright (many grass plants, fewer grasshoppers, one lizard). it can be inverted: one big mango tree can feed hundreds of caterpillars. pyramid of biomass: the total mass of living matter at each level. it is usually upright. it can be inverted in the sea, where the small mass of phytoplankton at any moment is smaller than the mass of the zooplankton that eat it, because phytoplankton reproduce so fast that they replace themselves within days. (the lesson note says the phytoplankton support ''massive whales''; most big whales actually eat krill, which are zooplankton, so the correct link is phytoplankton to zooplankton.) pyramid of energy: the amount of energy at each level over a year. it is always upright, because energy is lost at every step and can never increase. ecological pyramids, cycles and the balance of nature ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-13', 2, 'Why the energy pyramid is always broad at the base', 'Each level receives only about 10% of the level below. The base must be the widest to provide enough energy to support everything above. This is why an energy pyramid cannot be inverted.', 'why the energy pyramid is always broad at the base each level receives only about 10% of the level below. the base must be the widest to provide enough energy to support everything above. this is why an energy pyramid cannot be inverted. ecological pyramids, cycles and the balance of nature ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-13', 3, 'Nutrient cycling: matter is recycled', 'Energy is lost, but the chemical elements are used again and again. Carbon cycle: plants remove CO₂ from the air in photosynthesis. CO₂ is added by respiration (all living things), decay (decomposers) and combustion (burning wood and fossil fuels such as petrol and diesel, which release carbon stored millions of years ago). Water cycle: evaporation (the Sun turns water into vapour), transpiration (plants lose vapour from leaves), condensation (the vapour cools into clouds) and precipitation (rain, snow or hail). See the diagrams in the First Term notes.', 'nutrient cycling: matter is recycled energy is lost, but the chemical elements are used again and again. carbon cycle: plants remove co₂ from the air in photosynthesis. co₂ is added by respiration (all living things), decay (decomposers) and combustion (burning wood and fossil fuels such as petrol and diesel, which release carbon stored millions of years ago). water cycle: evaporation (the sun turns water into vapour), transpiration (plants lose vapour from leaves), condensation (the vapour cools into clouds) and precipitation (rain, snow or hail). see the diagrams in the first term notes. ecological pyramids, cycles and the balance of nature ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-13', 4, 'The balance of nature', 'An ecosystem is in a dynamic equilibrium: it constantly changes but stays about the same on average. For example: if the number of rats increases, the snakes that eat them have plenty of food and their number increases. The snakes eat so many rats that the rat population falls. Now the snakes have less food and many starve, so their number falls. The rats recover, and the cycle repeats. This is a negative feedback loop in nature. If a farmer kills all the hawks, the snakes and mice are no longer controlled by their predator: the snakes will increase at first, and they will eat more mice and reduce them, until food becomes short. Taking one species out of a food web can have effects on many others, which is why we conserve biodiversity.', 'the balance of nature an ecosystem is in a dynamic equilibrium: it constantly changes but stays about the same on average. for example: if the number of rats increases, the snakes that eat them have plenty of food and their number increases. the snakes eat so many rats that the rat population falls. now the snakes have less food and many starve, so their number falls. the rats recover, and the cycle repeats. this is a negative feedback loop in nature. if a farmer kills all the hawks, the snakes and mice are no longer controlled by their predator: the snakes will increase at first, and they will eat more mice and reduce them, until food becomes short. taking one species out of a food web can have effects on many others, which is why we conserve biodiversity. ecological pyramids, cycles and the balance of nature ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-14', 'The Male Reproductive System') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-14', 0, 'The Male Reproductive System: summary', 'The parts of the human male reproductive system and the function of each, including the accessory glands and semen. Key words: Testis, Scrotum, Epididymis, Vas deferens, Prostate gland, Semen.', 'the male reproductive system: summary the parts of the human male reproductive system and the function of each, including the accessory glands and semen. key words: testis, scrotum, epididymis, vas deferens, prostate gland, semen. the male reproductive system ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-14', 1, 'What reproduction does', 'Reproduction is the making of new individuals of the same species, and it ensures that life continues. Humans reproduce sexually: a male gamete (sperm) joins with a female gamete (ovum or egg). The male system makes sperm and delivers them into the female.', 'what reproduction does reproduction is the making of new individuals of the same species, and it ensures that life continues. humans reproduce sexually: a male gamete (sperm) joins with a female gamete (ovum or egg). the male system makes sperm and delivers them into the female. the male reproductive system ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-14', 2, 'External parts', 'Scrotum: a skin bag that hangs outside the body and holds the testes. It keeps them about 2 to 3 °C cooler than the body, which is needed for sperm to develop properly. Penis: the organ for passing sperm into the female. It has spongy erectile tissue that fills with blood to make it stiff (erection).', 'external parts scrotum: a skin bag that hangs outside the body and holds the testes. it keeps them about 2 to 3 °c cooler than the body, which is needed for sperm to develop properly. penis: the organ for passing sperm into the female. it has spongy erectile tissue that fills with blood to make it stiff (erection). the male reproductive system ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-14', 3, 'Internal parts', 'Testes (singular testis): two oval organs in the scrotum. They make sperm cells (in tubules called seminiferous tubules) and the male hormone testosterone (in cells between the tubules), which brings about male features such as a deep voice and beard growth. Epididymis: a coiled tube on each testis, where sperm are stored and finish maturing so that they can swim. Vas deferens (sperm duct): a long tube that carries sperm from the epididymis towards the urethra. Urethra: the tube through the penis that carries both urine and semen, but never at the same time.', 'internal parts testes (singular testis): two oval organs in the scrotum. they make sperm cells (in tubules called seminiferous tubules) and the male hormone testosterone (in cells between the tubules), which brings about male features such as a deep voice and beard growth. epididymis: a coiled tube on each testis, where sperm are stored and finish maturing so that they can swim. vas deferens (sperm duct): a long tube that carries sperm from the epididymis towards the urethra. urethra: the tube through the penis that carries both urine and semen, but never at the same time. the male reproductive system ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-14', 4, 'Accessory glands', 'These add fluids to the sperm to make semen. The seminal vesicles make a sugary fluid (fructose) that gives the sperm energy. The prostate gland makes an alkaline fluid that neutralises the acid in the vagina and helps sperm survive. Cowper''s gland makes a lubricating fluid. Semen is about 2 to 5 ml in each ejaculation and contains hundreds of millions of sperm.', 'accessory glands these add fluids to the sperm to make semen. the seminal vesicles make a sugary fluid (fructose) that gives the sperm energy. the prostate gland makes an alkaline fluid that neutralises the acid in the vagina and helps sperm survive. cowper''s gland makes a lubricating fluid. semen is about 2 to 5 ml in each ejaculation and contains hundreds of millions of sperm. the male reproductive system ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-14', 5, 'Health note', 'Keep the area clean. Tight underwear and hot baths can lower sperm production. Prostate problems in older men should be checked by a doctor. Any pain or swelling in the testes needs prompt medical attention.', 'health note keep the area clean. tight underwear and hot baths can lower sperm production. prostate problems in older men should be checked by a doctor. any pain or swelling in the testes needs prompt medical attention. the male reproductive system ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-15', 'The Female Reproductive System and the Gametes') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-15', 0, 'The Female Reproductive System and the Gametes: summary', 'The parts of the human female reproductive system, and the structure of the sperm cell and the egg cell with their differences. Key words: Ovary, Fallopian tube, Uterus, Endometrium, Cervix, Acrosome, Ovum.', 'the female reproductive system and the gametes: summary the parts of the human female reproductive system, and the structure of the sperm cell and the egg cell with their differences. key words: ovary, fallopian tube, uterus, endometrium, cervix, acrosome, ovum. the female reproductive system and the gametes ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-15', 1, 'The female system', 'The female system makes eggs (ova), receives sperm, and nurtures the developing baby.', 'the female system the female system makes eggs (ova), receives sperm, and nurtures the developing baby. the female reproductive system and the gametes ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-15', 2, 'The parts', 'Ovaries (two): almond-shaped organs in the lower abdomen. They make ova (eggs) and the hormones oestrogen and progesterone. Fallopian tubes (oviducts): tubes between each ovary and the uterus. Fertilisation takes place here. Cilia and muscle contractions push the egg towards the uterus. Uterus (womb): a pear-shaped muscular organ where the foetus develops. Its lining is the endometrium, which thickens each month to receive an embryo. Cervix: the narrow neck of the uterus that opens into the vagina; it widens in childbirth. Vagina: a muscular tube leading to the outside. It receives the penis during intercourse and is the birth canal during delivery.', 'the parts ovaries (two): almond-shaped organs in the lower abdomen. they make ova (eggs) and the hormones oestrogen and progesterone. fallopian tubes (oviducts): tubes between each ovary and the uterus. fertilisation takes place here. cilia and muscle contractions push the egg towards the uterus. uterus (womb): a pear-shaped muscular organ where the foetus develops. its lining is the endometrium, which thickens each month to receive an embryo. cervix: the narrow neck of the uterus that opens into the vagina; it widens in childbirth. vagina: a muscular tube leading to the outside. it receives the penis during intercourse and is the birth canal during delivery. the female reproductive system and the gametes ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-15', 3, 'The sperm cell', 'A sperm is tiny and mobile. Head: contains the nucleus with the genetic material, and the acrosome, a cap of enzymes that dissolves the outer layer of the egg. Middle piece: packed with mitochondria that provide energy for swimming. Tail (flagellum): a long whip that drives the sperm along.', 'the sperm cell a sperm is tiny and mobile. head: contains the nucleus with the genetic material, and the acrosome, a cap of enzymes that dissolves the outer layer of the egg. middle piece: packed with mitochondria that provide energy for swimming. tail (flagellum): a long whip that drives the sperm along. the female reproductive system and the gametes ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-15', 4, 'The egg cell (ovum)', 'The ovum is spherical and much larger than the sperm, and it cannot move on its own (it is carried by cilia). It has cytoplasm with yolk (food store) for the early embryo, a nucleus, and a jelly coat (zona pellucida) which hardens after one sperm has entered so that no other sperm can enter.', 'the egg cell (ovum) the ovum is spherical and much larger than the sperm, and it cannot move on its own (it is carried by cilia). it has cytoplasm with yolk (food store) for the early embryo, a nucleus, and a jelly coat (zona pellucida) which hardens after one sperm has entered so that no other sperm can enter. the female reproductive system and the gametes ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-15', 5, 'Comparing the gametes', 'Study the table. Size; Very small; Much larger (the largest human cell). Movement; Moves actively with a tail; Does not move; is carried by cilia. Number; Millions made every day; One released each month. Food store; Very little; Yolk in the cytoplasm. Special parts; Acrosome, mitochondria, tail; Jelly coat. Chromosomes; 23 (haploid); 23 (haploid).', 'comparing the gametes study the table. size; very small; much larger (the largest human cell). movement; moves actively with a tail; does not move; is carried by cilia. number; millions made every day; one released each month. food store; very little; yolk in the cytoplasm. special parts; acrosome, mitochondria, tail; jelly coat. chromosomes; 23 (haploid); 23 (haploid). the female reproductive system and the gametes ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-16', 'Ovulation and the Menstrual Cycle') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-16', 0, 'Ovulation and the Menstrual Cycle: summary', 'The 28-day cycle with its four phases and hormones (FSH, LH, oestrogen, progesterone), and why a pregnant woman does not menstruate. Key words: Menstruation, Ovulation, FSH, LH, Progesterone, Corpus luteum.', 'ovulation and the menstrual cycle: summary the 28-day cycle with its four phases and hormones (fsh, lh, oestrogen, progesterone), and why a pregnant woman does not menstruate. key words: menstruation, ovulation, fsh, lh, progesterone, corpus luteum. ovulation and the menstrual cycle ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-16', 1, 'A monthly cycle', 'From puberty until about 45 to 50 years old, the female body prepares each month for a possible pregnancy. The average cycle is 28 days, though 21 to 35 days is normal, and it may be irregular in young girls.', 'a monthly cycle from puberty until about 45 to 50 years old, the female body prepares each month for a possible pregnancy. the average cycle is 28 days, though 21 to 35 days is normal, and it may be irregular in young girls. ovulation and the menstrual cycle ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-16', 2, 'The four phases', '1. Menstruation (about days 1 to 5): if there was no pregnancy, the lining of the uterus breaks down and leaves the body through the vagina as a flow of blood and tissue (a period). In the chart it lasts to about day 6; it may last 3 to 7 days. 2. Follicular phase (to about day 13): the pituitary gland releases FSH (follicle-stimulating hormone), which makes a follicle in the ovary grow and mature an egg. The follicle releases oestrogen, which rebuilds the uterus lining. 3. Ovulation (about day 14): a surge in LH (luteinising hormone) makes the follicle burst and release the mature egg into the fallopian tube. This is the most fertile time. 4. Luteal phase (days 15 to 28): the empty follicle becomes the corpus luteum, which makes progesterone to keep the uterus lining thick and rich in blood. If the egg is not fertilised, the corpus luteum breaks down, the hormone levels fall and menstruation begins again.', 'the four phases 1. menstruation (about days 1 to 5): if there was no pregnancy, the lining of the uterus breaks down and leaves the body through the vagina as a flow of blood and tissue (a period). in the chart it lasts to about day 6; it may last 3 to 7 days. 2. follicular phase (to about day 13): the pituitary gland releases fsh (follicle-stimulating hormone), which makes a follicle in the ovary grow and mature an egg. the follicle releases oestrogen, which rebuilds the uterus lining. 3. ovulation (about day 14): a surge in lh (luteinising hormone) makes the follicle burst and release the mature egg into the fallopian tube. this is the most fertile time. 4. luteal phase (days 15 to 28): the empty follicle becomes the corpus luteum, which makes progesterone to keep the uterus lining thick and rich in blood. if the egg is not fertilised, the corpus luteum breaks down, the hormone levels fall and menstruation begins again. ovulation and the menstrual cycle ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-16', 3, 'The hormones at a glance', 'Compare the hormones. FSH; Pituitary; Grows the follicle and egg. Oestrogen; Ovary (follicle); Rebuilds the uterus lining; triggers the LH surge. LH; Pituitary; Causes ovulation; forms the corpus luteum. Progesterone; Corpus luteum; Maintains the uterus lining; stops new follicles.', 'the hormones at a glance compare the hormones. fsh; pituitary; grows the follicle and egg. oestrogen; ovary (follicle); rebuilds the uterus lining; triggers the lh surge. lh; pituitary; causes ovulation; forms the corpus luteum. progesterone; corpus luteum; maintains the uterus lining; stops new follicles. ovulation and the menstrual cycle ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-16', 4, 'Why no periods in pregnancy', 'If the egg is fertilised, the embryo implants in the thick uterus lining, and the placenta soon makes hormones (including hCG) that keep the corpus luteum and progesterone going. The lining is kept in place to feed the embryo, so menstruation does not occur. A missed period is often the first sign of pregnancy.', 'why no periods in pregnancy if the egg is fertilised, the embryo implants in the thick uterus lining, and the placenta soon makes hormones (including hcg) that keep the corpus luteum and progesterone going. the lining is kept in place to feed the embryo, so menstruation does not occur. a missed period is often the first sign of pregnancy. ovulation and the menstrual cycle ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-16', 5, 'Caring for yourself', 'Girls should be taught about periods before they start: use clean pads, wash regularly and change often. Mild pain is normal; severe pain or very heavy bleeding should be checked by a doctor. Families and schools should support girls so that they do not miss school.', 'caring for yourself girls should be taught about periods before they start: use clean pads, wash regularly and change often. mild pain is normal; severe pain or very heavy bleeding should be checked by a doctor. families and schools should support girls so that they do not miss school. ovulation and the menstrual cycle ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-17', 'Fertilisation, Pregnancy and Birth') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-17', 0, 'Fertilisation, Pregnancy and Birth: summary', 'Fertilisation, implantation, the placenta and amniotic fluid, pregnancy (gestation), birth, and a note on sexually transmitted infections. Key words: Zygote, Implantation, Gestation, Placenta, Amniotic fluid, Parturition.', 'fertilisation, pregnancy and birth: summary fertilisation, implantation, the placenta and amniotic fluid, pregnancy (gestation), birth, and a note on sexually transmitted infections. key words: zygote, implantation, gestation, placenta, amniotic fluid, parturition. fertilisation, pregnancy and birth ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-17', 1, 'Fertilisation', 'Millions of sperm are released into the vagina during intercourse. They swim through the cervix and uterus into the fallopian tube; only one fertilises the egg. The sperm head releases enzymes from the acrosome, enters the egg, and the nucleus of the sperm (n) fuses with the nucleus of the egg (n) to give a zygote (2n). The jelly coat then hardens to keep out other sperm.', 'fertilisation millions of sperm are released into the vagina during intercourse. they swim through the cervix and uterus into the fallopian tube; only one fertilises the egg. the sperm head releases enzymes from the acrosome, enters the egg, and the nucleus of the sperm (n) fuses with the nucleus of the egg (n) to give a zygote (2n). the jelly coat then hardens to keep out other sperm. fertilisation, pregnancy and birth ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-17', 2, 'Implantation', 'The zygote divides again and again by mitosis to form a ball of cells (the embryo) as it travels down the tube. After about 6 to 7 days it reaches the uterus and sinks into the thick lining (implantation).', 'implantation the zygote divides again and again by mitosis to form a ball of cells (the embryo) as it travels down the tube. after about 6 to 7 days it reaches the uterus and sinks into the thick lining (implantation). fertilisation, pregnancy and birth ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-17', 3, 'Gestation (pregnancy)', 'Gestation is the time from fertilisation to birth, about 9 months (40 weeks counted from the last period). The developing baby is called an embryo for the first 8 weeks and a foetus after that. Its organs form in the early months, so a mother should avoid alcohol, smoking, harmful drugs and self-medication, and should attend antenatal clinic regularly, take the iron and folic acid given, and sleep under a treated net to prevent malaria.', 'gestation (pregnancy) gestation is the time from fertilisation to birth, about 9 months (40 weeks counted from the last period). the developing baby is called an embryo for the first 8 weeks and a foetus after that. its organs form in the early months, so a mother should avoid alcohol, smoking, harmful drugs and self-medication, and should attend antenatal clinic regularly, take the iron and folic acid given, and sleep under a treated net to prevent malaria. fertilisation, pregnancy and birth ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-17', 4, 'The placenta, cord and amniotic fluid', 'The placenta is a disc-shaped organ made of tissues from both mother and embryo. It lets food, oxygen, water and antibodies pass from mother to baby, and lets CO₂ and urea pass from baby to mother. The mother''s blood and the baby''s blood do not mix (they are separated by thin walls so that substances pass by diffusion and active transport), which also protects the baby from the mother''s blood pressure and some germs. The placenta also makes hormones. The umbilical cord links the baby to the placenta; it has two arteries and one vein. The amniotic sac holds the amniotic fluid. It acts as a shock absorber, protects from bumps and sudden changes in temperature, keeps the baby from drying out, and allows the baby to move. (This answers: ''what protects the foetus from shock and drying out?'')', 'the placenta, cord and amniotic fluid the placenta is a disc-shaped organ made of tissues from both mother and embryo. it lets food, oxygen, water and antibodies pass from mother to baby, and lets co₂ and urea pass from baby to mother. the mother''s blood and the baby''s blood do not mix (they are separated by thin walls so that substances pass by diffusion and active transport), which also protects the baby from the mother''s blood pressure and some germs. the placenta also makes hormones. the umbilical cord links the baby to the placenta; it has two arteries and one vein. the amniotic sac holds the amniotic fluid. it acts as a shock absorber, protects from bumps and sudden changes in temperature, keeps the baby from drying out, and allows the baby to move. (this answers: ''what protects the foetus from shock and drying out?'') fertilisation, pregnancy and birth ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-17', 5, 'Birth (parturition)', 'At the end of pregnancy the hormone oxytocin makes the muscles of the uterus contract (labour). The cervix widens, the amnion breaks and the fluid comes out (''the waters break''), and the baby is pushed out head first through the vagina. The umbilical cord is cut and tied, and the placenta follows as the afterbirth. After birth the mother makes milk (lactation) under the control of the hormone prolactin. Breast milk gives antibodies and the best food in the first 6 months of life. Always deliver in a clinic or hospital with a skilled birth attendant.', 'birth (parturition) at the end of pregnancy the hormone oxytocin makes the muscles of the uterus contract (labour). the cervix widens, the amnion breaks and the fluid comes out (''the waters break''), and the baby is pushed out head first through the vagina. the umbilical cord is cut and tied, and the placenta follows as the afterbirth. after birth the mother makes milk (lactation) under the control of the hormone prolactin. breast milk gives antibodies and the best food in the first 6 months of life. always deliver in a clinic or hospital with a skilled birth attendant. fertilisation, pregnancy and birth ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-17', 6, 'Protecting health: STIs', 'Sexually transmitted infections (STIs), such as gonorrhoea, syphilis, HIV/AIDS and hepatitis B, are spread by unprotected sex. They can cause infertility and harm babies. Prevention: abstinence before marriage, faithfulness to one uninfected partner, correct use of condoms, testing, and treatment early. Students are encouraged to talk to a health worker or teacher about any questions.', 'protecting health: stis sexually transmitted infections (stis), such as gonorrhoea, syphilis, hiv/aids and hepatitis b, are spread by unprotected sex. they can cause infertility and harm babies. prevention: abstinence before marriage, faithfulness to one uninfected partner, correct use of condoms, testing, and treatment early. students are encouraged to talk to a health worker or teacher about any questions. fertilisation, pregnancy and birth ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-18', 'From Pollination to Fertilisation in Flowering Plants') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-18', 0, 'From Pollination to Fertilisation in Flowering Plants: summary', 'A recap of pollination, the growth of the pollen tube, double fertilisation, and the changes in the flower afterwards. Key words: Pollen tube, Micropyle, Double fertilisation, Endosperm, Zygote, Triploid nucleus.', 'from pollination to fertilisation in flowering plants: summary a recap of pollination, the growth of the pollen tube, double fertilisation, and the changes in the flower afterwards. key words: pollen tube, micropyle, double fertilisation, endosperm, zygote, triploid nucleus. from pollination to fertilisation in flowering plants ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-18', 1, 'Pollination is only the arrival', 'Recall that the flower is the sexual reproductive organ of a flowering plant. The stamen (anther and filament) is the male part. The carpel (stigma, style and ovary with ovules) is the female part. Pollination is the transfer of mature pollen grains from the anther to the stigma. Self-pollination (for example tomato) is within the same flower or plant; cross-pollination (for example pawpaw) is between flowers of different plants of the same species and gives healthier and more varied offspring. Insect-pollinated flowers (hibiscus, pride of Barbados) are large, coloured and scented, have nectar, a sticky stigma and rough sticky pollen. Wind-pollinated flowers (maize, grasses, rice) are small, dull and scentless, have anthers and feathery stigmas hanging outside, and make light, smooth pollen in huge amounts. Wind pollen is plentiful because most of it is lost and only a few grains land on a stigma by chance.', 'pollination is only the arrival recall that the flower is the sexual reproductive organ of a flowering plant. the stamen (anther and filament) is the male part. the carpel (stigma, style and ovary with ovules) is the female part. pollination is the transfer of mature pollen grains from the anther to the stigma. self-pollination (for example tomato) is within the same flower or plant; cross-pollination (for example pawpaw) is between flowers of different plants of the same species and gives healthier and more varied offspring. insect-pollinated flowers (hibiscus, pride of barbados) are large, coloured and scented, have nectar, a sticky stigma and rough sticky pollen. wind-pollinated flowers (maize, grasses, rice) are small, dull and scentless, have anthers and feathery stigmas hanging outside, and make light, smooth pollen in huge amounts. wind pollen is plentiful because most of it is lost and only a few grains land on a stigma by chance. from pollination to fertilisation in flowering plants ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-18', 2, 'Fertilisation step by step', 'Pollination only brings the pollen to the stigma. Fertilisation is the fusion of the gametes. 1. Germination of pollen: a pollen grain landing on a compatible stigma takes in a sugary liquid and swells. 2. Pollen tube growth: the grain grows a tube that pushes down through the style towards the ovary, with the male nuclei inside. 3. Entry: the tube enters the ovule through a tiny pore called the micropyle. 4. Double fertilisation: one male nucleus fuses with the egg cell to form the zygote (the future plant), and the other fuses with the two polar nuclei (the secondary nucleus) to form a triploid (3n) nucleus, which becomes the endosperm (food store). Two fusions occur, so it is called double fertilisation; it is a special feature of flowering plants.', 'fertilisation step by step pollination only brings the pollen to the stigma. fertilisation is the fusion of the gametes. 1. germination of pollen: a pollen grain landing on a compatible stigma takes in a sugary liquid and swells. 2. pollen tube growth: the grain grows a tube that pushes down through the style towards the ovary, with the male nuclei inside. 3. entry: the tube enters the ovule through a tiny pore called the micropyle. 4. double fertilisation: one male nucleus fuses with the egg cell to form the zygote (the future plant), and the other fuses with the two polar nuclei (the secondary nucleus) to form a triploid (3n) nucleus, which becomes the endosperm (food store). two fusions occur, so it is called double fertilisation; it is a special feature of flowering plants. from pollination to fertilisation in flowering plants ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-18', 3, 'Changes after fertilisation', 'The petals and sepals usually wither and fall off. The stigma and style also wither. The changes are summarised below. Ovary; Fruit. Ovary wall; Pericarp (fruit wall). Ovule; Seed. Integuments (ovule walls); Testa (seed coat). Zygote; Embryo (baby plant). Triploid nucleus; Endosperm (food store).', 'changes after fertilisation the petals and sepals usually wither and fall off. the stigma and style also wither. the changes are summarised below. ovary; fruit. ovary wall; pericarp (fruit wall). ovule; seed. integuments (ovule walls); testa (seed coat). zygote; embryo (baby plant). triploid nucleus; endosperm (food store). from pollination to fertilisation in flowering plants ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-18', 4, 'A common question', 'Why do the petals fall off while tomato seeds form inside the fruit? Because the petals have finished their job of attracting pollinators. The plant then sends its food and energy to the ovary to grow the fruit and seeds, instead of wasting it on the petals.', 'a common question why do the petals fall off while tomato seeds form inside the fruit? because the petals have finished their job of attracting pollinators. the plant then sends its food and energy to the ovary to grow the fruit and seeds, instead of wasting it on the petals. from pollination to fertilisation in flowering plants ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-19', 'The Structure of Seeds: Bean and Maize') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-19', 0, 'The Structure of Seeds: Bean and Maize: summary', 'Monocot and dicot seeds, the parts of a bean seed, and the maize grain as a fruit with its scutellum and coleoptile. Key words: Testa, Hilum, Micropyle, Plumule, Radicle, Cotyledon, Endosperm, Caryopsis.', 'the structure of seeds: bean and maize: summary monocot and dicot seeds, the parts of a bean seed, and the maize grain as a fruit with its scutellum and coleoptile. key words: testa, hilum, micropyle, plumule, radicle, cotyledon, endosperm, caryopsis. the structure of seeds: bean and maize ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-19', 1, 'A seed is a ripened ovule', 'A seed is a ripened, fertilised ovule that contains the embryo plant with a store of food. Monocotyledonous seeds (maize, rice, wheat) have one cotyledon (seed leaf), and the food is mostly stored in a separate endosperm. Dicotyledonous seeds (bean, groundnut, mango) have two cotyledons, which are large and store the food (starch and protein).', 'a seed is a ripened ovule a seed is a ripened, fertilised ovule that contains the embryo plant with a store of food. monocotyledonous seeds (maize, rice, wheat) have one cotyledon (seed leaf), and the food is mostly stored in a separate endosperm. dicotyledonous seeds (bean, groundnut, mango) have two cotyledons, which are large and store the food (starch and protein). the structure of seeds: bean and maize ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-19', 2, 'The bean seed (a dicot)', 'Testa: the tough brown seed coat, which protects against fungi, bacteria and insects. Hilum: a scar showing where the seed was joined to the pod. Micropyle: a tiny pore near the hilum, through which water and air enter when the seed germinates. Embryo: made of the plumule (the young shoot, with the epicotyl above the cotyledons), the radicle (the young root) and the hypocotyl (the stem part below the cotyledons). Cotyledons: two large fleshy ''seed leaves'' that store food.', 'the bean seed (a dicot) testa: the tough brown seed coat, which protects against fungi, bacteria and insects. hilum: a scar showing where the seed was joined to the pod. micropyle: a tiny pore near the hilum, through which water and air enter when the seed germinates. embryo: made of the plumule (the young shoot, with the epicotyl above the cotyledons), the radicle (the young root) and the hypocotyl (the stem part below the cotyledons). cotyledons: two large fleshy ''seed leaves'' that store food. the structure of seeds: bean and maize ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-19', 3, 'The maize grain (a monocot)', 'A maize ''seed'' is actually a whole fruit called a caryopsis (grain), because the fruit wall (pericarp) is joined tightly to the seed coat. Endosperm: the large yellow part that stores starch. Scutellum: the single cotyledon, which lies between the endosperm and the embryo and absorbs digested food from the endosperm for the growing embryo. Coleoptile: a sheath that protects the young shoot (plumule). Coleorhiza: a sheath that protects the young root (radicle). How to see it: soak maize grains for a day, cut one lengthwise with a blade, and put a drop of iodine on the cut face. The endosperm turns blue-black, showing starch. Draw and label it.', 'the maize grain (a monocot) a maize ''seed'' is actually a whole fruit called a caryopsis (grain), because the fruit wall (pericarp) is joined tightly to the seed coat. endosperm: the large yellow part that stores starch. scutellum: the single cotyledon, which lies between the endosperm and the embryo and absorbs digested food from the endosperm for the growing embryo. coleoptile: a sheath that protects the young shoot (plumule). coleorhiza: a sheath that protects the young root (radicle). how to see it: soak maize grains for a day, cut one lengthwise with a blade, and put a drop of iodine on the cut face. the endosperm turns blue-black, showing starch. draw and label it. the structure of seeds: bean and maize ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-19', 4, 'Bean and maize compared', 'Study the table. Cotyledons; Two, large and fleshy; One (scutellum), thin. Food store; In the cotyledons; In the endosperm. Fruit wall; Separate from the seed coat (pod); Fused to the seed coat (caryopsis). Shoot and root sheaths; None; Coleoptile and coleorhiza. Germination; Epigeal; Hypogeal.', 'bean and maize compared study the table. cotyledons; two, large and fleshy; one (scutellum), thin. food store; in the cotyledons; in the endosperm. fruit wall; separate from the seed coat (pod); fused to the seed coat (caryopsis). shoot and root sheaths; none; coleoptile and coleorhiza. germination; epigeal; hypogeal. the structure of seeds: bean and maize ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-20', 'Germination of Seeds') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-20', 0, 'Germination of Seeds: summary', 'The conditions needed for germination, epigeal and hypogeal germination, dormancy and a home experiment. Key words: Germination, Dormancy, Epigeal, Hypogeal, Hypocotyl, Epicotyl.', 'germination of seeds: summary the conditions needed for germination, epigeal and hypogeal germination, dormancy and a home experiment. key words: germination, dormancy, epigeal, hypogeal, hypocotyl, epicotyl. germination of seeds ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-20', 1, 'What is germination?', 'Germination is the waking of the embryo from its resting stage (dormancy) so that it grows into a seedling. Dry seeds have very little water and respire very slowly.', 'what is germination? germination is the waking of the embryo from its resting stage (dormancy) so that it grows into a seedling. dry seeds have very little water and respire very slowly. germination of seeds ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-20', 2, 'Conditions needed: remember ''WOW''', 'Water: to soften the testa, make the cells swell and start the enzymes working to digest the stored food. Oxygen: for respiration, which releases energy for growth (seeds in waterlogged soil may rot). Warmth: a suitable temperature, usually about 25 to 35 °C, for enzymes to work. Light is not normally needed for the first stages (a few seeds, such as some weeds, need light). Soil is also not needed, as seeds germinate on wet cotton wool.', 'conditions needed: remember ''wow'' water: to soften the testa, make the cells swell and start the enzymes working to digest the stored food. oxygen: for respiration, which releases energy for growth (seeds in waterlogged soil may rot). warmth: a suitable temperature, usually about 25 to 35 °c, for enzymes to work. light is not normally needed for the first stages (a few seeds, such as some weeds, need light). soil is also not needed, as seeds germinate on wet cotton wool. germination of seeds ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-20', 3, 'Epigeal germination', 'The cotyledons are carried above the ground. The hypocotyl (the stem part below the cotyledons) grows rapidly and forms an arch that pulls the cotyledons out of the soil. Examples: bean, melon, castor oil, groundnut, cowpea, morning glory. After the first true leaves open, the cotyledons shrink as the food is used, turn green for a short time and then wither and fall off.', 'epigeal germination the cotyledons are carried above the ground. the hypocotyl (the stem part below the cotyledons) grows rapidly and forms an arch that pulls the cotyledons out of the soil. examples: bean, melon, castor oil, groundnut, cowpea, morning glory. after the first true leaves open, the cotyledons shrink as the food is used, turn green for a short time and then wither and fall off. germination of seeds ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-20', 4, 'Hypogeal germination', 'The cotyledons stay under the ground. The epicotyl (the stem part above the cotyledons) grows quickly and pushes the shoot up. Examples: maize, guinea corn (sorghum), millet, pea, yam seed.', 'hypogeal germination the cotyledons stay under the ground. the epicotyl (the stem part above the cotyledons) grows quickly and pushes the shoot up. examples: maize, guinea corn (sorghum), millet, pea, yam seed. germination of seeds ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-20', 5, 'Epigeal and hypogeal compared', 'Study the table. Part that grows fast; Hypocotyl; Epicotyl. Cotyledons; Above the soil; Stay in the soil. Examples; Bean, melon, castor oil; Maize, millet, guinea corn.', 'epigeal and hypogeal compared study the table. part that grows fast; hypocotyl; epicotyl. cotyledons; above the soil; stay in the soil. examples; bean, melon, castor oil; maize, millet, guinea corn. germination of seeds ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-20', 6, 'Dormancy and how farmers break it', 'Dormancy is a resting stage in which a living seed does not germinate even when conditions are right. It lets seeds survive the dry season. Farmers can break it by soaking in water, scratching or nicking the hard seed coat (scarification), soaking in warm water, dipping in weak acid, or exposing to cold. Test your seeds first: put 20 in wet cotton wool and count how many germinate (germination percentage). Home project: plant 5 bean seeds and 5 maize seeds in two tins. Watch for 7 days. In bean you will see a loop (the hypocotyl arch) and fat cotyledons coming out first; in maize the green spear-like shoot comes out and the grain stays in the soil.', 'dormancy and how farmers break it dormancy is a resting stage in which a living seed does not germinate even when conditions are right. it lets seeds survive the dry season. farmers can break it by soaking in water, scratching or nicking the hard seed coat (scarification), soaking in warm water, dipping in weak acid, or exposing to cold. test your seeds first: put 20 in wet cotton wool and count how many germinate (germination percentage). home project: plant 5 bean seeds and 5 maize seeds in two tins. watch for 7 days. in bean you will see a loop (the hypocotyl arch) and fat cotyledons coming out first; in maize the green spear-like shoot comes out and the grain stays in the soil. germination of seeds ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-21', 'Fruits: Structure and Classification') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-21', 0, 'Fruits: Structure and Classification: summary', 'What a fruit is, the three layers of the pericarp, true and false fruits, simple, aggregate and multiple fruits, and the fleshy and dry types. Key words: Fruit, Pericarp, Epicarp, Mesocarp, Endocarp, True fruit, False fruit, Drupe, Berry.', 'fruits: structure and classification: summary what a fruit is, the three layers of the pericarp, true and false fruits, simple, aggregate and multiple fruits, and the fleshy and dry types. key words: fruit, pericarp, epicarp, mesocarp, endocarp, true fruit, false fruit, drupe, berry. fruits: structure and classification ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-21', 1, 'What is a fruit?', 'A fruit is a fertilised, ripened ovary that contains seeds. After fertilisation, the ovary swells and changes to protect the seeds and help to scatter them. In cooking, ''fruit'' means something sweet, but in biology tomatoes, okra, pepper and cucumber are all fruits, because they develop from flowers and contain seeds.', 'what is a fruit? a fruit is a fertilised, ripened ovary that contains seeds. after fertilisation, the ovary swells and changes to protect the seeds and help to scatter them. in cooking, ''fruit'' means something sweet, but in biology tomatoes, okra, pepper and cucumber are all fruits, because they develop from flowers and contain seeds. fruits: structure and classification ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-21', 2, 'The structure of a fruit', 'The wall of a fruit is the pericarp. In many fleshy fruits it has three layers: the epicarp (the outer skin or peel), the mesocarp (the middle, usually fleshy and edible layer) and the endocarp (the inner layer around the seed, sometimes hard and stony).', 'the structure of a fruit the wall of a fruit is the pericarp. in many fleshy fruits it has three layers: the epicarp (the outer skin or peel), the mesocarp (the middle, usually fleshy and edible layer) and the endocarp (the inner layer around the seed, sometimes hard and stony). fruits: structure and classification ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-21', 3, 'Classifying by origin', 'True fruit: made from the ovary only. Examples: mango, orange, cowpea. False fruit (pseudocarp): made from the ovary together with other parts of the flower. Examples: apple (the flesh is the swollen receptacle), cashew (the ''apple'' is the swollen stalk; the true fruit is the kidney-shaped nut hanging under it), strawberry (the red flesh is the receptacle; the real fruits are the tiny dots on it) and pineapple.', 'classifying by origin true fruit: made from the ovary only. examples: mango, orange, cowpea. false fruit (pseudocarp): made from the ovary together with other parts of the flower. examples: apple (the flesh is the swollen receptacle), cashew (the ''apple'' is the swollen stalk; the true fruit is the kidney-shaped nut hanging under it), strawberry (the red flesh is the receptacle; the real fruits are the tiny dots on it) and pineapple. fruits: structure and classification ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-21', 4, 'Classifying by composition', 'Simple fruit: from one flower with one ovary, for example bean, cherry, tomato. Aggregate fruit: from one flower with many separate ovaries, each becoming a small fruitlet in a cluster, for example strawberry and custard apple. Multiple (composite) fruit: from a whole cluster of flowers (an inflorescence) that fuse together, for example pineapple and breadfruit.', 'classifying by composition simple fruit: from one flower with one ovary, for example bean, cherry, tomato. aggregate fruit: from one flower with many separate ovaries, each becoming a small fruitlet in a cluster, for example strawberry and custard apple. multiple (composite) fruit: from a whole cluster of flowers (an inflorescence) that fuse together, for example pineapple and breadfruit. fruits: structure and classification ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-21', 5, 'Fleshy simple fruits', 'Berry: the whole pericarp is soft and juicy, usually with many seeds. Examples: tomato, pepper, guava, watermelon, and orange (a special berry called a hesperidium). Drupe: a fleshy mesocarp and a hard stony endocarp (a stone) around one seed. Examples: mango, coconut (a fibrous drupe), oil palm fruit, cherry. Pome: the outer flesh is the receptacle and the core is the real ovary. Examples: apple, pear.', 'fleshy simple fruits berry: the whole pericarp is soft and juicy, usually with many seeds. examples: tomato, pepper, guava, watermelon, and orange (a special berry called a hesperidium). drupe: a fleshy mesocarp and a hard stony endocarp (a stone) around one seed. examples: mango, coconut (a fibrous drupe), oil palm fruit, cherry. pome: the outer flesh is the receptacle and the core is the real ovary. examples: apple, pear. fruits: structure and classification ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-21', 6, 'Dry fruits', 'Dry dehiscent fruits split open when ripe to let out the seeds. Legume (pod): splits along two sides; bean, cowpea, flamboyant. Capsule: splits along many lines or pores; okra, cotton, poppy. Follicle: splits along one side only; kola, rose periwinkle. Schizocarp: breaks into one-seeded parts; Desmodium, Cassia. Dry indehiscent fruits do not split. Caryopsis (grain): the seed coat is fused to the fruit wall; maize, rice, grasses. Cypsela: a small one-seeded fruit often with a hairy parachute (pappus); Tridax, sunflower. Nut: a very hard woody pericarp; cashew nut. Samara: a fruit wall with a wing; Combretum.', 'dry fruits dry dehiscent fruits split open when ripe to let out the seeds. legume (pod): splits along two sides; bean, cowpea, flamboyant. capsule: splits along many lines or pores; okra, cotton, poppy. follicle: splits along one side only; kola, rose periwinkle. schizocarp: breaks into one-seeded parts; desmodium, cassia. dry indehiscent fruits do not split. caryopsis (grain): the seed coat is fused to the fruit wall; maize, rice, grasses. cypsela: a small one-seeded fruit often with a hairy parachute (pappus); tridax, sunflower. nut: a very hard woody pericarp; cashew nut. samara: a fruit wall with a wing; combretum. fruits: structure and classification ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-21', 7, 'Pointers', 'A maize grain is called a fruit, not just a seed, because the fruit wall is joined to the seed coat. A berry and a drupe differ in how the seed is protected: in a drupe a hard stony endocarp surrounds a single seed; in a berry the seeds lie in soft flesh with no stone.', 'pointers a maize grain is called a fruit, not just a seed, because the fruit wall is joined to the seed coat. a berry and a drupe differ in how the seed is protected: in a drupe a hard stony endocarp surrounds a single seed; in a berry the seeds lie in soft flesh with no stone. fruits: structure and classification ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-22', 'Seed and Fruit Dispersal and Parthenocarpy') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-22', 0, 'Seed and Fruit Dispersal and Parthenocarpy: summary', 'Why seeds are dispersed, the four methods (wind, water, animals and explosive) with their adaptations, and fruits that form without fertilisation. Key words: Dispersal, Pappus, Samara, Hooks, Explosive mechanism, Parthenocarpy.', 'seed and fruit dispersal and parthenocarpy: summary why seeds are dispersed, the four methods (wind, water, animals and explosive) with their adaptations, and fruits that form without fertilisation. key words: dispersal, pappus, samara, hooks, explosive mechanism, parthenocarpy. seed and fruit dispersal and parthenocarpy ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-22', 1, 'Why disperse seeds?', 'Dispersal is the scattering of seeds away from the parent plant. It prevents overcrowding, reduces competition for light, water and minerals, helps plants to colonise new places, and reduces the spread of disease among crowded seedlings.', 'why disperse seeds? dispersal is the scattering of seeds away from the parent plant. it prevents overcrowding, reduces competition for light, water and minerals, helps plants to colonise new places, and reduces the spread of disease among crowded seedlings. seed and fruit dispersal and parthenocarpy ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-22', 2, 'Dispersal by wind', 'Adaptations: very small and light seeds (orchids); wings, as in the samara of Combretum and Terminalia; parachutes of hairs (pappus) as in Tridax, dandelion and cotton seeds; plumes and flat shapes. Wind-dispersed fruits are dry and light.', 'dispersal by wind adaptations: very small and light seeds (orchids); wings, as in the samara of combretum and terminalia; parachutes of hairs (pappus) as in tridax, dandelion and cotton seeds; plumes and flat shapes. wind-dispersed fruits are dry and light. seed and fruit dispersal and parthenocarpy ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-22', 3, 'Dispersal by water', 'Adaptations: buoyancy so that they float; a waterproof outer layer (epicarp) so that they do not rot; air spaces in a fibrous mesocarp that trap air. Examples: coconut (which can float across oceans and so grows on coasts), water lily, mangrove.', 'dispersal by water adaptations: buoyancy so that they float; a waterproof outer layer (epicarp) so that they do not rot; air spaces in a fibrous mesocarp that trap air. examples: coconut (which can float across oceans and so grows on coasts), water lily, mangrove. seed and fruit dispersal and parthenocarpy ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-22', 4, 'Dispersal by animals', 'Edible fruits: bright colour, sweet smell and tasty pulp attract animals, which eat them and drop the seeds far away in their dung, where the seeds pass through the gut unharmed (guava, tomato, pepper, pawpaw, bats and birds spread many trees). Hooks and spines catch on fur or clothes (Desmodium, Boerhavia, the ''black-jack'' Bidens pilosa, Triumfetta).', 'dispersal by animals edible fruits: bright colour, sweet smell and tasty pulp attract animals, which eat them and drop the seeds far away in their dung, where the seeds pass through the gut unharmed (guava, tomato, pepper, pawpaw, bats and birds spread many trees). hooks and spines catch on fur or clothes (desmodium, boerhavia, the ''black-jack'' bidens pilosa, triumfetta). seed and fruit dispersal and parthenocarpy ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-22', 5, 'Self-dispersal (explosive mechanism)', 'The fruit wall dries unevenly and builds up tension. When it is ripe and dry, it bursts open suddenly, ''shooting'' the seeds away. Examples: oil bean (Pentaclethra), balsam, rubber seed, okra, and many pods. This throws seeds only a short distance, so they do not travel as far as wind-dispersed seeds.', 'self-dispersal (explosive mechanism) the fruit wall dries unevenly and builds up tension. when it is ripe and dry, it bursts open suddenly, ''shooting'' the seeds away. examples: oil bean (pentaclethra), balsam, rubber seed, okra, and many pods. this throws seeds only a short distance, so they do not travel as far as wind-dispersed seeds. seed and fruit dispersal and parthenocarpy ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-22', 6, 'Why unripe fruits are green and sour', 'Unripe fruits are green, hard and sour, so that animals do not eat them before the seeds are ready. When the seeds are mature, the fruit changes colour, becomes sweet and smells nice, so animals are attracted and spread the seeds.', 'why unripe fruits are green and sour unripe fruits are green, hard and sour, so that animals do not eat them before the seeds are ready. when the seeds are mature, the fruit changes colour, becomes sweet and smells nice, so animals are attracted and spread the seeds. seed and fruit dispersal and parthenocarpy ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-22', 7, 'Parthenocarpy', 'Parthenocarpy is the formation of a fruit without fertilisation, so the fruit has no seeds (it is seedless). Examples: banana and some pineapples. Farmers can cause it by spraying the flowers with plant hormones (auxins) to make seedless grapes, tomatoes or watermelons. This is useful for eating, but the plant cannot reproduce by seed, so banana is grown from suckers.', 'parthenocarpy parthenocarpy is the formation of a fruit without fertilisation, so the fruit has no seeds (it is seedless). examples: banana and some pineapples. farmers can cause it by spraying the flowers with plant hormones (auxins) to make seedless grapes, tomatoes or watermelons. this is useful for eating, but the plant cannot reproduce by seed, so banana is grown from suckers. seed and fruit dispersal and parthenocarpy ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-23', 'Courtship Behaviour in Animals') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-23', 0, 'Courtship Behaviour in Animals: summary', 'Why animals perform courtship, with examples of visual, sound, chemical and territorial displays, including the Agama lizard and the peacock. Key words: Courtship, Instinct, Species recognition, Pheromone, Territory, Display.', 'courtship behaviour in animals: summary why animals perform courtship, with examples of visual, sound, chemical and territorial displays, including the agama lizard and the peacock. key words: courtship, instinct, species recognition, pheromone, territory, display. courtship behaviour in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-23', 1, 'Behaviour matters in reproduction', 'Reproduction is not only about body parts. It also needs behaviour that makes sure the right mates meet and the young survive. These behaviours are mostly instinctive (inborn): the animal does not need to learn them.', 'behaviour matters in reproduction reproduction is not only about body parts. it also needs behaviour that makes sure the right mates meet and the young survive. these behaviours are mostly instinctive (inborn): the animal does not need to learn them. courtship behaviour in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-23', 2, 'What is courtship?', 'Courtship is the series of special actions that a male and female of the same species perform to excite each other before mating.', 'what is courtship? courtship is the series of special actions that a male and female of the same species perform to excite each other before mating. courtship behaviour in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-23', 3, 'Why is courtship necessary?', '1. Species recognition: it makes sure animals mate with their own kind; a female lizard will not respond to the dance of a male toad, so no effort is wasted on mating that would produce no young. 2. Synchronisation: it prepares both partners so that the female releases her eggs at the right time that the male releases sperm. 3. Mate selection: the female can choose a strong, healthy male with good genes (survival of the fittest). 4. Territory: it sets up a safe place for mating and nesting and shows that the male can defend it.', 'why is courtship necessary? 1. species recognition: it makes sure animals mate with their own kind; a female lizard will not respond to the dance of a male toad, so no effort is wasted on mating that would produce no young. 2. synchronisation: it prepares both partners so that the female releases her eggs at the right time that the male releases sperm. 3. mate selection: the female can choose a strong, healthy male with good genes (survival of the fittest). 4. territory: it sets up a safe place for mating and nesting and shows that the male can defend it. courtship behaviour in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-23', 4, 'Kinds of courtship display', 'Visual: bright colours and movements. The male rainbow agama lizard (Agama agama), so common on Nigerian walls and trees, shows an orange-red head with a blue body (the female is a duller brown), nods its head rapidly (head-bobbing) and does ''push-ups''. The male peacock spreads its large, colourful tail feathers in front of the peahen. Sound: frogs and toads croak loudly in the rainy season, and birds sing special mating songs. Crickets chirp. Chemical (pheromones): a pheromone is a chemical signal released by an animal that affects the behaviour of another of the same species. Female moths release pheromones that males can smell kilometres away; dogs and cats mark territory and show readiness with urine. Territorial: fighting and threatening to win and hold a breeding ground, for example male agamas, cocks and antelope.', 'kinds of courtship display visual: bright colours and movements. the male rainbow agama lizard (agama agama), so common on nigerian walls and trees, shows an orange-red head with a blue body (the female is a duller brown), nods its head rapidly (head-bobbing) and does ''push-ups''. the male peacock spreads its large, colourful tail feathers in front of the peahen. sound: frogs and toads croak loudly in the rainy season, and birds sing special mating songs. crickets chirp. chemical (pheromones): a pheromone is a chemical signal released by an animal that affects the behaviour of another of the same species. female moths release pheromones that males can smell kilometres away; dogs and cats mark territory and show readiness with urine. territorial: fighting and threatening to win and hold a breeding ground, for example male agamas, cocks and antelope. courtship behaviour in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-23', 5, 'A correction', 'The lesson note says the male agama has a ''bright blue head and orange tail''. In the common Nigerian rainbow agama it is the other way round: the head is orange-red and the body and tail base are blue. If your own lizards look different, remember that colours can vary between places and species, and always describe what you really see.', 'a correction the lesson note says the male agama has a ''bright blue head and orange tail''. in the common nigerian rainbow agama it is the other way round: the head is orange-red and the body and tail base are blue. if your own lizards look different, remember that colours can vary between places and species, and always describe what you really see. courtship behaviour in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-23', 6, 'Why courtship matters', 'It keeps the species going, because animals must find a mate. It passes on good genes. It reduces the chance of wasted matings and wasted energy. A weak or sick animal is less likely to win a mate.', 'why courtship matters it keeps the species going, because animals must find a mate. it passes on good genes. it reduces the chance of wasted matings and wasted energy. a weak or sick animal is less likely to win a mate. courtship behaviour in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-24', 'Parental Care in Animals') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-24', 0, 'Parental Care in Animals: summary', 'The link between the number of young and the amount of care, with examples from fish, amphibians, reptiles, birds and mammals. Key words: Parental care, Mouth brooding, Incubation, Lactation, Brood parasite.', 'parental care in animals: summary the link between the number of young and the amount of care, with examples from fish, amphibians, reptiles, birds and mammals. key words: parental care, mouth brooding, incubation, lactation, brood parasite. parental care in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-24', 1, 'What is parental care?', 'Parental care means any time, energy or food that parents give to help their young to survive: guarding eggs, building nests, keeping young warm, feeding and protecting them, and teaching them.', 'what is parental care? parental care means any time, energy or food that parents give to help their young to survive: guarding eggs, building nests, keeping young warm, feeding and protecting them, and teaching them. parental care in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-24', 2, 'The trade-off: quantity or quality', 'Low parental care means many eggs. If the parents do not look after the young, most are eaten or die, so thousands of eggs must be made so that a few survive (fish, amphibians). High parental care means few young, because most survive when protected (birds, mammals). That is why a female fish lays thousands of eggs, while a cow gives birth to only one calf a year.', 'the trade-off: quantity or quality low parental care means many eggs. if the parents do not look after the young, most are eaten or die, so thousands of eggs must be made so that a few survive (fish, amphibians). high parental care means few young, because most survive when protected (birds, mammals). that is why a female fish lays thousands of eggs, while a cow gives birth to only one calf a year. parental care in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-24', 3, 'Patterns of care in the animal classes', 'Fish: most lay eggs and leave them. Exception: tilapia is a mouth brooder: the female keeps the fertilised eggs, and later the young, in her mouth until they can fend for themselves. The male seahorse carries the eggs in a brood pouch. Amphibians: toads and frogs lay jelly-covered eggs in water and leave them; the tadpoles live alone. Exception: the male midwife toad carries strings of eggs wound round his legs. Reptiles: most bury their leathery eggs in sand or soil and leave. Exception: the female crocodile guards her nest fiercely and carries the hatchlings to the water in her mouth. Birds: high care. They build nests (the weaver bird weaves a hanging nest), incubate the eggs to keep them warm, feed the chicks with insects, worms or seeds, and defend them. A hen covers her chicks with her wings and scratches the ground to show them food. Mammals: the highest care. Young are born alive (viviparous), fed with milk (lactation), protected for months or years and taught skills, such as lions teaching cubs to hunt, and humans teaching children.', 'patterns of care in the animal classes fish: most lay eggs and leave them. exception: tilapia is a mouth brooder: the female keeps the fertilised eggs, and later the young, in her mouth until they can fend for themselves. the male seahorse carries the eggs in a brood pouch. amphibians: toads and frogs lay jelly-covered eggs in water and leave them; the tadpoles live alone. exception: the male midwife toad carries strings of eggs wound round his legs. reptiles: most bury their leathery eggs in sand or soil and leave. exception: the female crocodile guards her nest fiercely and carries the hatchlings to the water in her mouth. birds: high care. they build nests (the weaver bird weaves a hanging nest), incubate the eggs to keep them warm, feed the chicks with insects, worms or seeds, and defend them. a hen covers her chicks with her wings and scratches the ground to show them food. mammals: the highest care. young are born alive (viviparous), fed with milk (lactation), protected for months or years and taught skills, such as lions teaching cubs to hunt, and humans teaching children. parental care in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-24', 4, 'Comparing a toad and a cat', 'Toad: thousands of eggs, external fertilisation, no parental care. Cat: a few kittens (3 to 5) in a litter, internal fertilisation and development in the uterus, high care with milk and protection.', 'comparing a toad and a cat toad: thousands of eggs, external fertilisation, no parental care. cat: a few kittens (3 to 5) in a litter, internal fertilisation and development in the uterus, high care with milk and protection. parental care in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-24', 5, 'An unusual strategy: brood parasites', 'The cuckoo, a brood parasite, lays its eggs in the nests of other birds, which then bring up the cuckoo chick as their own. The host wastes its energy and food on a stranger, and the cuckoo chick may push the host''s own eggs or chicks out of the nest. In Nigeria, honeyguides and whydahs (viduine finches) are also brood parasites.', 'an unusual strategy: brood parasites the cuckoo, a brood parasite, lays its eggs in the nests of other birds, which then bring up the cuckoo chick as their own. the host wastes its energy and food on a stranger, and the cuckoo chick may push the host''s own eggs or chicks out of the nest. in nigeria, honeyguides and whydahs (viduine finches) are also brood parasites. parental care in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-24', 6, 'The value of reproductive behaviour', 'It ensures that the species continues; passes on good genes; and increases the survival of young so that the population stays steady. Parental care is a sacrifice: the parents spend a lot of energy and food, are more at risk from predators and may lose weight.', 'the value of reproductive behaviour it ensures that the species continues; passes on good genes; and increases the survival of young so that the population stays steady. parental care is a sacrifice: the parents spend a lot of energy and food, are more at risk from predators and may lose weight. parental care in animals ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_title (id, title) VALUES ('NG-SS2-BIO-T3:b23-25', 'Third Term Revision and Exam Practice') ON CONFLICT(id) DO UPDATE SET title = excluded.title;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-25', 0, 'Third Term Revision and Exam Practice: summary', 'A checklist for the term''s nervous system, sense organs, population ecology, ecosystems, human reproduction, seeds and fruits, and animal behaviour, with worked answers. Key words: Revision, Coordination, Population, Ecosystem, Reproduction.', 'third term revision and exam practice: summary a checklist for the term''s nervous system, sense organs, population ecology, ecosystems, human reproduction, seeds and fruits, and animal behaviour, with worked answers. key words: revision, coordination, population, ecosystem, reproduction. third term revision and exam practice ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-25', 1, 'Checklist', 'Nervous coordination: neuron parts; resting and action potential; saltatory conduction; synapse; brain and spinal cord; autonomic nervous system; reflex arc. Sense organs: eye (parts, accommodation, defects); ear (hearing and balance); nose, tongue and skin. Population ecology: density, frequency, distribution; natality, mortality, immigration and emigration; growth curves; limiting factors; quadrat and capture-mark-recapture. Ecosystem: components; food chain and web; the 10% rule; pyramids; carbon and water cycles; balance of nature. Human reproduction: male and female systems; gametes; menstrual cycle; fertilisation, pregnancy and birth. Plants: fertilisation; seed structure; germination; fruit types and dispersal. Behaviour: courtship and parental care.', 'checklist nervous coordination: neuron parts; resting and action potential; saltatory conduction; synapse; brain and spinal cord; autonomic nervous system; reflex arc. sense organs: eye (parts, accommodation, defects); ear (hearing and balance); nose, tongue and skin. population ecology: density, frequency, distribution; natality, mortality, immigration and emigration; growth curves; limiting factors; quadrat and capture-mark-recapture. ecosystem: components; food chain and web; the 10% rule; pyramids; carbon and water cycles; balance of nature. human reproduction: male and female systems; gametes; menstrual cycle; fertilisation, pregnancy and birth. plants: fertilisation; seed structure; germination; fruit types and dispersal. behaviour: courtship and parental care. third term revision and exam practice ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-25', 2, 'Worked answers to common questions', 'Why is a myelinated neuron faster? The action potential jumps from node to node (saltatory conduction) instead of travelling along the whole length of the axon. What happens in the cerebellum damage? The person has jerky movements, loss of balance and poor coordination. Calculation: 40 marked, second catch 60 with 12 marked: N = 40 × 60 ÷ 12 = 200. Why does a pyramid of energy always stand upright? Energy is lost at every level (only about 10% passes on), so each level has less energy than the one below. Why are the testes outside the body? Sperm need a temperature 2 to 3 °C lower than the body. What is the function of the micropyle in a dry seed? It lets water and air enter when germination starts. Why is a maize grain called a fruit? The fruit wall (pericarp) is fused to the seed coat. Why does a female fish lay thousands of eggs and a cow one calf? Fish give no care, so most eggs are lost; a cow gives much care, so most calves survive.', 'worked answers to common questions why is a myelinated neuron faster? the action potential jumps from node to node (saltatory conduction) instead of travelling along the whole length of the axon. what happens in the cerebellum damage? the person has jerky movements, loss of balance and poor coordination. calculation: 40 marked, second catch 60 with 12 marked: n = 40 × 60 ÷ 12 = 200. why does a pyramid of energy always stand upright? energy is lost at every level (only about 10% passes on), so each level has less energy than the one below. why are the testes outside the body? sperm need a temperature 2 to 3 °c lower than the body. what is the function of the micropyle in a dry seed? it lets water and air enter when germination starts. why is a maize grain called a fruit? the fruit wall (pericarp) is fused to the seed coat. why does a female fish lay thousands of eggs and a cow one calf? fish give no care, so most eggs are lost; a cow gives much care, so most calves survive. third term revision and exam practice ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
INSERT INTO kb_chunk (course_id, lesson_id, chunk_idx, title, body, keywords) VALUES ('NG-SS2-BIO-T3', 'NG-SS2-BIO-T3:b23-25', 3, 'Skills to practise', 'Diagrams: neuron, reflex arc, brain, eye, ear, male and female systems, bean seed, maize grain, food web, S-curve. Calculations: population density and capture-recapture. Practicals: blind-spot test, quadrat count, germination experiment. Use active recall, spaced revision and timed past papers, and explain each topic to a friend. For every topic you rate 3 or less out of 5, write one action to improve.', 'skills to practise diagrams: neuron, reflex arc, brain, eye, ear, male and female systems, bean seed, maize grain, food web, s-curve. calculations: population density and capture-recapture. practicals: blind-spot test, quadrat count, germination experiment. use active recall, spaced revision and timed past papers, and explain each topic to a friend. for every topic you rate 3 or less out of 5, write one action to improve. third term revision and exam practice ss2 biology, term 3') ON CONFLICT(lesson_id, chunk_idx) DO UPDATE SET title = excluded.title, body = excluded.body, keywords = excluded.keywords;
